import {
  canRevertDetailActivity,
  type DetailActivity,
  type DetailRecord,
  type DetailRevertHandler,
  detailActivity,
  type RecordDetailsConfig,
} from "./record-details";

export interface TableActivityRecord {
  row: DetailRecord;
  activity: readonly DetailActivity[];
}

/** Reuse the record activity contract, including records no longer in the visible dataset. */
export function createActivityUndo(options: {
  rows: () => readonly DetailRecord[];
  config: () => RecordDetailsConfig | undefined;
  handler: () => DetailRevertHandler | undefined;
  onReverted: () => Promise<void>;
  onSuccess?: (entry: DetailActivity) => void;
  onError: (error?: string) => void;
  onUnavailable: () => void;
}): { undo: () => Promise<void> } {
  let pending = false;
  const completed = new Set<string>();
  return {
    undo: async () => {
      const config = options.config();
      const handler = options.handler();
      if (pending || !config || !handler) {
        return;
      }
      const records =
        config.history?.() ??
        options
          .rows()
          .map((row) => ({ row, activity: detailActivity(config, row) }));
      const candidates = activityCandidates(records, config, completed);
      const candidate = candidates.find((item) => item.allowed);
      if (!candidate) {
        options.onUnavailable();
        return;
      }
      const group = candidate.entry.transactionId
        ? candidates.filter(
            (item) =>
              item.entry.transactionId === candidate.entry.transactionId &&
              !item.reverted
          )
        : [candidate];
      if (group.some((item) => !item.allowed)) {
        options.onUnavailable();
        return;
      }
      pending = true;
      try {
        const changed = await revertGroup(
          group,
          handler,
          completed,
          options.onError
        );
        if (changed) {
          await options.onReverted();
        }
        if (changed === group.length) {
          options.onSuccess?.(candidate.entry);
        }
      } catch (error) {
        options.onError(errorMessage(error));
      } finally {
        pending = false;
      }
    },
  };
}

function errorMessage(error: unknown): string | undefined {
  return error instanceof Error ? error.message : undefined;
}

function activityCandidates(
  records: readonly TableActivityRecord[],
  config: RecordDetailsConfig,
  completed: Set<string>
) {
  return records
    .flatMap(({ row, activity }) => {
      const sorted = [...activity].sort(
        (a, b) => Date.parse(b.at) - Date.parse(a.at)
      );
      return sorted.map((entry) => ({
        row,
        entry,
        reverted:
          completed.has(entry.id) ||
          activity.some((item) => item.reverts === entry.id),
        allowed:
          !completed.has(entry.id) &&
          canRevertDetailActivity(entry, sorted) &&
          config.canRevert?.(entry, row) !== false,
      }));
    })
    .sort((a, b) => Date.parse(b.entry.at) - Date.parse(a.entry.at));
}

async function revertGroup(
  group: ReturnType<typeof activityCandidates>,
  handler: DetailRevertHandler,
  completed: Set<string>,
  onError: (error?: string) => void
): Promise<number> {
  let changed = 0;
  try {
    for (const item of group) {
      const result = await handler(item.row, item.entry);
      if (!result.success) {
        onError(result.error);
        break;
      }
      completed.add(item.entry.id);
      changed += 1;
    }
  } catch (error) {
    onError(errorMessage(error));
  }
  // Partial success must refresh before the remaining members can be retried.
  return changed;
}

const SCROLLABLE_OVERFLOW = /auto|scroll|hidden/;

/** Bound the numeric page size sent to both local and server-backed tables. */
export function fitPageSize(
  availableHeight: number,
  rowHeight: number
): number {
  if (
    !(Number.isFinite(availableHeight) && Number.isFinite(rowHeight)) ||
    rowHeight <= 0
  ) {
    return 1;
  }
  return Math.max(
    1,
    Math.min(500, Math.floor(Math.max(0, availableHeight) / rowHeight))
  );
}

/** Count measured rows in order, then estimate unseen rows using the smallest visible row. */
export function fitMeasuredPageSize(
  availableHeight: number,
  heights: number[]
): number {
  const measured = heights.filter(
    (height) => Number.isFinite(height) && height > 0
  );
  if (!measured.length) {
    return 1;
  }
  let remaining = Math.max(0, availableHeight);
  let count = 0;
  for (const height of measured) {
    if (height > remaining) {
      return Math.max(1, count);
    }
    remaining -= height;
    count += 1;
    if (count === 500) {
      return count;
    }
  }
  return Math.min(500, count + Math.floor(remaining / Math.min(...measured)));
}

export interface AutoPageMeasurement {
  pageSize: number;
  tableHeight: number;
  layoutKey: string;
}

/** Observe layout, not scroll position, so scrolling to the selector does not change the capacity. */
export function observeAutoPageSize(
  root: HTMLElement,
  onMeasure: (value: AutoPageMeasurement) => void
): () => void {
  const win = root.ownerDocument.defaultView;
  if (!win) {
    return () => undefined;
  }
  let disposed = false;
  let frame = 0;
  const ancestors: HTMLElement[] = [];
  for (
    let element = root.parentElement;
    element;
    element = element.parentElement
  ) {
    ancestors.push(element);
  }
  const measure = () => {
    frame = 0;
    if (disposed || !root.isConnected || !root.getClientRects().length) {
      return;
    }
    const table = root.querySelector("table");
    const body = table?.querySelector("tbody");
    if (!(table && body)) {
      return;
    }
    const rows = [...body.querySelectorAll("tr")].filter(
      (row) => row.querySelector("td")?.colSpan === 1
    );
    // Intrinsic table width can change between pages; only the container is a layout boundary.
    const width = root.getBoundingClientRect().width;
    const heights = rows
      .map((row) => row.getBoundingClientRect().height)
      .filter((height) => height > 0);
    if (!heights.length) {
      return;
    }
    const scroller = ancestors.find((element) => {
      const style = win.getComputedStyle(element);
      return (
        SCROLLABLE_OVERFLOW.test(style.overflowY) &&
        element.clientHeight < element.scrollHeight
      );
    });
    const viewportHeight =
      scroller?.clientHeight ?? win.visualViewport?.height ?? win.innerHeight;
    const origin = scroller
      ? scroller.getBoundingClientRect().top +
        scroller.clientTop -
        scroller.scrollTop
      : -win.scrollY;
    const tableTop = Math.max(0, table.getBoundingClientRect().top - origin);
    const bodyTop = Math.max(0, body.getBoundingClientRect().top - origin);
    const footer = root.querySelector<HTMLElement>("[data-yayaw-pagination]");
    const footerHeight = footer?.getBoundingClientRect().height ?? 48;
    const calculationsHeight =
      table.querySelector("tfoot")?.getBoundingClientRect().height ?? 0;
    const tableHeight = Math.max(
      80,
      viewportHeight - tableTop - footerHeight - 24
    );
    const available =
      viewportHeight - bodyTop - footerHeight - calculationsHeight - 24;
    onMeasure({
      pageSize: fitMeasuredPageSize(available, heights),
      tableHeight,
      // Header wrapping and footer content can vary between pages just like row heights.
      // They affect measured capacity, but must not raise the existing capacity ceiling.
      layoutKey: [viewportHeight, width].join(":"),
    });
  };
  const schedule = () => {
    if (!(disposed || frame)) {
      frame = win.requestAnimationFrame(measure);
    }
  };
  const resize =
    typeof win.ResizeObserver === "function"
      ? new win.ResizeObserver(schedule)
      : undefined;
  resize?.observe(root);
  for (const ancestor of ancestors) {
    resize?.observe(ancestor);
  }
  const mutation = new win.MutationObserver(schedule);
  mutation.observe(root, {
    childList: true,
    subtree: true,
    attributes: true,
    attributeFilter: ["class", "style"],
  });
  win.addEventListener("resize", schedule);
  win.visualViewport?.addEventListener("resize", schedule);
  root.addEventListener("load", schedule, true);
  root.ownerDocument.fonts?.ready.then(schedule, schedule);
  schedule();
  return () => {
    disposed = true;
    win.cancelAnimationFrame(frame);
    resize?.disconnect();
    mutation.disconnect();
    win.removeEventListener("resize", schedule);
    win.visualViewport?.removeEventListener("resize", schedule);
    root.removeEventListener("load", schedule, true);
  };
}

import type { BulkActionResult, TableRecord } from "./types";

export interface ResolvedBulkActionResult {
  success: boolean;
  clearSelection: boolean;
  closeMenu: boolean;
  message?: string;
}

export const resolveBulkActionResult = (
  result: BulkActionResult | undefined,
  failureMessage: string,
  defaults = { clearSelection: false, closeMenu: true }
): ResolvedBulkActionResult => {
  const success = result?.success !== false;
  return {
    success,
    clearSelection:
      result?.clearSelection ??
      result?.closeMenu ??
      (success && defaults.clearSelection),
    closeMenu: result?.closeMenu ?? (success && defaults.closeMenu),
    message:
      result?.message?.trim() ||
      result?.error?.trim() ||
      (success ? undefined : failureMessage),
  };
};

export const parseBulkEditPatch = (input: string): TableRecord => {
  const patch: unknown = JSON.parse(input);
  if (patch === null || typeof patch !== "object" || Array.isArray(patch)) {
    throw new Error("Enter a valid JSON object.");
  }
  return patch as TableRecord;
};

/** Shared copy and clear-value conventions for both independently installed registries. */
export const bulkEditorMessages = (locale = "en") =>
  locale.startsWith("fr")
    ? {
        titleOne: "Modifier 1 ligne",
        titleMany: "Modifier {count} lignes",
        applyOne: "Appliquer à 1 ligne",
        applyMany: "Appliquer à {count} lignes",
        description: "Les autres propriétés restent inchangées.",
        addField: "Ajouter un champ",
        searchFields: "Rechercher une propriété…",
        noFields: "Aucune propriété disponible",
        empty: "Ajoutez les propriétés à modifier.",
        removeField: "Retirer {field}",
        clearValue: "Effacer la valeur",
        cancel: "Annuler",
        close: "Fermer",
        saving: "Enregistrement…",
      }
    : {
        titleOne: "Edit 1 row",
        titleMany: "Edit {count} rows",
        applyOne: "Apply to 1 row",
        applyMany: "Apply to {count} rows",
        description: "Other properties stay unchanged.",
        addField: "Add a field",
        searchFields: "Search properties…",
        noFields: "No properties available",
        empty: "Add the properties you want to change.",
        removeField: "Remove {field}",
        clearValue: "Clear value",
        cancel: "Cancel",
        close: "Close",
        saving: "Saving…",
      };
export type BulkEditorMessages = ReturnType<typeof bulkEditorMessages>;

/** Required fields and boolean/custom editors never imply a clear operation. */
export function bulkClearCandidate(field: {
  type: string;
  required?: boolean;
}): { value: unknown } | undefined {
  if (field.required) {
    return;
  }
  switch (field.type) {
    case "text":
    case "string":
    case "textarea":
    case "url":
    case "image":
      return { value: "" };
    case "multiSelect":
    case "collection":
      return { value: [] };
    case "number":
    case "date":
    case "json":
    case "select":
    case "radio":
    case "select-with-add-new":
      return { value: null };
    default:
      return;
  }
}

import { bulkClearCandidate } from "./bulk-editor";
import {
  cloneFormValue,
  fieldIsDisabled,
  fieldIsHidden,
  formValuesEqual,
  validateForm,
} from "./form-runtime";
import type {
  FormConfig,
  FormFieldContext,
  FormFieldDefinition,
  TableRecord,
} from "./types";

const reservedFields = new Set([
  "id",
  "_id",
  "createdAt",
  "updatedAt",
  "created_at",
  "updated_at",
]);

/** Start with common values, never the first row's differing values. */
export const commonBulkValues = (rows: readonly TableRecord[]): TableRecord =>
  cloneFormValue(
    Object.fromEntries(
      Object.entries(rows[0] ?? {}).filter(([key, value]) =>
        rows.every((row) => formValuesEqual(row[key], value))
      )
    )
  );

/** Check conditional fields against every target, including explicitly changed dependencies. */
export const bulkFieldEditable = (
  field: FormFieldDefinition,
  context: FormFieldContext
): boolean => {
  if (reservedFields.has(field.name) || field.bulkEdit === false) {
    return false;
  }
  const patch = Object.fromEntries(
    (context.bulkEdit?.fields ?? []).map((name) => [name, context.values[name]])
  );
  return (context.bulkEdit?.rows ?? []).every((row) => {
    const rowContext = { ...context, row, values: { ...row, ...patch } };
    return !(
      fieldIsHidden(field, rowContext) || fieldIsDisabled(field, rowContext)
    );
  });
};

/** Keep field validation, but not a full-row schema that requires untouched fields. */
export const bulkFormConfig = (
  config: FormConfig,
  context: FormFieldContext
): FormConfig => ({
  ...config,
  schema: undefined,
  submitMode: "full",
  fields: config.fields
    .filter(
      (field) =>
        context.bulkEdit?.fields.includes(field.name) &&
        bulkFieldEditable(field, context)
    )
    .sort(
      (left, right) =>
        (context.bulkEdit?.fields.indexOf(left.name) ?? 0) -
        (context.bulkEdit?.fields.indexOf(right.name) ?? 0)
    )
    .map((field) => ({ ...field, hidden: false, disabled: false })),
});

/** Strip untouched fields before validation and transforms, including undeclared row metadata. */
export const bulkFormValues = (
  config: FormConfig,
  values: TableRecord
): TableRecord =>
  cloneFormValue(
    Object.fromEntries(
      config.fields.map((field) => [field.name, values[field.name]])
    )
  );

/** Invalid completion reports must never clear unrelated rows or cause a silent success. */
export const bulkCompletion = (
  ids: string[],
  result: { success: boolean; failedIds?: string[] }
): { completed: string[]; remaining: string[] } => {
  if (result.success) {
    return { completed: [...ids], remaining: [] };
  }
  const failed = result.failedIds;
  if (!failed?.length || failed.some((id) => !ids.includes(id))) {
    return { completed: [], remaining: [...ids] };
  }
  return {
    completed: ids.filter((id) => !failed.includes(id)),
    remaining: ids.filter((id) => failed.includes(id)),
  };
};

/** Validate drafts without publishing them; reject unsupported clears through the field schema. */
export async function validateBulkDraft(
  config: FormConfig,
  context: FormFieldContext
) {
  const values = context.values ?? {};
  const [draft, candidates] = await Promise.all([
    validateForm(config, bulkFormValues(config, values), context),
    Promise.all(
      config.fields.map(async (field) => {
        const candidate = bulkClearCandidate(field);
        if (!candidate) {
          return;
        }
        const result = await validateForm(
          { ...config, schema: undefined, fields: [field] },
          { [field.name]: candidate.value },
          { ...context, values: { ...values, [field.name]: candidate.value } }
        );
        return Object.keys(result.errors).length
          ? undefined
          : ([field.name, candidate.value] as const);
      })
    ),
  ]);
  const clearValues: TableRecord = {};
  for (const candidate of candidates) {
    if (candidate) {
      clearValues[candidate[0]] = candidate[1];
    }
  }
  return {
    valid: config.fields.length > 0 && !Object.keys(draft.errors).length,
    clearValues,
  };
}

/**
 * Calendar view model shared by the React and Vue editions. It has no
 * calendar-library dependency: the optional calendar registry items render it.
 */
import { type DateRangeScope, localDayKey } from "./scoped-rows";

export type CalendarLayout = "month" | "week" | "list";

export interface CalendarViewSettings {
  /** Column holding the start date, or the only date. */
  dateColumn?: string;
  /** Column holding an inclusive end date; one-day events without it. */
  endColumn?: string;
  /** Column used as the event title. */
  titleColumn?: string;
  /** Column whose tag color colors the event. */
  colorColumn?: string;
  layout?: CalendarLayout;
  /** First day of the week, 0 = Sunday … 6 = Saturday (default Monday). */
  weekStartsOn?: number;
  showWeekends?: boolean;
  /** Drag an event to another day (needs `actions.update`). */
  allowDragUpdate?: boolean;
  /** Stretch an event to change its end (needs an end column). */
  allowResize?: boolean;
  /** Click a day to create a record on it (needs `actions.create`). */
  allowCreate?: boolean;
}

export const CALENDAR_DEFAULTS = {
  layout: "month",
  weekStartsOn: 1,
  showWeekends: true,
  allowDragUpdate: true,
  allowResize: true,
  allowCreate: true,
} as const satisfies CalendarViewSettings;

type ResolvedCalendarSettings = CalendarViewSettings &
  Required<
    Pick<
      CalendarViewSettings,
      | "allowCreate"
      | "allowDragUpdate"
      | "allowResize"
      | "layout"
      | "showWeekends"
      | "weekStartsOn"
    >
  >;

const LAYOUTS = new Set<CalendarLayout>(["month", "week", "list"]);
const STRING_KEYS = [
  "dateColumn",
  "endColumn",
  "titleColumn",
  "colorColumn",
] as const;
const BOOLEAN_KEYS = [
  "showWeekends",
  "allowDragUpdate",
  "allowResize",
  "allowCreate",
] as const;
const DAYS_IN_WEEK = 7;
const DAY_MS = 86_400_000;
const DATE_ONLY = /^\d{4}-\d{2}-\d{2}$/;

/** Keep only valid calendar settings; unknown or malformed values are dropped. */
export function normalizeCalendarViewConfig(
  value: unknown
): CalendarViewSettings | undefined {
  if (!value || typeof value !== "object") {
    return;
  }
  const input = value as Record<string, unknown>;
  const normalized: CalendarViewSettings = {};
  for (const key of STRING_KEYS) {
    const text = typeof input[key] === "string" ? input[key].trim() : "";
    if (text) {
      normalized[key] = text;
    }
  }
  for (const key of BOOLEAN_KEYS) {
    if (typeof input[key] === "boolean") {
      normalized[key] = input[key];
    }
  }
  if (LAYOUTS.has(input.layout as CalendarLayout)) {
    normalized.layout = input.layout as CalendarLayout;
  }
  const weekStart = Number(input.weekStartsOn);
  if (
    input.weekStartsOn !== undefined &&
    Number.isInteger(weekStart) &&
    weekStart >= 0 &&
    weekStart < DAYS_IN_WEEK
  ) {
    normalized.weekStartsOn = weekStart;
  }
  return Object.keys(normalized).length ? normalized : undefined;
}

interface CalendarColumn {
  id: string;
  type?: string;
}

/** Table defaults, then the view; the first date column when none is chosen. */
export function resolveCalendarSettings(
  columns: readonly CalendarColumn[],
  defaults: CalendarViewSettings | undefined,
  view: CalendarViewSettings | undefined
): ResolvedCalendarSettings {
  const merged = { ...CALENDAR_DEFAULTS, ...defaults, ...view };
  const dataColumns = columns.filter(
    (column) => column.id !== "select" && column.id !== "actions"
  );
  return {
    ...merged,
    dateColumn:
      merged.dateColumn ??
      dataColumns.find((column) => column.type === "date")?.id,
    titleColumn:
      merged.titleColumn ??
      dataColumns.find((column) => column.type !== "date")?.id,
  };
}

export interface CalendarEvent {
  id: string;
  title: string;
  /** Local calendar day (`YYYY-MM-DD`). */
  start: string;
  /** Exclusive end day, as calendar libraries expect for all-day events. */
  end: string;
  allDay: true;
  /** Value of the color column, for tag coloring. */
  colorValue?: string;
}

/** Year, month index and day of a `YYYY-MM-DD` string. */
function dayParts(day: string): [number, number, number] {
  const [year = 0, month = 1, date = 1] = day.split("-").map(Number);
  return [year, month - 1, date];
}

/** `YYYY-MM-DD` plus a number of days, in local calendar arithmetic. */
export function addDays(day: string, days: number): string {
  const [year, month, date] = dayParts(day);
  const shifted = new Date(year, month, date + days);
  return localDayKey(shifted) ?? day;
}

/** Whole days from one `YYYY-MM-DD` to another. */
export function daysBetween(from: string, to: string): number {
  const toTime = (day: string) => Date.UTC(...dayParts(day));
  return Math.round((toTime(to) - toTime(from)) / DAY_MS);
}

/** Rows with a start date become all-day events; an end before the start is ignored. */
export function calendarEvents(
  rows: readonly Record<string, unknown>[],
  settings: CalendarViewSettings,
  getRowId: (row: Record<string, unknown>) => string
): CalendarEvent[] {
  if (!settings.dateColumn) {
    return [];
  }
  return rows.flatMap((row) => {
    const start = localDayKey(row[settings.dateColumn as string]);
    if (!start) {
      return [];
    }
    const lastDay =
      (settings.endColumn && localDayKey(row[settings.endColumn])) || start;
    const last = lastDay < start ? start : lastDay;
    const title = settings.titleColumn ? row[settings.titleColumn] : undefined;
    const color = settings.colorColumn ? row[settings.colorColumn] : undefined;
    return [
      {
        id: getRowId(row),
        title: title === null || title === undefined ? "" : String(title),
        start,
        end: addDays(last, 1),
        allDay: true as const,
        colorValue:
          color === null || color === undefined ? undefined : String(color),
      },
    ];
  });
}

/** The rows a visible calendar range needs, as a list scope. */
export function calendarScope(
  settings: CalendarViewSettings,
  visibleStart: Date,
  visibleEndExclusive: Date
): DateRangeScope | undefined {
  const from = localDayKey(visibleStart);
  const end = localDayKey(visibleEndExclusive);
  if (!(settings.dateColumn && from && end)) {
    return;
  }
  return {
    kind: "dateRange",
    field: settings.dateColumn,
    endField: settings.endColumn,
    from,
    to: addDays(end, -1),
  };
}

/** Write a day in the stored value's own format: date-only stays date-only. */
function formatLike(original: unknown, day: string): string {
  if (typeof original === "string" && !DATE_ONLY.test(original)) {
    const previous = new Date(original);
    if (Number.isFinite(previous.getTime())) {
      previous.setFullYear(...dayParts(day));
      return previous.toISOString();
    }
  }
  return day;
}

/**
 * The patch for an event moved or stretched to a new exclusive range. Without
 * an end column, only the start moves and stretching is not possible.
 */
export function calendarMovePatch(
  row: Record<string, unknown>,
  settings: CalendarViewSettings,
  start: string,
  endExclusive: string
): Record<string, unknown> {
  if (!settings.dateColumn) {
    return {};
  }
  const patch: Record<string, unknown> = {
    [settings.dateColumn]: formatLike(row[settings.dateColumn], start),
  };
  if (settings.endColumn) {
    const last = addDays(endExclusive, -1);
    patch[settings.endColumn] = formatLike(
      row[settings.endColumn],
      last < start ? start : last
    );
  }
  return patch;
}

import type { ColumnPinningState, ColumnVisibilityState } from "./types";

const reserved = (id: string): boolean => id === "select" || id === "actions";
const ids = (value: unknown, allowed: string[]): string[] =>
  Array.isArray(value)
    ? [
        ...new Set(
          value.filter(
            (id): id is string =>
              typeof id === "string" && allowed.includes(id) && !reserved(id)
          )
        ),
      ]
    : [];

/** Utility columns cannot be moved, hidden, or unpinned by saved or URL state. */
export const lockedColumnOrder = (
  value: unknown,
  allowed: string[]
): string[] => [
  "select",
  ...new Set([
    ...ids(value, allowed),
    ...allowed.filter((id) => !reserved(id)),
  ]),
  "actions",
];

export const lockedColumnVisibility = (
  value: ColumnVisibilityState,
  mandatory: string[]
): ColumnVisibilityState => ({
  ...value,
  ...Object.fromEntries(
    [...mandatory, "select", "actions"].map((id) => [id, true])
  ),
});

export const lockedColumnPinning = (
  value: ColumnPinningState | undefined,
  allowed: string[],
  enabled = true
): ColumnPinningState => {
  const left = enabled ? ids(value?.left, allowed) : [];
  const right = enabled
    ? ids(value?.right, allowed).filter((id) => !left.includes(id))
    : [];
  return { left: ["select", ...left], right: [...right, "actions"] };
};

import {
  CalendarDays,
  ChartGantt,
  Columns3,
  Images,
  List,
  Table2,
} from "lucide-vue-next";
import type { Component } from "vue";
import type { TableDisplayMode } from "../../types";

export const displayModeIcons: Record<TableDisplayMode, Component> = {
  calendar: CalendarDays,
  gantt: ChartGantt,
  table: Table2,
  kanban: Columns3,
  gallery: Images,
  list: List,
};

import type { InjectionKey, ShallowRef } from "vue";

export interface SettingsNavigation {
  title: string;
  back: () => void;
}
/** A nested settings screen reuses the enclosing popover/drawer header. */
export const settingsNavigationKey: InjectionKey<
