> = Symbol("settings-navigation");

import { onBeforeUnmount, onMounted, type Ref, ref, watch } from "vue";
import {
  type AutoPageMeasurement,
  observeAutoPageSize,
} from "../auto-page-size";
import { useTableContext } from "../context";

export function useAutoPageSize(root: Ref<HTMLElement | undefined>) {
  const context = useTableContext();
  const defaultAutomatic = Boolean(
    context.config.table.enablePagination !== false &&
      context.config.table.enableAutoPageSize &&
      context.config.table.defaultAutoPageSize
  );
  const automatic = ref(defaultAutomatic);
  const measurement = ref<AutoPageMeasurement>();
  let expectedSize: number | undefined;
  let fitKey = "";
  let stop: (() => void) | undefined;
  let mounted = false;
  const setPageSize = (pageSize: number) => {
    const previous = context.state.pagination.value;
    expectedSize = pageSize;
    if (previous.pageSize !== pageSize) {
      context.state.pagination.value = {
        pageIndex: Math.floor(
          (previous.pageIndex * previous.pageSize) / pageSize
        ),
        pageSize,
      };
    }
  };
  const observe = () => {
    stop?.();
    if (!(mounted && root.value && context.config.table.enableAutoPageSize)) {
      return;
    }
    stop = observeAutoPageSize(root.value, (value) => {
      if (
        measurement.value?.layoutKey !== value.layoutKey ||
        measurement.value?.pageSize !== value.pageSize ||
        measurement.value?.tableHeight !== value.tableHeight
      ) {
        measurement.value = value;
      }
      if (automatic.value) {
        const nextFitKey = `${context.state.density.value}:${value.layoutKey}`;
        // Keep the capacity stable across pages with different row heights.
        const size =
          fitKey === nextFitKey
            ? Math.min(value.pageSize, expectedSize ?? value.pageSize)
            : value.pageSize;
        fitKey = nextFitKey;
        setPageSize(size);
      }
    });
  };
  onMounted(() => {
    mounted = true;
    observe();
  });
  onBeforeUnmount(() => {
    mounted = false;
    stop?.();
  });
  watch(() => context.state.density.value, observe);
  watch(
    () => context.state.activeViewId.value,
    () => {
      expectedSize = undefined;
      fitKey = "";
      automatic.value = defaultAutomatic;
      observe();
    }
  );
  watch(
    () => context.state.pagination.value.pageSize,
    (value) => {
      if (
        automatic.value &&
        expectedSize !== undefined &&
        value !== expectedSize
      ) {
        automatic.value = false;
      }
    }
  );
  const selectSize = (value: string) => {
    automatic.value = value === "auto";
    fitKey = `${context.state.density.value}:${measurement.value?.layoutKey}`;
    const size = automatic.value ? measurement.value?.pageSize : Number(value);
    if (size && Number.isInteger(size) && size > 0) {
      setPageSize(size);
    }
  };
  return { automatic, measurement, selectSize };
}

import { computed } from "vue";
import { useTableContext } from "../context";
import { applyTableQuery } from "../core";

/** Cards and the grid use the same page state; server pages must never be sliced twice. */
export const useCardRows = () => {
  const context = useTableContext();
  return computed(() => {
    if (context.data.isServer.value) {
      return context.data.rows.value;
    }
    const rows = applyTableQuery(context.data.rows.value, {
      columns: context.config.columns.definitions,
      search: context.state.search.value,
      filters: context.state.filters.value,
      advancedFilters: context.state.advancedFilters.value,
      sorting: context.state.sorting.value,
    });
    if (!context.config.table.enablePagination) {
      return rows;
    }
    const { pageIndex, pageSize } = context.state.pagination.value;
    return rows.slice(pageIndex * pageSize, (pageIndex + 1) * pageSize);
  });
};

import { computed, onBeforeUnmount, onMounted, ref, watch } from "vue";
import {
  cloneFormValue,
  fieldIsDisabled,
  fieldIsHidden,
} from "../form-runtime";
import type {
  FormFieldContext,
  FormFieldDefinition,
  SelectOption,
} from "../types";

/** Keep option requests scoped to the field's declared dependencies. */
export const useFieldOptions = (input: {
  field: () => FormFieldDefinition;
  context: () => FormFieldContext;
  value: () => unknown;
}) => {
  const query = ref("");
  const base = ref<SelectOption[]>([]);
  const searched = ref<SelectOption[]>([]);
  const resolved = ref<SelectOption[]>([]);
  const created = ref<SelectOption[]>([]);
  const loading = ref(false);
  const error = ref<string>();
  const mounted = ref(false);
  let baseLoaded = false;
  let generation = 0;
  let controller: AbortController | undefined;
  let timer: ReturnType<typeof setTimeout> | undefined;
  const values = (): unknown[] => {
    const value = input.value();
    return Array.isArray(value)
      ? value
      : [value].filter(
          (item) => item !== undefined && item !== null && item !== ""
        );
  };
  const options = computed(() => {
    const configured = Array.isArray(input.field().options)
      ? (input.field().options as SelectOption[])
      : [];
    const all = [
      ...configured,
      ...base.value,
      ...searched.value,
      ...resolved.value,
      ...created.value,
    ];
    return all.filter(
      (option, index) =>
        all.findIndex((candidate) =>
          Object.is(candidate.value, option.value)
        ) === index
    );
  });
  const active = () =>
    mounted.value &&
    !fieldIsHidden(input.field(), input.context()) &&
    !fieldIsDisabled(input.field(), input.context());
  const rememberSelection = () => {
    const selected = options.value.filter((option) =>
      values().some((value) => Object.is(value, option.value))
    );
    for (const option of selected) {
      if (
        !resolved.value.some((known) => Object.is(known.value, option.value))
      ) {
        resolved.value.push(option);
      }
    }
  };
  const invalidate = () => {
    generation += 1;
    controller?.abort();
    if (timer) {
      clearTimeout(timer);
    }
    loading.value = false;
  };
  const loadBase = async (
    field: FormFieldDefinition,
    context: FormFieldContext
  ): Promise<SelectOption[]> => {
    if (baseLoaded) {
      return base.value;
    }
    const configured =
      typeof field.options === "function"
        ? await field.options(context)
        : (field.options ?? []);
    const legacy = field.optionsLoader
      ? (await field.optionsLoader()).map((value) => ({ value, label: value }))
      : [];
    return [...configured, ...legacy];
  };
  const populate = async (
    field: FormFieldDefinition,
    context: FormFieldContext,
    text: string,
    signal: AbortSignal,
    current: () => boolean
  ): Promise<void> => {
    const nextBase = await loadBase(field, context);
    if (!current()) {
      return;
    }
    base.value = nextBase;
    baseLoaded = true;
    const known = [...nextBase, ...created.value, ...resolved.value];
    const selected = values().filter(
      (value) => !known.some((option) => Object.is(value, option.value))
    );
    if (selected.length && field.resolveOptions) {
      const next = await field.resolveOptions(selected, context, signal);
      if (!current()) {
        return;
      }
      resolved.value = [...resolved.value, ...next];
    }
    if (
      field.searchOptions &&
      text.length >= Math.max(1, field.searchMinLength ?? 3)
    ) {
      const next = await field.searchOptions(text, context, signal);
      if (!current()) {
        return;
      }
      searched.value = next;
    }
  };
  const load = async (): Promise<void> => {
    invalidate();
    if (!active()) {
      return;
    }
    const version = generation;
    const request = new AbortController();
    controller = request;
    loading.value = true;
    error.value = undefined;
    const field = input.field();
    const context = {
      ...input.context(),
      values: cloneFormValue(input.context().values),
    };
    const text = query.value.trim();
    const current = () => generation === version && !request.signal.aborted;
    try {
      await populate(field, context, text, request.signal, current);
    } catch (cause) {
      if (current()) {
        error.value = cause instanceof Error ? cause.message : String(cause);
      }
    } finally {
      if (current()) {
        loading.value = false;
      }
    }
  };
  watch(
    () =>
      JSON.stringify([
        input.field().name,
        input.field().optionsScope,
        Array.isArray(input.field().options)
          ? input.field().options
          : undefined,
        (input.field().optionDependencies ?? []).map(
          (name) => input.context().values[name]
        ),
      ]),
    async () => {
      invalidate();
      baseLoaded = false;
      base.value = [];
      searched.value = [];
      resolved.value = [];
      created.value = [];
      error.value = undefined;
      query.value = "";
      await load();
    }
  );
  watch(active, async (enabled) => {
    if (enabled) {
      await load();
    } else {
      invalidate();
    }
  });
  watch(
    query,
    () => {
      invalidate();
      rememberSelection();
      searched.value = [];
      if (!(active() && query.value.trim())) {
        return;
      }
      timer = setTimeout(
        load,
        Math.max(0, input.field().searchDebounceMs ?? 300)
      );
    },
    { flush: "sync" }
  );
  watch(
    () => JSON.stringify(values()),
    async () => {
      rememberSelection();
      if (
        input.field().resolveOptions &&
        values().some(
          (value) =>
            !options.value.some((option) => Object.is(value, option.value))
        )
      ) {
        await load();
      }
    }
  );
  const reload = async () => {
    baseLoaded = false;
    await load();
  };
  onMounted(() => {
    mounted.value = true;
  });
  onBeforeUnmount(invalidate);
  return { query, options, created, loading, error, reload };
};

import { computed } from "vue";
import { useTableContext } from "../context";
import type {
  TableGalleryAspectRatio,
  TableGalleryCardSize,
  TableGalleryImageFit,
} from "../types";

export function useGallerySettings() {
  const context = useTableContext();
  const translate = (key: string, fallback: string) =>
    String(context.translations.value[key] ?? fallback);
  const columns = computed(() =>
    context.config.columns.definitions.filter(
      (column) => !["select", "actions"].includes(column.id)
    )
  );
  const columnOptions = computed(() =>
    columns.value.map((column) => ({ value: column.id, label: column.header }))
  );
  const imageOptions = computed(() => [
    { value: "", label: translate("none", "None") },
    ...columnOptions.value,
  ]);
  const ratioOptions = computed(() => [
    { value: "square" as const, label: translate("cardSquare", "Square") },
    {
      value: "portrait" as const,
      label: translate("cardPortrait", "Portrait"),
    },
    { value: "video" as const, label: translate("cardVideo", "Video") },
    { value: "wide" as const, label: translate("cardWide", "Wide") },
  ]);
  const fitOptions = computed(() => [
    { value: "cover" as const, label: translate("cardCover", "Cover") },
    { value: "contain" as const, label: translate("cardContain", "Contain") },
  ]);
  const sizeOptions = computed(() => [
    { value: "small" as const, label: translate("cardSmall", "Small") },
    { value: "medium" as const, label: translate("cardMedium", "Medium") },
    { value: "large" as const, label: translate("cardLarge", "Large") },
  ]);
  const imageColumn = computed({
    get: () =>
      context.state.gallery.value.imageColumn ??
      context.config.table.gallery?.imageColumn ??
      columns.value.find((column) => column.type === "image")?.id ??
      "",
    set: (value: string) => {
      context.state.gallery.value = {
        ...context.state.gallery.value,
        imageColumn: value,
      };
    },
  });
  const titleColumn = computed({
    get: () =>
      context.state.gallery.value.titleColumn ??
      context.config.table.gallery?.titleColumn ??
      columns.value.find((column) => column.id !== imageColumn.value)?.id ??
      "id",
    set: (value: string) => {
      context.state.gallery.value = {
        ...context.state.gallery.value,
        titleColumn: value,
      };
    },
  });
  const propertyIds = computed({
    get: () =>
      context.state.gallery.value.cardColumnIds ??
      context.config.table.gallery?.cardColumnIds ??
      columns.value
        .filter(
          (column) =>
            ![imageColumn.value, titleColumn.value].includes(column.id)
        )
        .slice(0, 4)
        .map((column) => column.id),
    set: (value: string[]) => {
      context.state.gallery.value = {
        ...context.state.gallery.value,
        cardColumnIds: value,
      };
    },
  });
  const aspectRatio = computed({
    get: () =>
      context.state.gallery.value.aspectRatio ??
      context.config.table.gallery?.aspectRatio ??
      "wide",
    set: (value: TableGalleryAspectRatio) => {
      context.state.gallery.value = {
        ...context.state.gallery.value,
        aspectRatio: value,
      };
    },
  });
  const imageFit = computed({
    get: () =>
      context.state.gallery.value.imageFit ??
      context.config.table.gallery?.imageFit ??
      "cover",
    set: (value: TableGalleryImageFit) => {
      context.state.gallery.value = {
        ...context.state.gallery.value,
        imageFit: value,
      };
    },
  });
  const cardSize = computed({
    get: () =>
      context.state.gallery.value.cardSize ??
      context.config.table.gallery?.cardSize ??
      "medium",
    set: (value: TableGalleryCardSize) => {
      context.state.gallery.value = {
        ...context.state.gallery.value,
        cardSize: value,
      };
    },
  });
  const previewSize = computed({
    get: () =>
      context.state.gallery.value.previewSize ??
      context.config.table.gallery?.previewSize ??
      "medium",
    set: (value: TableGalleryCardSize) => {
      context.state.gallery.value = {
        ...context.state.gallery.value,
        previewSize: value,
      };
    },
  });
  const showLabels = computed({
    get: () =>
      context.state.gallery.value.showCardLabels ??
      context.config.table.gallery?.showCardLabels ??
      false,
    set: (value: boolean) => {
      context.state.gallery.value = {
        ...context.state.gallery.value,
        showCardLabels: value,
      };
    },
  });

  return {
    context,
    translate,
    columns,
    columnOptions,
    titleColumn,
    propertyIds,
    showLabels,
    imageOptions,
    ratioOptions,
    fitOptions,
    sizeOptions,
    imageColumn,
    aspectRatio,
    imageFit,
    cardSize,
    previewSize,
  };
}

