  /** Views rendered by optional registry items, such as the calendar. */
  displayModeRenderers?: DisplayModeRenderers;
  openEdit: (row: TData) => void;
  openDetails?: (row: TData) => void;
  activateRow: (row: TData, event: MouseEvent) => void;
  emitSelection: () => void;
  clearSelection: () => void;
  selectAllMatching: () => Promise<number>;
  loadAllMatchingRows: () => Promise<TData[]>;
  status: Ref<{ type: "error" | "success"; message: string } | undefined>;
  queryClient: QueryClient;
  locale: string;
  onBulkDelete?: (rows: TData[]) => MaybePromise<BulkActionHandlerResult>;
  onBulkEdit?: (
    rows: TData[],
    patch?: TableRecord
  ) => MaybePromise<BulkActionHandlerResult>;
  onBulkCopy?: (rows: TData[]) => MaybePromise<BulkActionHandlerResult>;
  onBulkExport?: (rows: TData[]) => MaybePromise<BulkActionHandlerResult>;
  onExport?: (rows: TData[]) => Promise<void> | void;
}

export const tableContextKey = Symbol(
  "yayaw-table-vue"
) as InjectionKey<TableContextValue>;

export const useTableContext = <
  TData extends TableRecord = TableRecord,
>(): TableContextValue<TData> => {
  const value = inject(tableContextKey);
  if (!value) {
    throw new Error(
      "YaYaw Table components must be used inside <YayawDataTable>."
    );
  }
  return value as TableContextValue<TData>;
};

/** Translate reusable field controls without requiring a table provider for standalone forms. */
export const useTableTranslation = (): ((
  key: string,
  fallback: string
) => string) => {
  const context = inject(tableContextKey, undefined);
  return (key, fallback) => {
    const value = context?.translations.value[key];
    return typeof value === "string" ? value : fallback;
  };
};

import { isValid } from "date-fns";
import { normalizeGenericModeConfigs } from "./display-modes";
import { normalizeGalleryViewConfig } from "./gallery-view-state";
import {
  dataTypeOptionLabel,
  matchesContractFilter,
  normalizeFilterEnvelope,
} from "./table-contracts";
import { getTableFavoriteStorageKey } from "./table-view-favorite";
import type {
  AdvancedFilter,
  AdvancedFiltersState,
  CalculationType,
  ColumnDefinition,
  ColumnFiltersState,
  ColumnNumberFormat,
  CreateTableViewInput,
  DateDisplayPreset,
  SortingState,
