} from "./types";
import {
  formatNumberValue,
  formatDateValue as formatSharedDate,
} from "./value-format";

const CSV_ESCAPE_PATTERN = /[",\n\r]/;
const VIEW_STORAGE_KEY_PATTERN = /^yayaw-table:(.+):views$/;
const NATURAL_SORT_COLLATOR = new Intl.Collator(undefined, {
  numeric: true,
  sensitivity: "base",
});

const isEmptyValue = (value: unknown): boolean =>
  value === null ||
  value === undefined ||
  value === "" ||
  (Array.isArray(value) && value.length === 0);

const toComparable = (
  value: unknown,
  columnType?: ColumnDefinition["type"]
): number | string => {
  if (value instanceof Date) {
    return value.getTime();
  }
  if (typeof value === "number") {
    return value;
  }
  if (typeof value === "boolean") {
    return value ? 1 : 0;
  }
  if (columnType === "date" && typeof value === "string") {
    const date = Date.parse(value);
    if (!Number.isNaN(date)) {
      return date;
    }
  }
  if (columnType === "number") {
    const number = Number(value);
    if (Number.isFinite(number)) {
      return number;
    }
  }
  return String(value ?? "").toLocaleLowerCase();
};

const compareValues = (
  left: number | string,
  right: number | string
): number => {
  if (typeof left === "string" && typeof right === "string") {
    return NATURAL_SORT_COLLATOR.compare(left, right);
  }
  if (left < right) {
    return -1;
  }
  if (left > right) {
    return 1;
  }
  return 0;
};

export const matchesAdvancedFilter = (
  row: TableRecord,
  filter: AdvancedFilter
): boolean => {
  return matchesContractFilter(row[filter.columnId], { ...filter });
};

export const applyAdvancedFilters = <TData extends TableRecord>(
  rows: TData[],
  input?: AdvancedFiltersState | unknown[]
): TData[] => {
  const normalized = normalizeFilterEnvelope(input);
  const state = {
    ...normalized,
    filters: normalized.filters.filter((filter) => filter.isActive !== false),
  } as unknown as AdvancedFiltersState;
  if (!state.filters.length) {
    return rows;
  }
  return rows.filter((row) =>
    state.joinOperator === "or"
      ? state.filters.some((filter) => matchesAdvancedFilter(row, filter))
      : state.filters.every((filter) => matchesAdvancedFilter(row, filter))
  );
};

export const applyTableQuery = <TData extends TableRecord>(
  rows: TData[],
  {
    columns,
    search = "",
    filters = [],
    advancedFilters,
    sorting = [],
  }: {
    columns: ColumnDefinition<TData>[];
    search?: string;
    filters?: ColumnFiltersState;
    advancedFilters?: AdvancedFiltersState;
    sorting?: SortingState;
  }
): TData[] => {
  const columnsById = new Map(columns.map((column) => [column.id, column]));
  const valueFor = (row: TData, columnId: string): unknown => {
    const column = columnsById.get(columnId);
    return column?.accessorFn
      ? column.accessorFn(row)
      : row[column?.accessorKey ?? columnId];
  };
  const query = search.trim().toLocaleLowerCase();
  const filtered = rows.filter((row) => {
    if (
      query &&
      !columns.some((column) =>
        String(valueFor(row, column.id) ?? "")
          .toLocaleLowerCase()
          .includes(query)
      )
    ) {
      return false;
    }
    return filters.every((filter) => {
      const actual = valueFor(row, filter.id);
      const expected = String(filter.value ?? "").toLocaleLowerCase();
      if (Array.isArray(actual)) {
        return actual.some((value) =>
          String(value).toLocaleLowerCase().includes(expected)
        );
      }
      return String(actual ?? "")
        .toLocaleLowerCase()
        .includes(expected);
    });
  });
  const advancedRows = advancedFilters?.filters.length
    ? (applyAdvancedFilters(
        filtered.map((row) => ({
          ...row,
          ...Object.fromEntries(
            columns.map((column) => [column.id, valueFor(row, column.id)])
          ),
        })),
        advancedFilters
      ) as TData[])
    : filtered;
  if (!sorting.length) {
    return advancedRows;
  }
  return [...advancedRows].sort((leftRow, rightRow) => {
    for (const sort of sorting) {
      const columnType = columnsById.get(sort.id)?.type;
      const left = toComparable(valueFor(leftRow, sort.id), columnType);
      const right = toComparable(valueFor(rightRow, sort.id), columnType);
      const comparison = compareValues(left, right);
      if (comparison) {
        return sort.desc ? -comparison : comparison;
      }
    }
    return 0;
  });
};

export const formatNumber = (
  value: unknown,
  options: ColumnNumberFormat = {}
): string => formatNumberValue(value, options);

/** Earlier signature kept; zone options come from the column. */
export const formatDateValue = (
  value: unknown,
  preset: DateDisplayPreset = "localized-short",
  customFormat?: string,
  locale?: string,
  zone: { timeZone?: string; hour12?: boolean } = {}
): string =>
  formatSharedDate(value, {
    preset,
    pattern: customFormat,
    locale,
    timeZone: zone.timeZone,
    hour12: zone.hour12,
  });

export const displayCellValue = (
  value: unknown,
  column: ColumnDefinition,
  locale?: string
): string => {
  if (value === null || value === undefined || value === "") {
    return "—";
  }
  if (column.type === "date") {
    return formatDateValue(
      value,
      column.dateDisplayPreset,
      column.dateFormat,
      locale,
      { timeZone: column.timeZone, hour12: column.hour12 }
    );
  }
  if (column.type === "number") {
    return formatNumberValue(value, column.numberFormat, locale);
  }
  if (column.type === "boolean") {
    return value ? "Yes" : "No";
  }
  if (column.type === "json") {
    try {
      return JSON.stringify(value);
    } catch {
      return String(value);
    }
  }
  if (["select", "multiSelect", "tag"].includes(column.type ?? "")) {
    return (Array.isArray(value) ? value : [value])
      .map((item) => dataTypeOptionLabel(item, column.options))
      .join(", ");
  }
  if (Array.isArray(value)) {
    return value.map(String).join(", ");
  }
  if (typeof value === "object") {
    try {
      return JSON.stringify(value);
    } catch {
      return String(value);
    }
  }
  const displayed = String(value);
  return column.type === "string" && column.showQuotes
    ? `“${displayed}”`
    : displayed;
};

const numericValues = (rows: TableRecord[], columnId: string): number[] =>
  rows
    .map((row) => row[columnId])
    .filter((value) => !isEmptyValue(value))
    .map(Number)
    .filter(Number.isFinite);

const calculateDateColumn = (
  values: unknown[],
  calculation: CalculationType,
  locale?: string
): string | null | undefined => {
  if (!["min", "max", "range"].includes(calculation)) {
    return undefined;
  }
  const dates = values
    .filter((value) => !isEmptyValue(value))
    .map((value) => (value instanceof Date ? value : new Date(String(value))))
    .filter((value) => isValid(value))
    .sort((left, right) => left.getTime() - right.getTime());
  const first = dates.at(0);
  const last = dates.at(-1);
  if (!(first && last)) {
    return null;
  }
  if (calculation === "range") {
    return `${Math.round((last.getTime() - first.getTime()) / 86_400_000)}d`;
  }
  const selected = calculation === "min" ? first : last;
  return new Intl.DateTimeFormat(locale, {
    year: "numeric",
    month: "short",
    day: "numeric",
  }).format(selected);
};

const calculateCounts = (
  values: unknown[],
  nonEmpty: unknown[],
  calculation: CalculationType
): number | undefined => {
  const total = values.length;
  switch (calculation) {
    case "count_all":
      return total;
    case "count_empty":
      return total - nonEmpty.length;
    case "count_not_empty":
    case "count_values":
      return nonEmpty.length;
    case "count_unique":
      return new Set(nonEmpty.map((value) => JSON.stringify(value))).size;
    case "count_true":
      return values.filter((value) => value === true).length;
    case "count_false":
      return values.filter((value) => value === false).length;
    case "percent_empty":
      return total ? ((total - nonEmpty.length) / total) * 100 : 0;
    case "percent_not_empty":
      return total ? (nonEmpty.length / total) * 100 : 0;
    case "percent_true":
      return total
        ? (values.filter((value) => value === true).length / total) * 100
        : 0;
    case "percent_false":
      return total
        ? (values.filter((value) => value === false).length / total) * 100
        : 0;
    default:
      return undefined;
  }
};

const calculateNumeric = (
  numbers: number[],
  calculation: CalculationType
): number | null => {
  if (!numbers.length) {
    return null;
  }
  switch (calculation) {
    case "sum":
      return numbers.reduce((sum, value) => sum + value, 0);
    case "average":
      return numbers.reduce((sum, value) => sum + value, 0) / numbers.length;
    case "median": {
      const middle = Math.floor(numbers.length / 2);
      const middleValue = numbers[middle] ?? 0;
      return numbers.length % 2
        ? middleValue
        : ((numbers[middle - 1] ?? 0) + middleValue) / 2;
    }
    case "min":
      return numbers.at(0) ?? null;
    case "max":
      return numbers.at(-1) ?? null;
    case "range":
      return (numbers.at(-1) ?? 0) - (numbers.at(0) ?? 0);
    default:
      return null;
  }
};

export const calculateColumn = (
  rows: TableRecord[],
  columnId: string,
  calculation: CalculationType,
  columnType?: string,
  locale?: string
): number | string | null => {
  const values = rows.map((row) => row[columnId]);
  const numbers = numericValues(rows, columnId).sort((a, b) => a - b);
  const nonEmpty = values.filter((value) => !isEmptyValue(value));
  if (columnType === "date") {
    const dateResult = calculateDateColumn(values, calculation, locale);
    if (dateResult !== undefined) {
      return dateResult;
    }
  }
  const countResult = calculateCounts(values, nonEmpty, calculation);
  return countResult ?? calculateNumeric(numbers, calculation);
};

const csvEscape = (value: unknown): string => {
  let text = "";
  if (value !== null && value !== undefined) {
    text = typeof value === "object" ? JSON.stringify(value) : String(value);
  }
  return CSV_ESCAPE_PATTERN.test(text)
    ? `"${text.replaceAll('"', '""')}"`
    : text;
};

export const exportColumns = (
  columns: ColumnDefinition[],
  visibility: Record<string, boolean>,
  order: string[]
): ColumnDefinition[] => {
  const ids = [...new Set([...order, ...columns.map((column) => column.id)])];
  return ids.flatMap((id) => {
    const column = columns.find((item) => item.id === id);
    return column && visibility[id] !== false ? [column] : [];
  });
};

export const rowsToCsv = (
  rows: TableRecord[],
  columns: ColumnDefinition[]
): string => {
  const exportColumns = columns.filter(
    (column) => column.type !== "actions" && column.id !== "select"
  );
  return [
    exportColumns.map((column) => csvEscape(column.header)).join(","),
    ...rows.map((row) =>
      exportColumns
        .map((column) =>
          csvEscape(
            column.accessorFn
              ? column.accessorFn(row)
              : row[column.accessorKey ?? column.id]
          )
        )
        .join(",")
    ),
  ].join("\n");
};

export const downloadCsv = (
  rows: TableRecord[],
  columns: ColumnDefinition[],
  filename: string
): void => {
  if (typeof document === "undefined") {
    return;
  }
  const blob = new Blob([rowsToCsv(rows, columns)], {
    type: "text/csv;charset=utf-8",
  });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = filename.endsWith(".csv") ? filename : `${filename}.csv`;
  anchor.click();
  URL.revokeObjectURL(url);
};

export const createTableViewSnapshot = (
  config: TableViewConfig
): TableViewConfig => {
  const snapshot: TableViewConfig = {
    ...config,
    gallery: normalizeGalleryViewConfig(config.gallery),
    ...normalizeGenericModeConfigs(config as Record<string, unknown>),
    advancedFilters: normalizeFilterEnvelope(
      config.advancedFilters
    ) as unknown as AdvancedFiltersState,
  };
  if (!snapshot.search) {
    snapshot.search = undefined;
  }
  if (!snapshot.filters?.length) {
    snapshot.filters = undefined;
  }
  if (!normalizeFilterEnvelope(snapshot.advancedFilters).filters.length) {
    snapshot.advancedFilters = undefined;
  }
  if (!snapshot.sorting?.length) {
    snapshot.sorting = undefined;
  }
  if (!snapshot.grouping?.length) {
    snapshot.grouping = undefined;
  }
  if (!snapshot.columnOrder?.length) {
    snapshot.columnOrder = undefined;
  }
  if (
    !snapshot.columnSizing ||
    Object.keys(snapshot.columnSizing).length === 0
  ) {
    snapshot.columnSizing = undefined;
  }
  if (
    snapshot.columnVisibility &&
    Object.keys(snapshot.columnVisibility).length === 0
  ) {
    snapshot.columnVisibility = undefined;
  }
  return snapshot;
};

const storageKey = (tableId: string): string => `yayaw-table:${tableId}:views`;

const loadLocalViews = (tableId: string): TableView[] => {
  if (typeof localStorage === "undefined") {
    return [];
  }
  try {
    const value = JSON.parse(localStorage.getItem(storageKey(tableId)) ?? "[]");
    return Array.isArray(value) ? value : [];
  } catch {
    return [];
  }
};

const storeLocalViews = (tableId: string, views: TableView[]): void => {
  if (typeof localStorage !== "undefined") {
    localStorage.setItem(storageKey(tableId), JSON.stringify(views));
  }
};

export const createLocalTableViewActions = (): Required<TableViewActions> => ({
  getFavorite: (context) => ({
    success: true,
    data: {
      viewId:
        typeof localStorage === "undefined"
          ? null
          : localStorage.getItem(getTableFavoriteStorageKey(context)) || null,
    },
  }),
  setFavorite: (viewId, context) => {
    if (typeof localStorage === "undefined") {
      return { success: false, error: "Favorite storage is unavailable" };
    }
    localStorage.setItem(getTableFavoriteStorageKey(context), viewId ?? "");
    return { success: true, data: { viewId } };
  },
  list: ({ tableId }) => loadLocalViews(tableId),
  create: (input: CreateTableViewInput) => {
    const now = new Date().toISOString();
    const view: TableView = {
      ...input,
      id: crypto.randomUUID(),
      createdAt: now,
      updatedAt: now,
    };
    storeLocalViews(input.tableId, [...loadLocalViews(input.tableId), view]);
    return { success: true, data: view };
  },
  update: (id, input) => {
    let updated: TableView | undefined;
    const tableId =
      input.tableId ??
      (typeof window === "undefined"
        ? ""
        : (Object.keys(localStorage)
            .map((key) => key.match(VIEW_STORAGE_KEY_PATTERN)?.[1])
            .find(
              (candidate) =>
                candidate &&
                loadLocalViews(candidate).some((view) => view.id === id)
            ) ?? ""));
    if (
      loadLocalViews(tableId).find((view) => view.id === id)?.canEdit === false
    ) {
      return { success: false, error: "This view cannot be edited." };
    }
    if (loadLocalViews(tableId).find((view) => view.id === id)?.isSystem) {
      return { success: false, error: "System views cannot be updated" };
    }
    const views = loadLocalViews(tableId).map((view) => {
      if (view.id !== id) {
        return view;
      }
      updated = {
        ...view,
        ...input,
        config: input.config ?? view.config,
        updatedAt: new Date().toISOString(),
      };
      return updated;
    });
    if (updated) {
      storeLocalViews(tableId, views);
    }
    return updated
      ? { success: true, data: updated }
      : { success: false, error: "View not found" };
  },
  delete: (id, { tableId }) => {
    const views = loadLocalViews(tableId);
    const target = views.find((view) => view.id === id);
    if (target?.canDelete === false) {
      return { success: false, error: "This view cannot be deleted." };
    }
    if (target?.isSystem) {
      return { success: false, error: "System views cannot be deleted" };
    }
    storeLocalViews(
      tableId,
      views.filter((view) => view.id !== id)
    );
    return { success: true };
  },
});

export const safeHttpUrl = (value: unknown): string | undefined => {
  if (typeof value !== "string") {
    return undefined;
  }
  try {
    const url = new URL(value);
    return url.protocol === "http:" || url.protocol === "https:"
      ? url.href
      : undefined;
  } catch {
    return undefined;
  }
};

export const rowId = (row: TableRecord, fallback: string): string =>
  String(row.id ?? row.key ?? fallback);

const IMAGE_SOURCE =
  /^(?:https?:\/\/|\/(?!\/)|data:image\/[a-z0-9.+-]+;base64,|blob:)/i;
export const imageSource = (value: unknown): string | undefined =>
  typeof value === "string" && IMAGE_SOURCE.test(value.trim())
    ? value.trim()
    : undefined;

import type { Component } from "vue";
import type { ScopedRowsRequest } from "./scoped-rows";
import type { ColumnDefinition, TableDisplayMode, TableRecord } from "./types";

/** What a mode's settings panel needs. */
export interface DisplayModeSettingsContext {
  tableId: string;
  locale: string;
  columns: ColumnDefinition[];
  /** Table defaults for this mode, before the view's own settings. */
  defaults: Record<string, unknown>;
  /** The active view's own settings for this mode. */
  settings: Record<string, unknown>;
  /** Save settings for this mode in the view and URL (`undefined` resets them). */
  updateSettings: (settings: Record<string, unknown> | undefined) => void;
  translate: (key: string, fallback: string) => string;
}

/**
 * What the table gives a display mode rendered by an optional registry item,
 * such as the calendar. The item never reaches into table internals.
 */
export interface DisplayModeRenderContext extends DisplayModeSettingsContext {
  tableType: string;
  /** The current query (search, filters, sorting) as list parameters. */
  listParams: Record<string, unknown>;
  list?: ScopedRowsRequest["list"];
  /** Rows matching the current query, for tables without a list action. */
  rows: TableRecord[];
  getRowId: (row: TableRecord) => string;
  canEditRow: (row: TableRecord) => boolean;
  canCreate: boolean;
  /** Save a patch through `actions.update`; resolves false on failure. */
  updateRow: (row: TableRecord, patch: TableRecord) => Promise<boolean>;
  /** Open a record like a row click (details, edit or link). */
  openRow: (row: TableRecord, event?: MouseEvent) => void;
  /** Open the create form with prefilled values. */
  createRow: (initial: TableRecord) => void;
  /** Changes after each mutation so renderers reload their rows. */
  revision: number;
}

/** Components receive a `context` prop. */
export interface DisplayModeRenderer {
  view: Component;
  /** Content of View → Card settings for this mode. */
  settings?: Component;
}

export type DisplayModeRenderers = Partial<
  Record<TableDisplayMode, DisplayModeRenderer>
>;

/**
 * Display mode registry shared by the React and Vue editions.
 *
 * Every framework-neutral fact about a mode lives here, so adding a mode means
 * one entry in this file plus its renderer and settings panel in each edition.
 */
import {
  type CalendarViewSettings,
  normalizeCalendarViewConfig,
} from "./calendar-model";
import { type ListViewSettings, normalizeListViewConfig } from "./list-view";

export interface DisplayModeDefinition {
  /** Table-only presentation controls offered by the view menu. */
  capabilities: {
    calculations: boolean;
    columns: boolean;
    density: boolean;
  };
  /** Saved-view and URL key holding the mode's own settings (`${tableId}-${configKey}`). */
  configKey?: string;
  /** Grouping levels the mode can render; 0 hides the grouping control. */
  maxGroups: number;
  /** The mode renders nothing useful without a planning session. */
  requiresPlanning?: boolean;
  /**
   * The mode is rendered by an optional registry item (its library stays out
   * of the base block); it is offered only when that renderer is plugged in.
   */
  requiresRenderer?: boolean;
  /**
   * Saved views, URLs and table state handle the settings generically with
   * this normalizer. Kanban, gallery and Gantt keep dedicated code for their
   * historical migrations.
   */
  normalizeConfig?: (value: unknown) => object | undefined;
}

const NO_TABLE_CONTROLS = {
  calculations: false,
  columns: false,
  density: false,
} as const;

export const DISPLAY_MODES = {
  table: {
    capabilities: { calculations: true, columns: true, density: true },
    maxGroups: 2,
  },
  list: {
    capabilities: { calculations: false, columns: false, density: true },
    configKey: "list",
    maxGroups: 1,
    normalizeConfig: normalizeListViewConfig,
  },
  kanban: {
    capabilities: NO_TABLE_CONTROLS,
    configKey: "kanban",
    maxGroups: 1,
  },
  gallery: {
    capabilities: NO_TABLE_CONTROLS,
    configKey: "gallery",
    maxGroups: 1,
  },
  calendar: {
    capabilities: NO_TABLE_CONTROLS,
    configKey: "calendar",
    maxGroups: 0,
    normalizeConfig: normalizeCalendarViewConfig,
    requiresRenderer: true,
  },
  gantt: {
    capabilities: NO_TABLE_CONTROLS,
    configKey: "gantt",
    maxGroups: 0,
    requiresPlanning: true,
  },
} as const satisfies Record<string, DisplayModeDefinition>;

export type TableDisplayMode = keyof typeof DISPLAY_MODES;

export const DISPLAY_MODE_IDS = Object.keys(
  DISPLAY_MODES
) as TableDisplayMode[];

/** Keys of per-mode settings in saved views and URLs, in registry order. */
export const DISPLAY_MODE_CONFIG_KEYS = DISPLAY_MODE_IDS.flatMap((mode) => {
  const definition: DisplayModeDefinition = DISPLAY_MODES[mode];
  return definition.configKey ? [definition.configKey] : [];
});

export function isTableDisplayMode(value: unknown): value is TableDisplayMode {
  return typeof value === "string" && Object.hasOwn(DISPLAY_MODES, value);
}

export interface DisplayModeContext {
  /** Whether a planning session can feed planning modes such as Gantt. */
  planning?: boolean;
  /** Modes whose optional renderer is plugged into the table. */
  renderers?: readonly string[];
}

function isModeUsable(
  mode: TableDisplayMode,
  context: DisplayModeContext
): boolean {
  const definition: DisplayModeDefinition = DISPLAY_MODES[mode];
  if (definition.requiresPlanning && !context.planning) {
    return false;
  }
  return !(definition.requiresRenderer && !context.renderers?.includes(mode));
}

/**
 * Configured modes, deduplicated and restricted to known modes. With a context,
 * modes that cannot render yet are withheld; the table mode is the last resort.
 */
export function resolveDisplayModes(
  displayModes: readonly unknown[] | undefined,
  context?: DisplayModeContext
): TableDisplayMode[] {
  const known = (displayModes ?? []).filter(
    (mode, index, modes): mode is TableDisplayMode =>
      isTableDisplayMode(mode) && modes.indexOf(mode) === index
  );
  const usable = context
    ? known.filter((mode) => isModeUsable(mode, context))
    : known;
  return usable.length ? usable : ["table"];
}

/** The requested mode when it is offered, otherwise the default, otherwise the first offered mode. */
export function resolveDisplayMode({
  allowed,
  fallback,
  requested,
}: {
  allowed: readonly TableDisplayMode[];
  fallback?: unknown;
  requested?: unknown;
}): TableDisplayMode {
  if (isTableDisplayMode(requested) && allowed.includes(requested)) {
    return requested;
  }
  if (isTableDisplayMode(fallback) && allowed.includes(fallback)) {
    return fallback;
  }
  return allowed[0] ?? "table";
}

export function displayModeMaxGroups(mode: TableDisplayMode): number {
  return DISPLAY_MODES[mode].maxGroups;
}

/** View settings of the modes handled generically, by config key. */
export interface GenericModeViewConfigs {
  list?: ListViewSettings;
  calendar?: CalendarViewSettings;
}

export type GenericModeConfigKey = keyof GenericModeViewConfigs;

/** Config keys whose settings are stored and restored generically. */
export const GENERIC_MODE_CONFIG_KEYS = DISPLAY_MODE_IDS.flatMap((mode) => {
  const definition: DisplayModeDefinition = DISPLAY_MODES[mode];
  return definition.configKey && definition.normalizeConfig
    ? [definition.configKey as GenericModeConfigKey]
    : [];
});

function genericNormalizer(key: GenericModeConfigKey) {
  const mode = DISPLAY_MODE_IDS.find(
    (id) => (DISPLAY_MODES[id] as DisplayModeDefinition).configKey === key
  );
  return mode
    ? (DISPLAY_MODES[mode] as DisplayModeDefinition).normalizeConfig
    : undefined;
}

/** One mode's settings, normalized; unknown or empty values are dropped. */
export function normalizeModeConfig(
  key: GenericModeConfigKey,
  value: unknown
): object | undefined {
  return genericNormalizer(key)?.(value);
}

/** Every generic mode's settings found in a saved view or state object. */
export function normalizeGenericModeConfigs(
  source: Record<string, unknown>
): GenericModeViewConfigs {
  const normalized: Record<string, object> = {};
  for (const key of GENERIC_MODE_CONFIG_KEYS) {
    const value = normalizeModeConfig(key, source[key]);
    if (value) {
      normalized[key] = value;
    }
  }
  return normalized as GenericModeViewConfigs;
}

/** The generic per-mode settings of a table config, for passing it along. */
export function pickGenericModeConfigs(source: object): GenericModeViewConfigs {
  const record = source as Record<string, unknown>;
  return Object.fromEntries(
    GENERIC_MODE_CONFIG_KEYS.flatMap((key) =>
      record[key] === undefined ? [] : [[key, record[key]]]
    )
  ) as GenericModeViewConfigs;
}

type RecordData = Record<string, unknown>;
interface DuplicateResult {
  success: boolean;
  data?: unknown;
  error?: string;
}

export function duplicateLabels(locale: string, count: number) {
  const french = locale.startsWith("fr");
  const plural =
    new Intl.PluralRules(french ? "fr" : "en").select(count) !== "one";
  return {
    success: french
      ? `${count} élément${plural ? "s" : ""} dupliqué${plural ? "s" : ""}`
      : `${count} record${plural ? "s" : ""} duplicated`,
    error: french
      ? "La duplication a échoué. Les éléments non dupliqués restent sélectionnés."
      : "Duplication failed. Records that were not duplicated remain selected.",
  };
}

/** Run the existing host duplicate action once per permitted selected record. */
export function createSelectionDuplicate(options: {
  rows: () => readonly RecordData[];
  getId: (row: RecordData) => string;
  canDuplicate: (row: RecordData) => boolean;
  action: () =>
    | ((id: string) => DuplicateResult | Promise<DuplicateResult>)
    | undefined;
  refresh: () => Promise<unknown>;
  select: (rows: RecordData[]) => void;
  success: (count: number) => void;
  error: (message?: string) => void;
}) {
  let pending = false;
  return async () => {
    const action = options.action();
    const selected = [
      ...new Map(
        options.rows().map((row) => [options.getId(row), row])
      ).values(),
    ];
    if (
      pending ||
      !action ||
      !selected.length ||
      selected.some((row) => !options.canDuplicate(row))
    ) {
      return;
    }
    pending = true;
    const { copies, completed, failed } = await duplicateRecords(
      selected,
      action,
      options
    );
    try {
      if (completed) {
        await options.refresh();
        options.select([...copies, ...selected.slice(completed)]);
      }
      if (!failed) {
        options.success(completed);
      }
    } catch (cause) {
      options.error(cause instanceof Error ? cause.message : undefined);
    } finally {
      pending = false;
    }
  };
}

async function duplicateRecords(
  selected: RecordData[],
  action: (id: string) => DuplicateResult | Promise<DuplicateResult>,
  options: Pick<
    Parameters<typeof createSelectionDuplicate>[0],
    "getId" | "error"
  >
) {
  const copies: RecordData[] = [];
  let completed = 0;
  let failed = false;
  try {
    for (const row of selected) {
      const result = await action(options.getId(row));
      if (!result.success) {
        failed = true;
        options.error(result.error);
        break;
      }
      completed += 1;
      if (
        result.data &&
        typeof result.data === "object" &&
        !Array.isArray(result.data)
      ) {
        copies.push(result.data as RecordData);
      }
    }
  } catch (cause) {
    failed = true;
    options.error(cause instanceof Error ? cause.message : undefined);
  }
  return { copies, completed, failed };
}

/** Quick filters reuse catalogue options and the native column-filter state. */
export interface FilterBarOption {
  value: string | number | boolean;
  label: string;
  disabled?: boolean;
}

export interface FilterBarColumn {
  id: string;
  header: string;
  type?: string;
  enableFiltering?: boolean;
  options?: unknown;
}

export const filterValueKey = (value: unknown): string =>
  `${typeof value}:${String(value)}`;

export function filterValues(value: unknown): unknown[] {
  if (value === undefined || value === null || value === "") {
    return [];
  }
  return Array.isArray(value) ? value : [value];
}

export function filterBarOptions(
  column: FilterBarColumn,
  value: unknown,
  booleanLabels: { yes: string; no: string }
): FilterBarOption[] {
  const options: FilterBarOption[] = Array.isArray(column.options)
    ? column.options
    : [];
  const initial =
    options.length || column.type !== "boolean"
      ? options
      : [
          { value: true, label: booleanLabels.yes },
          { value: false, label: booleanLabels.no },
        ];
  const result = new Map(
    initial.map((option) => [filterValueKey(option.value), option])
  );
  // Retain selections loaded from saved views even if an option was removed.
  for (const selected of filterValues(value)) {
    if (!["string", "number", "boolean"].includes(typeof selected)) {
      continue;
    }
    const key = filterValueKey(selected);
    if (!result.has(key)) {
      result.set(key, {
        value: selected as FilterBarOption["value"],
        label: String(selected),
      });
    }
  }
  return [...result.values()];
}

export function filterBarColumns<T extends FilterBarColumn>(
  columns: T[],
  ids: string[] = []
): T[] {
  return [...new Set(ids)].flatMap((id) => {
    const column = columns.find((item) => item.id === id);
    return column &&
      column.enableFiltering !== false &&
      (Array.isArray(column.options) || column.type === "boolean")
      ? [column]
      : [];
  });
}

export function replaceColumnFilter<T extends { id: string; value: unknown }>(
  filters: T[],
  id: string,
  values: unknown[]
): { id: string; value: unknown }[] {
  const other = filters.filter((filter) => filter.id !== id);
  return values.length ? [...other, { id, value: values }] : other;
}

import { dataTypeFilter } from "./table-contracts";
import type {
  AdvancedFilter,
  AdvancedFilterOperator,
  ColumnDefinition,
  ColumnType,
} from "./types";

const emptyOperators = ["isEmpty", "isNotEmpty"] as const;
const operators = {
  text: [
    "contains",
    "equals",
    "startsWith",
    "endsWith",
    "notContains",
    ...emptyOperators,
  ],
  number: [
    "equals",
    "greaterThan",
    "lessThan",
    "greaterThanOrEqual",
    "lessThanOrEqual",
    "between",
    "notEquals",
    ...emptyOperators,
  ],
  date: [
    "equals",
    "before",
    "after",
    "between",
    "notEquals",
    ...emptyOperators,
  ],
  select: ["is", "isNot", "isAnyOf", "isNoneOf", ...emptyOperators],
  multiSelect: ["contains", "containsAll", "containsNone", ...emptyOperators],
  boolean: ["isTrue", "isFalse", ...emptyOperators],
} satisfies Record<string, AdvancedFilterOperator[]>;
export const filterType = (
  column?: ColumnDefinition
): keyof typeof operators => {
  return dataTypeFilter(column?.type, Boolean(column?.options?.length));
};
export const filterOperators = (
  column: ColumnDefinition | undefined,
  current?: AdvancedFilterOperator
): AdvancedFilterOperator[] => {
  const type = filterType(column);
  const values: AdvancedFilterOperator[] = [...operators[type]];
  // Keep historical Vue aliases editable when a saved view uses them.
  const aliases: Partial<
    Record<keyof typeof operators, AdvancedFilterOperator[]>
  > = {
    select: ["equals", "notEquals", "in", "notIn", "isTrue", "isFalse"],
    multiSelect: ["in", "notIn", "notContains", "isAnyOf", "isNoneOf"],
    text: ["notEquals"],
    date: ["greaterThan", "lessThan", "greaterThanOrEqual", "lessThanOrEqual"],
  };
  if (current && aliases[type]?.includes(current)) {
    values.push(current);
  }
  return values;
};
export const filterNeedsValue = (operator: AdvancedFilterOperator): boolean =>
  !["isEmpty", "isNotEmpty", "isTrue", "isFalse"].includes(operator);
export const filterIsMultiple = (
  type: ColumnType | undefined,
  operator: AdvancedFilterOperator
): boolean =>
  type === "multiSelect" ||
  [
    "in",
    "notIn",
    "isAnyOf",
    "isNoneOf",
    "containsAll",
    "containsNone",
  ].includes(operator);
export const newFilter = (column: ColumnDefinition): AdvancedFilter => ({
  id: crypto.randomUUID(),
  columnId: column.id,
  type: filterType(column),
  operator: filterOperators(column)[0] ?? "contains",
  values: undefined,
  isActive: false,
});
export const filterHasValue = (filter: AdvancedFilter): boolean => {
  if (!filterNeedsValue(filter.operator)) {
    return true;
  }
  const values = Array.isArray(filter.values) ? filter.values : [filter.values];
  if (filter.operator === "between" && values.length !== 2) {
    return false;
  }
  if (!values.length) {
    return false;
  }
  return values.every((value) => {
    if (value === undefined || value === null) {
      return false;
    }
    if (filter.type === "number") {
      return typeof value === "number" && Number.isFinite(value);
    }
    if (filter.type === "date") {
      return value !== "" && Number.isFinite(new Date(String(value)).getTime());
    }
    return (
      filter.type === "select" || filter.type === "multiSelect" || value !== ""
    );
  });
};
export const operatorTranslationKeys: Record<AdvancedFilterOperator, string> = {
  contains: "contains",
  notContains: "not_contains",
  equals: "equals",
  notEquals: "not_equals",
  startsWith: "starts_with",
  endsWith: "ends_with",
  is: "is",
  isNot: "is_not",
  isAnyOf: "is_any_of",
  isNoneOf: "is_none_of",
  in: "is_any_of",
  notIn: "is_none_of",
  containsAll: "contains_all",
  containsNone: "contains_none",
  greaterThan: "greater_than",
  greaterThanOrEqual: "greater_than_or_equal",
  lessThan: "less_than",
  lessThanOrEqual: "less_than_or_equal",
  before: "before",
  after: "after",
  between: "between",
  isEmpty: "empty",
  isNotEmpty: "not_empty",
  isTrue: "is_true",
  isFalse: "is_false",
};

/** Framework-neutral layout contracts; each registry ships its own copy. */
export interface FormLayoutRuntime {
  disabled: boolean;
  isSubmitting: boolean;
  isValidating: boolean;
  setFieldValue: (name: string, value: unknown) => void;
  submit: () => Promise<void>;
  validate: () => Promise<boolean>;
}

export interface FormLayoutAction<TContext> {
  id: string;
  label: string;
  labelKey?: string;
  disabled?: boolean | ((context: TContext) => boolean);
  hidden?: boolean | ((context: TContext) => boolean);
  /** Validate the form before running this action, without submitting it. */
  validate?: boolean;
  variant?: "default" | "outline" | "secondary" | "destructive";
  onClick: (context: TContext, signal: AbortSignal) => void | Promise<void>;
}

export type FormBlockSpan = 1 | 2 | 3 | "full";

interface BlockBase {
  id: string;
  span?: FormBlockSpan;
}

export type FormLayoutBlock<TContext, TContent> =
  | {
      type: "field";
      name: string;
      id?: string;
      span?: FormBlockSpan;
    }
  | (BlockBase & {
      type: "section";
      title?: string;
      titleKey?: string;
      description?: string;
      descriptionKey?: string;
      columns?: 1 | 2 | 3;
      blocks: FormLayoutBlock<TContext, TContent>[];
    })
  | (BlockBase & {
      type: "content";
      title?: string;
      titleKey?: string;
      text: string;
      textKey?: string;
      tone?: "default" | "info" | "warning";
    })
  | (BlockBase & {
      type: "actions";
      actions: FormLayoutAction<TContext>[];
    })
  | (BlockBase & {
      type: "custom";
      /** React/Vue render callback. Vue also supports the form-{id} slot. */
      render?: (context: TContext) => TContent;
    });

/** Render each declared field once and retain fields omitted from the layout. */
export function resolveFormBlocks<TContext, TContent>(
  blocks: FormLayoutBlock<TContext, TContent>[],
  fieldNames: readonly string[]
): FormLayoutBlock<TContext, TContent>[] {
  const remaining = new Set(fieldNames);
  const visit = (
    items: FormLayoutBlock<TContext, TContent>[]
  ): FormLayoutBlock<TContext, TContent>[] => {
    const result: FormLayoutBlock<TContext, TContent>[] = [];
    for (const block of items) {
      if (block.type === "field") {
        if (remaining.delete(block.name)) {
          result.push(block);
        }
      } else if (block.type === "section") {
        result.push({ ...block, blocks: visit(block.blocks) });
      } else {
        result.push(block);
      }
    }
    return result;
  };
  return [
    ...visit(blocks),
    ...Array.from(remaining, (name) => ({ type: "field" as const, name })),
  ];
}

export function formBlockId<TContext, TContent>(
  block: FormLayoutBlock<TContext, TContent>
): string {
  return block.type === "field"
    ? (block.id ?? `field-${block.name}`)
    : block.id;
}

export function formBlockSpan(
  span: FormBlockSpan | undefined,
  columns: number
): number | "full" {
  return span === "full" ? "full" : Math.min(span ?? 1, columns);
}

export function formActionFlag<TContext>(
  flag: boolean | ((context: TContext) => boolean) | undefined,
  context: TContext
): boolean {
  return typeof flag === "function" ? flag(context) : flag === true;
}

/** Resolve form-local translations while retaining unresolved provider keys. */
export function translateFormBlocks<TContext, TContent>(
  blocks: FormLayoutBlock<TContext, TContent>[],
  keys: Record<string, string>
): FormLayoutBlock<TContext, TContent>[] {
  const translated = (value: string | undefined, key: string | undefined) => ({
    value: key ? (keys[key] ?? value) : value,
    key: key && keys[key] !== undefined ? undefined : key,
  });
  return blocks.map((block) => {
    if (block.type === "section" || block.type === "content") {
      const title = translated(block.title, block.titleKey);
      if (block.type === "section") {
        const description = translated(block.description, block.descriptionKey);
        return {
          ...block,
          title: title.value,
          titleKey: title.key,
          description: description.value,
          descriptionKey: description.key,
          blocks: translateFormBlocks(block.blocks, keys),
        };
      }
      const text = translated(block.text, block.textKey);
      return {
        ...block,
        title: title.value,
        titleKey: title.key,
        text: text.value ?? block.text,
        textKey: text.key,
      };
    }
    if (block.type === "actions") {
      return {
        ...block,
        actions: block.actions.map((action) => {
          const label = translated(action.label, action.labelKey);
          return {
            ...action,
            label: label.value ?? action.label,
            labelKey: label.key,
          };
        }),
      };
    }
    return block;
  });
}

import { toRaw } from "vue";
import { translateFormBlocks } from "./form-layout";
import {
  dataTypeValueError,
  isJsonFormDraft,
  jsonFormDraft,
  parseJsonFormValue,
} from "./table-contracts";
import type {
  FormConfig,
  FormFieldContext,
  FormFieldDefinition,
  FormSectionDefinition,
  TableRecord,
} from "./types";

/** Clone editable data without sharing nested values with a row or configuration. */
export const cloneFormValue = <T>(value: T): T => {
  if (isJsonFormDraft(value)) {
    return jsonFormDraft(value.text) as T;
  }
  if (value instanceof Date) {
    return new Date(value.getTime()) as T;
  }
  if (Array.isArray(value)) {
    return value.map(cloneFormValue) as T;
  }
  if (value !== null && typeof value === "object") {
    return Object.fromEntries(
      Object.entries(value).map(([key, item]) => [key, cloneFormValue(item)])
    ) as T;
  }
  return value;
};

export const formValuesEqual = (left: unknown, right: unknown): boolean => {
  if (isJsonFormDraft(left) || isJsonFormDraft(right)) {
    return (
      isJsonFormDraft(left) &&
      isJsonFormDraft(right) &&
      left.text === right.text
    );
  }
  if (Object.is(left, right)) {
    return true;
  }
  if (left instanceof Date || right instanceof Date) {
    return (
      left instanceof Date &&
      right instanceof Date &&
      left.getTime() === right.getTime()
    );
  }
  if (
    !(left && right) ||
    typeof left !== "object" ||
    typeof right !== "object"
  ) {
    return false;
  }
  if (Array.isArray(left) !== Array.isArray(right)) {
    return false;
  }
  const a = Object.entries(left);
  const b = Object.entries(right);
  return (
    a.length === b.length &&
    a.every(
      ([key, value]) =>
        Object.hasOwn(right, key) &&
        formValuesEqual(value, (right as TableRecord)[key])
    )
  );
};

export const fieldIsHidden = (
  field: FormFieldDefinition,
  context: FormFieldContext
): boolean =>
  Boolean(
    typeof field.hidden === "function" ? field.hidden(context) : field.hidden
  );

export const fieldIsDisabled = (
  field: FormFieldDefinition,
  context: FormFieldContext
): boolean =>
  Boolean(
    typeof field.disabled === "function"
      ? field.disabled(context)
      : field.disabled
  );

export const defaultFieldValue = (field: FormFieldDefinition): unknown => {
  if (field.defaultValue !== undefined) {
    return cloneFormValue(field.defaultValue);
  }
  if (["number", "date", "select", "json"].includes(field.type)) {
    return null;
  }
  if (field.type === "collection" || field.type === "multiSelect") {
    return [];
  }
  if (field.type === "switch" || field.type === "checkbox") {
    return false;
  }
  return "";
};

export const initialFormValues = (
  config: FormConfig,
  row?: TableRecord
): TableRecord =>
  cloneFormValue({
    ...Object.fromEntries(
      config.fields.map((field) => [field.name, defaultFieldValue(field)])
    ),
    ...config.defaultValues,
    ...row,
  });

export const resolveFormSections = (
  config: FormConfig
): FormSectionDefinition[] => {
  const remaining = new Set(config.fields.map((field) => field.name));
  const sections: FormSectionDefinition[] = [];
  for (const section of config.sections ?? []) {
    const fields = section.fields.filter((name) => remaining.delete(name));
    if (fields.length) {
      sections.push({ ...section, fields });
    }
  }
  if (remaining.size) {
    let id = "__ungrouped";
    while (sections.some((section) => section.id === id)) {
      id += "_";
    }
    sections.push({ id, fields: [...remaining] });
  }
  return sections;
};

export const translateFormConfig = (config: FormConfig): FormConfig => {
  const keys = config.translations?.keys ?? {};
  const translate = (key: string | undefined, fallback: string | undefined) =>
    key ? (keys[key] ?? fallback) : fallback;
  const field = (value: FormFieldDefinition): FormFieldDefinition => ({
    ...value,
    label: translate(value.labelKey, value.label) ?? value.name,
    description: translate(value.descriptionKey, value.description),
    placeholder: translate(value.placeholderKey, value.placeholder),
    itemFields: value.itemFields?.map(field),
    options: Array.isArray(value.options)
      ? value.options.map((option, index) => ({
          ...option,
          label:
            translate(value.optionKeys?.[index], option.label) ?? option.label,
        }))
      : value.options,
  });
  return {
    ...config,
    fields: config.fields.map(field),
    blocks: config.blocks
      ? translateFormBlocks(config.blocks, keys)
      : undefined,
    sections: config.sections?.map((section) => ({
      ...section,
      title: translate(section.titleKey, section.title),
      description: translate(section.descriptionKey, section.description),
    })),
  };
};

export interface FormValidationResult {
  values: TableRecord;
  errors: Record<string, string>;
}

const missing = (value: unknown): boolean =>
  value === "" ||
  value === null ||
  value === undefined ||
  (Array.isArray(value) && value.length === 0);

export const dynamicFieldType = (
  field: FormFieldDefinition,
  context: FormFieldContext
): "boolean" | "json" | "number" | "string" => {
  if (!["dynamic-value", "dynamicValue", "value-type"].includes(field.type)) {
    return "string";
  }
  const raw =
    field.type === "value-type"
      ? context.values[field.valueTypeField ?? ""]
      : field.dependsOn?.transform(context.values[field.dependsOn.field]);
  const candidate = String(raw ?? "string") as
    | "boolean"
    | "json"
    | "number"
    | "string";
  return (
    field.supportedTypes ?? ["boolean", "json", "number", "string"]
  ).includes(candidate)
    ? candidate
    : "string";
};

const validateScalar = (
  field: FormFieldDefinition,
  value: unknown,
  context: FormFieldContext
): string | undefined => {
  if (field.required && missing(value)) {
    return `${field.label} is required`;
  }
  const typeError = dataTypeValueError(
    ["dynamic-value", "dynamicValue", "value-type"].includes(field.type)
      ? dynamicFieldType(field, context)
      : field.type,
    value
  );
  if (typeError) {
    return `${field.label}: ${typeError}`;
  }
  const numeric =
    field.type === "number" || dynamicFieldType(field, context) === "number";
  if (
    numeric &&
    !missing(value) &&
    (typeof value !== "number" || !Number.isFinite(value))
  ) {
    return `Invalid ${field.label}`;
  }
  if (numeric && typeof value === "number") {
    if (field.min !== undefined && value < field.min) {
      return `${field.label} must be at least ${field.min}`;
    }
    if (field.max !== undefined && value > field.max) {
      return `${field.label} must be at most ${field.max}`;
    }
  }
  return undefined;
};

const validateCollection = async (
  field: FormFieldDefinition,
  value: unknown[],
  context: FormFieldContext
): Promise<FormValidationResult> => {
  const items: TableRecord[] = [];
  const errors: Record<string, string> = {};
  for (const [index, item] of value.entries()) {
    const path = `${field.name}.${index}`;
    if (!item || typeof item !== "object" || Array.isArray(item)) {
      errors[path] = "Invalid item";
      continue;
    }
    const child = await validateFormFields(
      field.itemFields ?? [],
      item as TableRecord,
      { ...context, values: item as TableRecord }
    );
    items.push(child.values);
    for (const [name, message] of Object.entries(child.errors)) {
      errors[`${path}.${name}`] = message;
    }
    const issues = field.validateItem?.(child.values, index) ?? [];
    if (issues.length) {
      errors[path] = issues.join("; ");
    }
  }
  const issues = field.validateItems?.(items) ?? [];
  if (issues.length) {
    errors[field.name] = issues.join("; ");
  }
  return { values: { [field.name]: items }, errors };
};

const validateField = async (
  field: FormFieldDefinition,
  value: unknown,
  context: FormFieldContext
): Promise<FormValidationResult> => {
  const values = { [field.name]: value };
  if ((field.type === "number" || field.type === "date") && value === "") {
    values[field.name] = null;
  }
  if (field.type === "json" || dynamicFieldType(field, context) === "json") {
    try {
      values[field.name] = parseJsonFormValue(value);
    } catch {
      return {
        values,
        errors: { [field.name]: `Invalid ${field.label}: expected valid JSON` },
      };
    }
  }
  const errors: Record<string, string> = {};
  const scalarError = validateScalar(field, values[field.name], context);
  if (scalarError) {
    return { values, errors: { [field.name]: scalarError } };
  }
  if (field.type === "collection" && Array.isArray(value)) {
    const result = await validateCollection(field, value, context);
    Object.assign(values, result.values);
    Object.assign(errors, result.errors);
  }
  if (field.schema) {
    // Zod schemas contain non-configurable properties and must not run through Vue proxies.
    const result = await toRaw(field.schema).safeParseAsync(values[field.name]);
    if (result.success) {
      values[field.name] = result.data;
    } else {
      for (const issue of result.error.issues) {
        errors[[field.name, ...issue.path].join(".")] = issue.message;
      }
    }
  }
  return { values, errors };
};

export const validateFormFields = async (
  fields: FormFieldDefinition[],
  values: TableRecord,
  context: FormFieldContext
): Promise<FormValidationResult> => {
  const output = cloneFormValue(values);
  const errors: Record<string, string> = {};
  for (const field of fields) {
    if (fieldIsHidden(field, context) || fieldIsDisabled(field, context)) {
      continue;
    }
    const result = await validateField(field, output[field.name], context);
    Object.assign(output, result.values);
    Object.assign(errors, result.errors);
  }
  return { values: output, errors };
};

export const validateForm = async (
  config: FormConfig,
  values: TableRecord,
  context: FormFieldContext
): Promise<FormValidationResult> => {
  const result = await validateFormFields(config.fields, values, context);
  if (!Object.keys(result.errors).length && config.schema) {
    const parsed = await toRaw(config.schema).safeParseAsync(result.values);
    if (parsed.success) {
      if (
        parsed.data &&
        typeof parsed.data === "object" &&
        !Array.isArray(parsed.data)
      ) {
        result.values = parsed.data as TableRecord;
      } else {
        result.errors.form = "The form schema must return an object";
      }
    } else {
      for (const issue of parsed.error.issues) {
        result.errors[issue.path.join(".") || "form"] = issue.message;
      }
    }
  }
  return result;
};

export const formSubmissionValues = (
  config: FormConfig,
  values: TableRecord,
  initial: TableRecord,
  context: FormFieldContext
): TableRecord => {
  const output =
    config.submitMode === "patch" && context.mode === "edit"
      ? Object.fromEntries(
          config.fields
            .filter(
              (field) =>
                !formValuesEqual(values[field.name], initial[field.name])
            )
            .map((field) => [field.name, values[field.name]])
        )
      : cloneFormValue(values);
  for (const field of config.fields) {
    if (fieldIsHidden(field, context) || fieldIsDisabled(field, context)) {
      delete output[field.name];
    }
  }
  return output;
};

/** Serializable gallery preferences shared by both framework registries. */
type TableGalleryAspectRatio = "portrait" | "square" | "video" | "wide";
type TableGalleryCardSize = "large" | "medium" | "small";
type TableGalleryImageFit = "contain" | "cover";

export interface GalleryViewState {
  imageColumn?: string;
  titleColumn?: string;
  cardColumnIds?: string[];
  aspectRatio?: TableGalleryAspectRatio;
  imageFit?: TableGalleryImageFit;
  cardSize?: TableGalleryCardSize;
  previewSize?: TableGalleryCardSize;
  showCardLabels?: boolean;
}

function normalizeColumnIds(value: unknown): string[] | undefined {
  if (!Array.isArray(value)) {
    return;
  }

  return value
    .filter((item): item is string => typeof item === "string")
    .map((item) => item.trim())
    .filter(Boolean);
}

function normalizeGalleryAspectRatio(
  value: unknown
): TableGalleryAspectRatio | undefined {
  if (
    value === "portrait" ||
    value === "square" ||
    value === "video" ||
    value === "wide"
  ) {
    return value;
  }

  return;
}

function normalizeGalleryImageFit(
  value: unknown
): TableGalleryImageFit | undefined {
  if (value === "contain" || value === "cover") {
    return value;
  }

  return;
}

function normalizeGalleryCardSize(
  value: unknown
): TableGalleryCardSize | undefined {
  if (value === "large" || value === "medium" || value === "small") {
    return value;
  }

  return;
}

export function normalizeGalleryViewConfig(
  config: GalleryViewState | undefined
): GalleryViewState | undefined {
  if (!config) {
    return;
  }

  const normalized: GalleryViewState = {};
  const imageColumn = config.imageColumn?.trim();
  const titleColumn = config.titleColumn?.trim();
  const cardColumnIds = normalizeColumnIds(config.cardColumnIds);
  const aspectRatio = normalizeGalleryAspectRatio(config.aspectRatio);
  const imageFit = normalizeGalleryImageFit(config.imageFit);
  const cardSize = normalizeGalleryCardSize(config.cardSize);
  const previewSize = normalizeGalleryCardSize(config.previewSize);

  if (typeof config.imageColumn === "string") {
    normalized.imageColumn = imageColumn ?? "";
  }
  if (titleColumn) {
    normalized.titleColumn = titleColumn;
  }
  if (cardColumnIds !== undefined) {
    normalized.cardColumnIds = cardColumnIds;
  }
  if (aspectRatio) {
    normalized.aspectRatio = aspectRatio;
  }
  if (imageFit) {
    normalized.imageFit = imageFit;
  }
  if (previewSize) {
    normalized.previewSize = previewSize;
  }
  if (cardSize) {
    normalized.cardSize = cardSize;
  }
  if (typeof config.showCardLabels === "boolean") {
    normalized.showCardLabels = config.showCardLabels;
  }

  return Object.keys(normalized).length > 0 ? normalized : undefined;
}

