/**
 * List view settings shared by the React and Vue editions.
 */

export interface ListViewSettings {
  /** Column used as the line title. */
  titleColumn?: string;
  /** Properties shown after the title, in order. */
  cardColumnIds?: string[];
  /** Show each property's column name before its value. */
  showCardLabels?: boolean;
  /** Let the title wrap onto several lines instead of truncating it. */
  wrap?: boolean;
  /** Show the row actions menu at the end of each line. */
  showActions?: boolean;
  /** Where properties sit: right after the title, or at the end of the line. */
  propertyAlign?: "end" | "start";
  /** Properties shown at most on every screen; unset shows them all. */
  maxProperties?: number;
  /** Properties shown at most on narrow screens (below 768px). */
  mobileMaxProperties?: number;
}

type ListDisplayDefaults = Required<
  Pick<
    ListViewSettings,
    "propertyAlign" | "showActions" | "showCardLabels" | "wrap"
  >
>;

export const LIST_VIEW_DEFAULTS: ListDisplayDefaults = {
  propertyAlign: "end",
  showActions: true,
  showCardLabels: false,
  wrap: false,
};

/** Widths below this use `mobileMaxProperties`, matching the other mobile layouts. */
export const LIST_MOBILE_BREAKPOINT = 768;

const cleanIds = (value: unknown): string[] | undefined =>
  Array.isArray(value)
    ? value
        .filter((item): item is string => typeof item === "string")
        .map((item) => item.trim())
        .filter(Boolean)
    : undefined;

const cleanCount = (value: unknown): number | undefined => {
  const count = Number(value);
  return value !== undefined && Number.isInteger(count) && count >= 0
    ? count
    : undefined;
};

/** Keep only valid list settings; unknown or malformed values are dropped. */
export function normalizeListViewConfig(
  value: unknown
): ListViewSettings | undefined {
  if (!value || typeof value !== "object") {
    return;
  }
  const input = value as Record<string, unknown>;
  const normalized: ListViewSettings = {};
  const title =
    typeof input.titleColumn === "string" ? input.titleColumn.trim() : "";
  if (title) {
    normalized.titleColumn = title;
  }
  const ids = cleanIds(input.cardColumnIds);
  if (ids) {
    normalized.cardColumnIds = ids;
  }
  for (const key of ["showCardLabels", "wrap", "showActions"] as const) {
    if (typeof input[key] === "boolean") {
      normalized[key] = input[key] as boolean;
    }
  }
  if (input.propertyAlign === "start" || input.propertyAlign === "end") {
    normalized.propertyAlign = input.propertyAlign;
  }
  const max = cleanCount(input.maxProperties);
  if (max !== undefined) {
    normalized.maxProperties = max;
  }
  const mobileMax = cleanCount(input.mobileMaxProperties);
  if (mobileMax !== undefined) {
    normalized.mobileMaxProperties = mobileMax;
  }
  return Object.keys(normalized).length ? normalized : undefined;
}

/** Table defaults, then the view's own settings. */
export function resolveListSettings(
  defaults: ListViewSettings | undefined,
  view: ListViewSettings | undefined
): ListViewSettings & ListDisplayDefaults {
  return { ...LIST_VIEW_DEFAULTS, ...defaults, ...view };
}

/** The properties a line shows at this width. */
export function visibleListProperties(
  ids: readonly string[],
  settings: Pick<ListViewSettings, "maxProperties" | "mobileMaxProperties">,
  isMobile: boolean
): string[] {
  const limits = [settings.maxProperties];
  if (isMobile) {
    limits.push(settings.mobileMaxProperties);
  }
  const limit = Math.min(
    ...limits.filter((item): item is number => item !== undefined)
  );
  return Number.isFinite(limit) ? ids.slice(0, limit) : [...ids];
}

/**
 * Manual order belongs to a view, not to the records: the host stores one
 * order per view and sorts by it when a list request uses this sort id.
 */
export const MANUAL_ORDER_SORT_ID = "__manual";

export interface ManualOrderMove {
  /** Saved view whose order changes; `null` is the table's default view. */
  viewId: string | null;
  id: string;
  /** Row now directly above the moved row, if any. */
  previousId?: string;
  /** Row now directly below the moved row, if any. */
  nextId?: string;
}

export function isManualOrder(sorting: unknown): boolean {
  return (
    Array.isArray(sorting) &&
    sorting.some(
      (sort) =>
        typeof sort === "object" &&
        sort !== null &&
        (sort as { id?: unknown }).id === MANUAL_ORDER_SORT_ID
    )
  );
}

/** Sorting a view by its manual order replaces every other sort. */
export const manualOrderSorting = () => [
  { id: MANUAL_ORDER_SORT_ID, desc: false },
];

/** Add the view identity a host needs to apply the view's own order. */
export function withManualOrderView<T extends Record<string, unknown>>(
  params: T,
  sorting: unknown,
  viewId: string | null | undefined
): T & { viewId?: string | null } {
  return isManualOrder(sorting)
    ? { ...params, viewId: viewId ?? null }
    : params;
}

/** The order after moving `id` to `toIndex`, and its new neighbours. */
export function moveInOrder(
  ids: readonly string[],
  id: string,
  toIndex: number
): { ids: string[]; previousId?: string; nextId?: string } | undefined {
  const from = ids.indexOf(id);
  if (from === -1) {
    return;
  }
  const next = ids.filter((item) => item !== id);
  const index = Math.max(0, Math.min(toIndex, next.length));
  if (index === from) {
    return;
  }
  next.splice(index, 0, id);
  return { ids: next, previousId: next[index - 1], nextId: next[index + 1] };
}

/** Marks a reorderable line so a pointer drag can find the line under it. */
export const REORDER_ROW_ATTRIBUTE = "data-reorder-row-id";

/**
 * The reorderable line under a pointer. Pointer events serve mouse, touch and
 * pen alike, unlike native drag and drop, which ignores touch.
 */
export function reorderRowAt(x: number, y: number): string | undefined {
  if (typeof document === "undefined") {
    return;
  }
  return (
    document
      .elementFromPoint(x, y)
      ?.closest(`[${REORDER_ROW_ATTRIBUTE}]`)
      ?.getAttribute(REORDER_ROW_ATTRIBUTE) ?? undefined
  );
}

/** Framework-neutral gallery media contract. Runtime callbacks never enter saved views. */
export interface TableMediaSource {
  url: string;
  type?: "image" | "video" | "audio" | "document" | "file";
  mimeType?: string;
  poster?: string;
  alt?: string;
  tracks?: {
    src: string;
    label?: string;
    srcLang?: string;
    kind?: "captions" | "subtitles";
  }[];
}

export interface TableGalleryMediaConfig {
  /** Opt in to the native viewer and separate preview from record activation. */
  enabled?: boolean;
  urlColumn?: string;
  typeColumn?: string;
  mimeTypeColumn?: string;
  posterColumn?: string;
  hoverPreview?: boolean;
  getMedia?: (row: Record<string, unknown>) => TableMediaSource | undefined;
}

export interface GalleryMediaItem {
  id: string;
  title: string;
  source?: TableMediaSource;
}

export type TableGalleryPreviewSize = "small" | "medium" | "large";

/** Relative asset paths and HTTP(S) are supported; executable and opaque schemes are not. */
export function mediaUrl(value: unknown): string | undefined {
  if (typeof value !== "string" || !value.trim()) {
    return;
  }
  const source = value.trim();
  try {
    const url = new URL(source, "https://yayaw.invalid/");
    if (url.protocol === "https:" || url.protocol === "http:") {
      return source;
    }
  } catch {
    return;
  }
}

export function resolveGalleryMedia(
  row: Record<string, unknown>,
  config?: TableGalleryMediaConfig,
  imageColumn?: string
): TableMediaSource | undefined {
  if (config?.enabled !== true) {
    return;
  }
  const custom = config.getMedia?.(row);
  const url = mediaUrl(
    custom?.url ?? row[config.urlColumn ?? imageColumn ?? ""]
  );
  if (!url) {
    return;
  }
  const mimeType = String(
    custom?.mimeType ?? row[config.mimeTypeColumn ?? ""] ?? ""
  );
  const candidate = custom?.type ?? row[config.typeColumn ?? ""];
  let type: NonNullable<TableMediaSource["type"]> = "file";
  if (
    ["image", "video", "audio", "document", "file"].includes(String(candidate))
  ) {
    type = candidate as NonNullable<TableMediaSource["type"]>;
  } else if (mimeType.startsWith("image/")) {
    type = "image";
  } else if (mimeType.startsWith("video/")) {
    type = "video";
  } else if (mimeType.startsWith("audio/")) {
    type = "audio";
  } else if (mimeType === "application/pdf") {
    type = "document";
  } else if (!config.urlColumn && imageColumn) {
    type = "image";
  }
  return {
    ...custom,
    url,
    type,
    mimeType,
    poster: mediaUrl(custom?.poster ?? row[config.posterColumn ?? ""]),
    tracks: custom?.tracks?.flatMap((track) => {
      const src = mediaUrl(track.src);
      return src ? [{ ...track, src }] : [];
    }),
  };
}

/** M preserves the configured ratio; S/L scale only its height, not the card width. */
export function galleryAspectRatio(
  ratio = "wide",
  size?: TableGalleryPreviewSize
): string {
  const ratios: Record<string, number> = {
    portrait: 3 / 4,
    square: 1,
    video: 16 / 9,
    wide: 16 / 10,
  };
  const factor = ({ small: 0.7, medium: 1, large: 1.35 } as const)[
    size ?? "medium"
  ];
  return String((ratios[ratio] ?? 16 / 10) / factor);
}

