function pauseMedia(root: HTMLElement): void {
  for (const media of root.querySelectorAll("video,audio")) {
    (media as HTMLMediaElement).pause();
  }
}

function nativeMedia(source: TableMediaSource, title: string): HTMLElement {
  if (source.type === "image") {
    const image = document.createElement("img");
    image.src = source.url;
    image.alt = source.alt ?? title;
    return image;
  }
  if (source.type === "video" || source.type === "audio") {
    const media = document.createElement(source.type);
    media.src = source.url;
    media.controls = true;
    media.preload = "metadata";
    media.setAttribute("aria-label", title);
    if (source.type === "video") {
      const video = media as HTMLVideoElement;
      video.playsInline = true;
      if (source.poster) {
        video.poster = source.poster;
      }
    }
    for (const track of source.tracks ?? []) {
      const element = document.createElement("track");
      element.src = track.src;
      element.kind = track.kind ?? "captions";
      element.label = track.label ?? "";
      element.srclang = track.srcLang ?? "";
      media.append(element);
    }
    return media;
  }
  if (source.type === "document" && source.mimeType === "application/pdf") {
    const frame = document.createElement("iframe");
    frame.src = source.url;
    frame.title = title;
    frame.referrerPolicy = "no-referrer";
    return frame;
  }
  return document.createElement("div");
}

/** One native, accessible viewer shared by both framework adapters. */
export function openMediaViewer({
  items,
  index,
  labels,
  onInfo,
  returnFocus,
}: {
  items: readonly GalleryMediaItem[];
  index: number;
  labels: MediaViewerLabels;
  onInfo?: (id: string) => void;
  returnFocus?: HTMLElement;
}): { destroy: () => void } {
  const dialog = document.createElement("dialog");
  dialog.className = "yayaw-media-viewer";
  // Portals inherit the originating table's theme, including scoped Vue themes.
  if (returnFocus) {
    const style = getComputedStyle(returnFocus);
    for (const token of [
      "background",
      "foreground",
      "muted",
      "border",
      "primary",
    ]) {
      const value =
        style.getPropertyValue(`--${token}`).trim() ||
        style.getPropertyValue(`--yayaw-${token}`).trim();
      if (value) {
        dialog.style.setProperty(`--${token}`, value);
      }
    }
  }
  dialog.setAttribute("aria-label", labels.preview);
  const header = document.createElement("header");
  const title = document.createElement("h2");
  const counter = document.createElement("span");
  counter.setAttribute("aria-live", "polite");
  const content = document.createElement("div");
  content.className = "yayaw-media-viewer-content";
  const footer = document.createElement("footer");
  let current = Math.max(0, Math.min(index, items.length - 1));
  let destroyed = false;
  const destroy = () => {
    if (destroyed) {
      return;
    }
    destroyed = true;
    pauseMedia(dialog);
    dialog.close();
    dialog.remove();
    if (returnFocus?.isConnected) {
      returnFocus.focus({ preventScroll: true });
    }
  };
  const button = (label: string, action: () => void) => {
    const control = document.createElement("button");
    control.type = "button";
    control.textContent = label;
    control.addEventListener("click", action);
    return control;
  };
  const previous = button(labels.previous, () => show(current - 1));
  const next = button(labels.next, () => show(current + 1));
  const info = onInfo
    ? button(labels.info, () => {
        const id = items[current]?.id;
        destroy();
        if (id) {
          onInfo(id);
        }
      })
    : undefined;
  const full = button(labels.fullscreen, () => {
    if (document.fullscreenElement === dialog) {
      document.exitFullscreen?.().catch(() => undefined);
    } else {
      dialog.requestFullscreen?.().catch(() => undefined);
    }
  });
  full.hidden = typeof dialog.requestFullscreen !== "function";
  const close = button(labels.close, destroy);
  const link = document.createElement("a");
  link.textContent = labels.openFile;
  link.target = "_blank";
  link.rel = "noopener noreferrer";
  const fallback = () => {
    pauseMedia(content);
    content.replaceChildren();
    const message = document.createElement("p");
    message.textContent = labels.unavailable;
    content.append(message);
  };
  function show(target: number): void {
    const item = items[target];
    if (!item) {
      return;
    }
    current = target;
    title.textContent = item.title;
    counter.textContent = `${current + 1} / ${items.length}`;
    previous.disabled = current === 0;
    next.disabled = current === items.length - 1;
    pauseMedia(content);
    content.replaceChildren();
    link.hidden = !mediaUrl(item.source?.url);
    if (!item.source || link.hidden) {
      fallback();
      return;
    }
    link.href = item.source.url;
    const media = nativeMedia(item.source, item.title);
    if (media.tagName === "DIV") {
      fallback();
    } else {
      media.addEventListener("error", fallback, { once: true });
      content.append(media);
    }
  }
  header.append(title, counter);
  if (info) {
    header.append(info);
  }
  header.append(full, close);
  footer.append(previous, link, next);
  dialog.append(header, content, footer);
  dialog.addEventListener("cancel", (event) => {
    event.preventDefault();
    destroy();
  });
  dialog.addEventListener("close", destroy);
  dialog.addEventListener("click", (event) => {
    if (event.target === dialog) {
      destroy();
    }
  });
  dialog.addEventListener("keydown", (event) => {
    if ((event.target as HTMLElement).closest("video,audio,input,textarea")) {
      return;
    }
    if (event.key === "ArrowLeft") {
      event.preventDefault();
      show(current - 1);
    }
    if (event.key === "ArrowRight") {
      event.preventDefault();
      show(current + 1);
    }
    if (event.key === "Home") {
      event.preventDefault();
      show(0);
    }
    if (event.key === "End") {
      event.preventDefault();
      show(items.length - 1);
    }
  });
  document.body.append(dialog);
  show(current);
  dialog.showModal();
  close.focus();
  return { destroy };
}

/** A muted hover sample never changes the full viewer's playback position. */
export function attachMediaThumbnail(
  host: HTMLElement,
  source: TableMediaSource | undefined,
  title: string,
  options: {
    fit: "cover" | "contain";
    hoverPreview?: boolean;
    previewLabel: string;
    onOpen: () => void;
  }
): () => void {
  const button = document.createElement("button");
  button.type = "button";
  button.className = "yayaw-media-thumbnail";
  button.setAttribute("aria-label", `${options.previewLabel}: ${title}`);
  button.addEventListener("click", (event) => {
    event.stopPropagation();
    options.onOpen();
  });
  let timer: ReturnType<typeof setTimeout> | undefined;
  let video: HTMLVideoElement | undefined;
  if (source?.type === "video") {
    video = document.createElement("video");
    video.src = source.url;
    video.muted = true;
    video.playsInline = true;
    video.preload = "metadata";
    if (source.poster) {
      video.poster = source.poster;
    }
    video.style.objectFit = options.fit;
    video.setAttribute("aria-hidden", "true");
    button.append(video);
  } else if (source?.type === "image" || source?.poster) {
    const image = document.createElement("img");
    image.src = source.poster ?? source.url;
    image.alt = "";
    image.loading = "lazy";
    image.style.objectFit = options.fit;
    button.append(image);
  }
  const fallback = document.createElement("span");
  fallback.className = "yayaw-media-file";
  fallback.textContent =
    source?.type === "video"
      ? "▷"
      : (source?.mimeType?.split("/")[1]?.toUpperCase() ??
        source?.type?.toUpperCase() ??
        "—");
  fallback.setAttribute("aria-hidden", "true");
  if (button.firstChild) {
    button.firstChild.addEventListener(
      "error",
      () => button.replaceChildren(fallback),
      { once: true }
    );
  } else {
    button.append(fallback);
  }
  if (source?.type === "video" || source?.type === "audio") {
    const cue = document.createElement("span");
    cue.className = "yayaw-media-play-cue";
    cue.textContent = "▶";
    cue.setAttribute("aria-hidden", "true");
    button.append(cue);
  }
  const stop = () => {
    clearTimeout(timer);
    if (video) {
      video.pause();
      video.currentTime = 0;
    }
  };
  const play = () => {
    if (
      !(video && options.hoverPreview) ||
      window.matchMedia("(prefers-reduced-motion: reduce)").matches
    ) {
      return;
    }
    video.play().catch(() => undefined);
    clearTimeout(timer);
    timer = setTimeout(stop, 5000);
  };
  button.addEventListener("pointerenter", play);
  button.addEventListener("pointerleave", stop);
  button.addEventListener("focus", play);
  button.addEventListener("blur", stop);
  host.replaceChildren(button);
  return () => {
    stop();
    host.replaceChildren();
  };
}

import { planningDefaults } from "./engine";
import {
  assertPlanningContext,
  createPlanningTransactions,
} from "./transactions";
import {
  type PlanningContext,
  PlanningError,
  type PlanningMutation,
  type PlanningPreview,
  type PlanningSnapshot,
  planningKey,
  type TablePlanningActions,
  type TablePlanningConfig,
} from "./types";

/** A complete executable adapter example. Production adapters enforce the same checks in a database transaction. */
export function createMemoryPlanningAdapter(input: {
  snapshot: PlanningSnapshot;
  config: TablePlanningConfig;
  /** Runs at preview and again at commit, before the final revision check. */
  validate?: (
    snapshot: PlanningSnapshot,
    mutations: PlanningMutation[],
    preview: PlanningPreview
  ) => void | Promise<void>;
}) {
  let current = structuredClone(input.snapshot);
  const config = planningDefaults(input.config);
  const actions = createPlanningTransactions({
    config: input.config,
    read: () => current,
    load: (context) => {
      assertPlanningContext(current, config.scopeId, context);
      context.signal?.throwIfAborted();
      return Promise.resolve(structuredClone(current));
    },
    commit: ({ snapshot }) => {
      current = { ...snapshot, revision: crypto.randomUUID() };
      return structuredClone(current);
    },
    validate: input.validate,
  });
  return {
    actions,
    getSnapshot: (): PlanningSnapshot => structuredClone(current),
    /** Simulate an external transaction, including permission/calendar changes, using a fresh revision. */
    replaceSnapshot(snapshot: PlanningSnapshot): void {
      current = { ...structuredClone(snapshot), revision: crypto.randomUUID() };
    },
  };
}

function addUnique<T>(
  items: T[],
  seen: Set<string>,
  key: (item: T) => string,
  target: T[],
  code: string
): void {
  for (const item of items) {
    const id = key(item);
    if (seen.has(id)) {
      throw new PlanningError(
        code,
        "A graph page contains a duplicate identity."
      );
    }
    seen.add(id);
    target.push(item);
  }
}
/** Page the graph independently of table filters. Every page must belong to the same revision. */
export async function loadPlanningSnapshot(
  actions: TablePlanningActions,
  context: PlanningContext,
  signal?: AbortSignal,
  onPage?: (snapshot: PlanningSnapshot) => void
): Promise<PlanningSnapshot> {
  let result: PlanningSnapshot | undefined;
  let cursor: string | undefined;
  const cursors = new Set<string>();
  const taskIds = new Set<string>();
  const dependencyIds = new Set<string>();
  for (let page = 0; page < 1000; page += 1) {
    signal?.throwIfAborted();
    const next = await actions.load({ ...context, cursor, signal });
    signal?.throwIfAborted();
    if (
      next.scopeId !== context.scopeId ||
      (result && result.revision !== next.revision)
    ) {
      throw new PlanningError(
        "stale-graph",
        "The planning changed while its graph was loading. Retry the load."
      );
    }
    if (!result) {
      result = { ...next, tasks: [], dependencies: [] };
    }
    addUnique(
      next.tasks,
      taskIds,
      (task) => planningKey(task.ref),
      result.tasks,
      "duplicate-task"
    );
    addUnique(
      next.dependencies,
      dependencyIds,
      (edge) => edge.id,
      result.dependencies,
      "duplicate-dependency"
    );
    result.complete = next.complete;
    result.nextCursor = next.nextCursor;
    onPage?.(structuredClone(result));
    if (!next.nextCursor) {
      return result;
    }
    if (cursors.has(next.nextCursor)) {
      throw new PlanningError(
        "invalid-cursor",
        "The planning loader repeated a page cursor."
      );
    }
    cursors.add(next.nextCursor);
    cursor = next.nextCursor;
  }
  throw new PlanningError(
    "incomplete-graph",
    "The planning graph exceeded the page limit."
  );
}

import {
  type PlanningCalendar,
  PlanningError,
  type PlanningSnapshot,
  type PlanningTask,
} from "./types";

const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;
const DAY_MS = 86_400_000;
/** Integer UTC day arithmetic avoids daylight-saving and browser time-zone drift. */
export function dateDay(value: string): number {
  if (!DATE_PATTERN.test(value)) {
    throw new PlanningError("invalid-date", `Invalid civil date: ${value}`);
  }
  const time = Date.parse(`${value}T00:00:00.000Z`);
  if (
    !Number.isFinite(time) ||
    new Date(time).toISOString().slice(0, 10) !== value
  ) {
    throw new PlanningError("invalid-date", `Invalid civil date: ${value}`);
  }
  return time / DAY_MS;
}
export function dayDate(day: number): string {
  if (!Number.isInteger(day)) {
    throw new PlanningError("invalid-date", "A date must use whole days.");
  }
  return new Date(day * DAY_MS).toISOString().slice(0, 10);
}
export const isWorkingDay = (
  day: number,
  calendar: PlanningCalendar
): boolean =>
  calendar.exceptions?.[dayDate(day)] ??
  calendar.workingDays.includes((((day + 4) % 7) + 7) % 7);

export function seekWorkingDay(
  day: number,
  direction: 1 | -1,
  calendar: PlanningCalendar,
  limit = 36_600
): number {
  let current = day;
  for (let count = 0; count < limit; count += 1, current += direction) {
    if (isWorkingDay(current, calendar)) {
      return current;
    }
  }
  throw new PlanningError(
    "calendar-exhausted",
    `No working date found in calendar ${calendar.id}.`
  );
}
export function addWorkingDays(
  day: number,
  amount: number,
  calendar: PlanningCalendar,
  limit = 36_600
): number {
  if (!Number.isSafeInteger(amount) || Math.abs(amount) > limit) {
    throw new PlanningError(
      "invalid-duration",
      "Working-day offsets must be bounded integers."
    );
  }
  const direction = amount < 0 ? -1 : 1;
  let remaining = Math.abs(amount);
  let current = day;
  for (let visited = 0; remaining > 0 && visited < limit; visited += 1) {
    current += direction;
    if (isWorkingDay(current, calendar)) {
      remaining -= 1;
    }
  }
  if (remaining) {
    throw new PlanningError(
      "calendar-exhausted",
      `Offset exceeds calendar ${calendar.id}.`
    );
  }
  return current;
}
export function workingDuration(
  start: number,
  end: number,
  calendar: PlanningCalendar,
  limit = 36_600
): number {
  if (end < start || end - start > limit) {
    throw new PlanningError(
      "invalid-duration",
      "Task dates are reversed or exceed the supported horizon."
    );
  }
  let duration = 0;
  for (let day = start; day <= end; day += 1) {
    if (isWorkingDay(day, calendar)) {
      duration += 1;
    }
  }
  if (!duration) {
    throw new PlanningError(
      "invalid-duration",
      "A scheduled task must include a working day."
    );
  }
  return duration;
}
export function taskCalendar(
  task: PlanningTask,
  snapshot: PlanningSnapshot
): PlanningCalendar {
  const source = snapshot.sources.find((item) => item.id === task.ref.source);
  if (!source) {
    throw new PlanningError(
      "missing-source",
      `Unknown source ${task.ref.source}.`
    );
  }
  const id = task.calendarId ?? source.calendarId ?? snapshot.defaultCalendarId;
  const calendar = snapshot.calendars.find((item) => item.id === id);
  if (!calendar) {
    throw new PlanningError("missing-calendar", `Unknown calendar ${id}.`);
  }
  return calendar;
}

import {
  addWorkingDays,
  dateDay,
  dayDate,
  seekWorkingDay,
  taskCalendar,
  workingDuration,
} from "./calendar";
import {
  type PlanningChange,
  type PlanningDependency,
  PlanningError,
  type PlanningMutation,
  type PlanningPreview,
  type PlanningRef,
  type PlanningSnapshot,
  type PlanningTask,
  planningKey,
  type TablePlanningConfig,
} from "./types";

export function planningDefaults(
  config: TablePlanningConfig
): Required<TablePlanningConfig> {
  return {
    ...config,
    allowDateEdit: config.allowDateEdit ?? true,
    allowDependencyEdit: config.allowDependencyEdit ?? true,
    allowHierarchyEdit: config.allowHierarchyEdit ?? true,
    allowCrossTableDependencies: config.allowCrossTableDependencies ?? true,
    allowSummaryMove: config.allowSummaryMove ?? true,
    hierarchy: config.hierarchy ?? true,
    parentDates: config.parentDates ?? "rollup",
    dependencyTypes: config.dependencyTypes ?? ["FS", "SS", "FF", "SF"],
    scheduling: config.scheduling ?? "preview",
    maxCalendarSearchDays: config.maxCalendarSearchDays ?? 36_600,
  };
}
interface Index {
  tasks: Map<string, PlanningTask>;
  children: Map<string, PlanningTask[]>;
  order: Map<string, number>;
}
const isRollup = (config: TablePlanningConfig): boolean =>
  config.hierarchy !== false && config.parentDates !== "independent";

function validateCalendars(
  snapshot: PlanningSnapshot,
  config: TablePlanningConfig
): void {
  const sourceIds = new Set(snapshot.sources.map((source) => source.id));
  const calendarIds = new Set(
    snapshot.calendars.map((calendar) => calendar.id)
  );
  if (
    sourceIds.size !== snapshot.sources.length ||
    calendarIds.size !== snapshot.calendars.length
  ) {
    throw new PlanningError(
      "duplicate-identity",
      "Source and calendar IDs must be unique."
    );
  }
  const limit = config.maxCalendarSearchDays ?? 36_600;
  if (!Number.isSafeInteger(limit) || limit < 1 || limit > 366_000) {
    throw new PlanningError(
      "invalid-horizon",
      "The calendar search horizon must be between 1 and 366000 days."
    );
  }
  for (const calendar of snapshot.calendars) {
    if (
      !calendar.id ||
      calendar.workingDays.some(
        (day) => !Number.isInteger(day) || day < 0 || day > 6
      )
    ) {
      throw new PlanningError(
        "invalid-calendar",
        "Working weekdays must be integers between 0 and 6."
      );
    }
    for (const [date, working] of Object.entries(calendar.exceptions ?? {})) {
      dateDay(date);
      if (typeof working !== "boolean") {
        throw new PlanningError(
          "invalid-calendar",
          "Calendar exceptions must be booleans."
        );
      }
    }
  }
}
type Connect = (from: string, to: string) => void;
function indexTasks(
  snapshot: PlanningSnapshot,
  tasks: Map<string, PlanningTask>,
  indegree: Map<string, number>,
  connect: Connect
): void {
  for (const task of snapshot.tasks) {
    const key = planningKey(task.ref);
    if (!(task.ref.id && task.ref.source) || tasks.has(key)) {
      throw new PlanningError(
        "duplicate-task",
        "Every task needs a unique source and record ID."
      );
    }
    tasks.set(key, task);
    indegree.set(`${key}:in`, 0);
    indegree.set(`${key}:out`, 0);
    connect(`${key}:in`, `${key}:out`);
    if ((task.start == null) !== (task.end == null)) {
      throw new PlanningError(
        "incomplete-dates",
        `Both dates are required for ${task.label}.`
      );
    }
    if (
      task.start != null &&
      task.end != null &&
      dateDay(task.end) < dateDay(task.start)
    ) {
      throw new PlanningError(
        "invalid-duration",
        `Reversed dates for ${task.label}.`
      );
    }
    taskCalendar(task, snapshot);
  }
}
function indexHierarchy(
  snapshot: PlanningSnapshot,
  config: TablePlanningConfig,
  tasks: Map<string, PlanningTask>,
  children: Map<string, PlanningTask[]>,
  connect: Connect
): void {
  for (const task of snapshot.tasks) {
    if (!task.parent) {
      continue;
    }
    const parentKey = planningKey(task.parent);
    if (!tasks.has(parentKey)) {
      throw new PlanningError(
        "missing-parent",
        `The parent of ${task.label} is unavailable.`
      );
    }
    const group = children.get(parentKey) ?? [];
    group.push(task);
    children.set(parentKey, group);
    const seen = new Set([planningKey(task.ref)]);
    let current: PlanningTask | undefined = tasks.get(parentKey);
    while (current) {
      const key = planningKey(current.ref);
      if (seen.has(key)) {
        throw new PlanningError(
          "hierarchy-cycle",
          "The hierarchy contains a cycle."
        );
      }
      seen.add(key);
      current = current.parent
        ? tasks.get(planningKey(current.parent))
        : undefined;
    }
    if (isRollup(config)) {
      const key = planningKey(task.ref);
      connect(`${parentKey}:in`, `${key}:in`);
      connect(`${key}:out`, `${parentKey}:out`);
    }
  }
}
function indexDependencies(
  snapshot: PlanningSnapshot,
  tasks: Map<string, PlanningTask>,
  connect: Connect
): void {
  const ids = new Set<string>();
  for (const dependency of snapshot.dependencies) {
    const from = planningKey(dependency.from);
    const to = planningKey(dependency.to);
    if (!dependency.id || ids.has(dependency.id)) {
      throw new PlanningError(
        "duplicate-dependency",
        "Dependency IDs must be unique."
      );
    }
    ids.add(dependency.id);
    if (!(tasks.has(from) && tasks.has(to))) {
      throw new PlanningError(
        "missing-task",
        "A dependency references an unavailable task."
      );
    }
    if (from === to) {
      throw new PlanningError(
        "dependency-cycle",
        "A task cannot depend on itself."
      );
    }
    if (
      !(
        ["FS", "SS", "FF", "SF"].includes(dependency.type) &&
        Number.isSafeInteger(dependency.lag ?? 0)
      )
    ) {
      throw new PlanningError(
        "invalid-dependency",
        "A dependency needs a supported type and a whole-day offset."
      );
    }
    if (
      dependency.lagUnit &&
      !["workingDays", "calendarDays"].includes(dependency.lagUnit)
    ) {
      throw new PlanningError(
        "invalid-dependency",
        "Unknown dependency calendar unit."
      );
    }
    connect(`${from}:out`, `${to}:in`);
  }
}
function topologicalOrder(
  indegree: Map<string, number>,
  edges: Map<string, Set<string>>
): Map<string, number> {
  const queue = [...indegree]
    .filter(([, count]) => count === 0)
    .map(([key]) => key);
  const order = new Map<string, number>();
  for (let i = 0; i < queue.length; i += 1) {
    const key = queue[i];
    if (key === undefined) {
      continue;
    }
    order.set(key, i);
    for (const next of edges.get(key) ?? []) {
      const count = (indegree.get(next) ?? 0) - 1;
      indegree.set(next, count);
      if (!count) {
        queue.push(next);
      }
    }
  }
  if (order.size !== indegree.size) {
    throw new PlanningError(
      "dependency-cycle",
      "Dependencies contain a cycle, including an ancestor or group relationship."
    );
  }
  return order;
}

/** Split task entry/exit nodes encode group constraints without quadratic leaf expansion. */
export function indexPlanning(
  snapshot: PlanningSnapshot,
  config: TablePlanningConfig
): Index {
  validateCalendars(snapshot, config);
  const tasks = new Map<string, PlanningTask>();
  const children = new Map<string, PlanningTask[]>();
  const edges = new Map<string, Set<string>>();
  const indegree = new Map<string, number>();
  const connect = (from: string, to: string): void => {
    const destinations = edges.get(from) ?? new Set<string>();
    if (!destinations.has(to)) {
      destinations.add(to);
      indegree.set(to, (indegree.get(to) ?? 0) + 1);
    }
    edges.set(from, destinations);
  };
  indexTasks(snapshot, tasks, indegree, connect);
  indexHierarchy(snapshot, config, tasks, children, connect);
  indexDependencies(snapshot, tasks, connect);
  const order = topologicalOrder(indegree, edges);
  return { tasks, children, order };
}

function rollupDates(index: Index, config: TablePlanningConfig): void {
  if (!isRollup(config)) {
    return;
  }
  const sorted = [...index.tasks.values()].sort(
    (a, b) =>
      (index.order.get(`${planningKey(a.ref)}:out`) ?? 0) -
      (index.order.get(`${planningKey(b.ref)}:out`) ?? 0)
  );
  for (const task of sorted) {
    const children = index.children.get(planningKey(task.ref));
    if (!children?.length) {
      continue;
    }
    // Unknown descendant dates must not produce a misleading partial summary.
    if (children.some((child) => !(child.start && child.end))) {
      task.start = null;
      task.end = null;
      continue;
    }
    task.start = dayDate(
      Math.min(...children.map((child) => dateDay(child.start as string)))
    );
    task.end = dayDate(
      Math.max(...children.map((child) => dateDay(child.end as string)))
    );
  }
}
export function resolvedPlanningSnapshot(
  snapshot: PlanningSnapshot,
  config: TablePlanningConfig
): PlanningSnapshot {
  const copy = structuredClone(snapshot);
  rollupDates(indexPlanning(copy, config), config);
  syncRecords(copy);
  return copy;
}
function requireTask(index: Index, ref: PlanningRef): PlanningTask {
  const task = index.tasks.get(planningKey(ref));
  if (!task) {
    throw new PlanningError(
      "missing-task",
      "The requested task is unavailable."
    );
  }
  return task;
}
function requireEditable(task: PlanningTask): void {
  if (task.editable === false) {
    throw new PlanningError(
      "permission-denied",
      `Changes to ${task.label} are not permitted.`
    );
  }
}
function requireFlag(value: boolean | undefined): void {
  if (value === false) {
    throw new PlanningError(
      "feature-disabled",
      "This planning operation is disabled."
    );
  }
}
function requireDates(task: PlanningTask): [number, number] {
  if (!(task.start && task.end)) {
    throw new PlanningError(
      "unscheduled-task",
      `Schedule ${task.label} before recalculating its dependencies.`
    );
  }
  return [dateDay(task.start), dateDay(task.end)];
}

function moveTask(
  task: PlanningTask,
  days: number,
  snapshot: PlanningSnapshot,
  index: Index,
  config: Required<TablePlanningConfig>
): void {
  if (
    !Number.isSafeInteger(days) ||
    Math.abs(days) > config.maxCalendarSearchDays
  ) {
    throw new PlanningError(
      "invalid-duration",
      "A move must use a bounded whole-day offset."
    );
  }
  requireEditable(task);
  const children = isRollup(config)
    ? index.children.get(planningKey(task.ref))
    : undefined;
  if (children?.length) {
    requireFlag(config.allowSummaryMove);
    for (const child of children) {
      moveTask(child, days, snapshot, index, config);
    }
    rollupDates(index, config);
    return;
  }
  const [start, end] = requireDates(task);
  const calendar = taskCalendar(task, snapshot);
  const duration = workingDuration(
    start,
    end,
    calendar,
    config.maxCalendarSearchDays
  );
  const next = seekWorkingDay(
    start + days,
    1,
    calendar,
    config.maxCalendarSearchDays
  );
  task.start = dayDate(next);
  task.end = dayDate(
    addWorkingDays(next, duration - 1, calendar, config.maxCalendarSearchDays)
  );
}

function mutateRecordParent(
  patch: Record<string, unknown>,
  field: string,
  task: PlanningTask,
  snapshot: PlanningSnapshot,
  index: Index,
  config: Required<TablePlanningConfig>
): void {
  const value = patch[field];
  if (value != null && typeof value !== "string" && typeof value !== "number") {
    throw new PlanningError(
      "invalid-parent",
      "Record parent values must be IDs or null; use a parent mutation for cross-source references."
    );
  }
  mutateTask(
    {
      type: "parent",
      ref: task.ref,
      parent:
        value == null || value === ""
          ? null
          : { source: task.ref.source, id: String(value) },
    },
    snapshot,
    index,
    config
  );
}
function validateRecordDates(start: unknown, end: unknown): void {
  if (
    (start != null && typeof start !== "string") ||
    (end != null && typeof end !== "string")
  ) {
    throw new PlanningError(
      "invalid-date",
      "Mapped planning fields require civil dates or null."
    );
  }
}
function mutateRecord(
  mutation: Extract<PlanningMutation, { type: "record" }>,
  task: PlanningTask,
  snapshot: PlanningSnapshot,
  index: Index,
  config: Required<TablePlanningConfig>
): void {
  const fields = snapshot.sources.find(
    (source) => source.id === task.ref.source
  )?.fields;
  if (!fields) {
    throw new PlanningError(
      "missing-fields",
      "Record editing requires source field mappings."
    );
  }
  // Match JSON transport semantics: undefined means omitted, null clears a field.
  const patch = Object.fromEntries(
    Object.entries(mutation.patch).filter(([, value]) => value !== undefined)
  );
  if (fields.parent && Object.hasOwn(patch, fields.parent)) {
    mutateRecordParent(patch, fields.parent, task, snapshot, index, config);
  }
  if (Object.hasOwn(patch, fields.start) || Object.hasOwn(patch, fields.end)) {
    const start = Object.hasOwn(patch, fields.start)
      ? patch[fields.start]
      : task.start;
    const end = Object.hasOwn(patch, fields.end) ? patch[fields.end] : task.end;
    validateRecordDates(start, end);
    mutateTask(
      {
        type: "dates",
        ref: task.ref,
        start: start as string | null,
        end: end as string | null,
      },
      snapshot,
      index,
      config
    );
  }
  if (fields.calendar && Object.hasOwn(patch, fields.calendar)) {
    requireFlag(config.allowDateEdit);
    const calendarId = patch[fields.calendar];
    if (calendarId != null && typeof calendarId !== "string") {
      throw new PlanningError(
        "missing-calendar",
        "Calendar IDs must be strings."
      );
    }
    task.calendarId = calendarId as string | undefined;
    taskCalendar(task, snapshot);
  }
  task.record = { ...task.record, ...patch };
  if (fields.title && Object.hasOwn(patch, fields.title)) {
    task.label = String(patch[fields.title] ?? "");
  }
}
function mutateTask(
  mutation: Exclude<
    PlanningMutation,
    { type: "dependency.put" | "dependency.remove" }
  >,
  snapshot: PlanningSnapshot,
  index: Index,
  config: Required<TablePlanningConfig>
): void {
  const task = requireTask(index, mutation.ref);
  requireEditable(task);
  if (mutation.type === "parent") {
    requireFlag(config.allowHierarchyEdit);
    requireFlag(config.hierarchy);
    if (mutation.parent) {
      requireEditable(requireTask(index, mutation.parent));
    }
    task.parent = mutation.parent;
    return;
  }
  if (mutation.type === "record") {
    mutateRecord(mutation, task, snapshot, index, config);
    return;
  }
  requireFlag(config.allowDateEdit);
  if (mutation.type === "move") {
    moveTask(task, mutation.days, snapshot, index, config);
    return;
  }
  const group = isRollup(config) && index.children.has(planningKey(task.ref));
  if (group) {
    const [start, end] = requireDates(task);
    if (
      !(mutation.start && mutation.end) ||
      dateDay(mutation.end) - dateDay(mutation.start) !== end - start
    ) {
      throw new PlanningError(
        "summary-resize",
        "Move the group or edit its children to change a summary duration."
      );
    }
    moveTask(task, dateDay(mutation.start) - start, snapshot, index, config);
    return;
  }
  if ((mutation.start == null) !== (mutation.end == null)) {
    throw new PlanningError(
      "incomplete-dates",
      "Provide both dates or clear both dates."
    );
  }
  if (mutation.start && mutation.end) {
    workingDuration(
      dateDay(mutation.start),
      dateDay(mutation.end),
      taskCalendar(task, snapshot),
      config.maxCalendarSearchDays
    );
  }
  task.start = mutation.start;
  task.end = mutation.end;
}

function dependencyBound(
  dependency: PlanningDependency,
  from: PlanningTask,
  to: PlanningTask,
  snapshot: PlanningSnapshot,
  config: Required<TablePlanningConfig>
): number {
  const [start, end] = requireDates(from);
  const calendar = taskCalendar(to, snapshot);
  // Finish boundaries are exclusive internally. Public end dates remain inclusive.
  const sourceBoundary = dependency.type[0] === "F" ? end + 1 : start;
  const endpoint = sourceBoundary - (dependency.type[1] === "F" ? 1 : 0);
  const lag = dependency.lag ?? 0;
  if (dependency.lagUnit === "calendarDays") {
    return seekWorkingDay(
      endpoint + lag,
      1,
      calendar,
      config.maxCalendarSearchDays
    );
  }
  return addWorkingDays(
    seekWorkingDay(endpoint, 1, calendar, config.maxCalendarSearchDays),
    lag,
    calendar,
    config.maxCalendarSearchDays
  );
}
function syncRecords(snapshot: PlanningSnapshot): void {
  for (const task of snapshot.tasks) {
    const fields = snapshot.sources.find(
      (source) => source.id === task.ref.source
    )?.fields;
    if (!(fields && task.record)) {
      continue;
    }
    task.record[fields.start] = task.start;
    task.record[fields.end] = task.end;
    if (fields.parent) {
      // Scalar columns can only represent parents from the same source.
      task.record[fields.parent] =
        task.parent?.source === task.ref.source ? task.parent.id : null;
    }
    if (fields.calendar) {
      task.record[fields.calendar] = task.calendarId ?? null;
    }
  }
}
function mutateDependency(
  mutation: Extract<
    PlanningMutation,
    { type: "dependency.put" | "dependency.remove" }
  >,
  next: PlanningSnapshot,
  index: Index,
  config: Required<TablePlanningConfig>
): void {
  requireFlag(config.allowDependencyEdit);
  const existing = next.dependencies.find(
    (item) =>
      item.id ===
      (mutation.type === "dependency.put"
        ? mutation.dependency.id
        : mutation.id)
  );
  if (existing) {
    requireEditable(requireTask(index, existing.from));
    requireEditable(requireTask(index, existing.to));
  }
  if (mutation.type === "dependency.remove") {
    if (!existing) {
      throw new PlanningError(
        "missing-dependency",
        "The dependency no longer exists."
      );
    }
    next.dependencies = next.dependencies.filter(
      (item) => item.id !== mutation.id
    );
  } else {
    const dependency = structuredClone(mutation.dependency);
    if (!config.dependencyTypes.includes(dependency.type)) {
      throw new PlanningError(
        "feature-disabled",
        "This dependency type is disabled."
      );
    }
    if (
      !config.allowCrossTableDependencies &&
      dependency.from.source !== dependency.to.source
    ) {
      throw new PlanningError(
        "feature-disabled",
        "Cross-table dependencies are disabled."
      );
    }
    requireEditable(requireTask(index, dependency.from));
    requireEditable(requireTask(index, dependency.to));
    next.dependencies = next.dependencies.filter(
      (item) => item.id !== dependency.id
    );
    next.dependencies.push(dependency);
  }
}
function moveGroupToBound(
  task: PlanningTask,
  dependency: PlanningDependency,
  bound: number,
  snapshot: PlanningSnapshot,
  index: Index,
  config: Required<TablePlanningConfig>
): void {
  const [initialStart] = requireDates(task);
  let [start, end] = requireDates(task);
  let endpoint = dependency.type[1] === "F" ? end : start;
  // A holiday can shorten the elapsed span while preserving working duration.
  // Recheck the actual group boundary instead of assuming a calendar translation.
  while (endpoint < bound) {
    moveTask(task, bound - endpoint, snapshot, index, config);
    [start, end] = requireDates(task);
    if (start - initialStart > config.maxCalendarSearchDays) {
      throw new PlanningError(
        "calendar-exhausted",
        "The group cannot satisfy its dependency within the planning horizon."
      );
    }
    endpoint = dependency.type[1] === "F" ? end : start;
  }
}
function satisfyDependency(
  dependency: PlanningDependency,
  next: PlanningSnapshot,
  index: Index,
  config: Required<TablePlanningConfig>,
  warnings: string[],
  addReason: (task: PlanningTask, reason: string) => void
): void {
  const from = requireTask(index, dependency.from);
  const to = requireTask(index, dependency.to);
  const [start, end] = requireDates(to);
  const bound = dependencyBound(dependency, from, to, next, config);
  const endpoint = dependency.type[1] === "F" ? end : start;
  if (endpoint >= bound) {
    return;
  }
  if (config.scheduling === "manual") {
    warnings.push(
      `${to.label}: ${dependency.type} dependency ${dependency.id} is not satisfied.`
    );
    return;
  }
  requireFlag(config.allowDateEdit);
  if (isRollup(config) && index.children.has(planningKey(to.ref))) {
    moveGroupToBound(to, dependency, bound, next, index, config);
  } else {
    const calendar = taskCalendar(to, next);
    const duration = workingDuration(
      start,
      end,
      calendar,
      config.maxCalendarSearchDays
    );
    const targetStart =
      dependency.type[1] === "F"
        ? addWorkingDays(
            bound,
            1 - duration,
            calendar,
            config.maxCalendarSearchDays
          )
        : bound;
    moveTask(to, Math.max(0, targetStart - start), next, index, config);
  }
  addReason(to, `dependency:${dependency.id}`);
  rollupDates(index, config);
}
export function calculatePlanning(
  snapshot: PlanningSnapshot,
  mutations: PlanningMutation[],
  input: TablePlanningConfig
): { snapshot: PlanningSnapshot; preview: Omit<PlanningPreview, "id"> } {
  const config = planningDefaults(input);
  if (!config.enabled) {
    throw new PlanningError("feature-disabled", "Planning is disabled.");
  }
  if (snapshot.scopeId !== config.scopeId) {
    throw new PlanningError(
      "scope-mismatch",
      "This planning snapshot belongs to a different scope."
    );
  }
  if (!snapshot.complete || snapshot.nextCursor) {
    throw new PlanningError(
      "incomplete-graph",
      "Load the complete dependency graph before recalculating."
    );
  }
  if (!snapshot.sources.some((source) => source.id === config.sourceId)) {
    throw new PlanningError(
      "missing-source",
      "The active source is unavailable."
    );
  }
  const baseline = resolvedPlanningSnapshot(snapshot, config);
  syncRecords(baseline);
  const next = structuredClone(baseline);
  let index = indexPlanning(next, config);
  const reasons = new Map<string, Set<string>>();
  const addReason = (task: PlanningTask, reason: string): void => {
    const key = planningKey(task.ref);
    const values = reasons.get(key) ?? new Set<string>();
    values.add(reason);
    reasons.set(key, values);
  };
  for (const mutation of mutations) {
    if (
      mutation.type === "dependency.put" ||
      mutation.type === "dependency.remove"
    ) {
      mutateDependency(mutation, next, index, config);
    } else {
      mutateTask(mutation, next, index, config);
      addReason(requireTask(index, mutation.ref), "requested");
    }
    index = indexPlanning(next, config);
    rollupDates(index, config);
  }
  const warnings: string[] = [];
  const dependencies = [...next.dependencies].sort(
    (a, b) =>
      (index.order.get(`${planningKey(a.to)}:in`) ?? 0) -
      (index.order.get(`${planningKey(b.to)}:in`) ?? 0)
  );
  for (const dependency of dependencies) {
    satisfyDependency(dependency, next, index, config, warnings, addReason);
  }
  syncRecords(next);
  const changes: PlanningChange[] = [];
  const beforeIndex = new Map(
    baseline.tasks.map((task) => [planningKey(task.ref), task])
  );
  for (const task of next.tasks) {
    const before = beforeIndex.get(planningKey(task.ref)) as PlanningTask;
    if (JSON.stringify(task) === JSON.stringify(before)) {
      continue;
    }
    requireEditable(task);
    changes.push({
      ref: task.ref,
      before,
      after: structuredClone(task),
      reasons: [
        ...(reasons.get(planningKey(task.ref)) ?? [
          isRollup(config) && index.children.has(planningKey(task.ref))
            ? "summary"
            : "group-or-calendar",
        ]),
      ],
    });
  }
  return {
    snapshot: next,
    preview: {
      revision: snapshot.revision,
      changes,
      dependencies: next.dependencies,
      warnings,
    },
  };
}

function treeGroups(
  snapshot: PlanningSnapshot,
  included: Set<string>,
  tasks: Map<string, PlanningTask>
): { children: Map<string, PlanningTask[]>; roots: PlanningTask[] } {
  const children = new Map<string, PlanningTask[]>();
  const roots: PlanningTask[] = [];
  for (const task of snapshot.tasks) {
    if (!included.has(planningKey(task.ref))) {
      continue;
    }
    if (
      task.parent &&
      included.has(planningKey(task.parent)) &&
      tasks.has(planningKey(task.parent))
    ) {
      const key = planningKey(task.parent);
      const list = children.get(key) ?? [];
      list.push(task);
      children.set(key, list);
    } else {
      roots.push(task);
    }
  }
  return { children, roots };
}
function includeAncestors(
  tasks: Map<string, PlanningTask>,
  included: Set<string>,
  visible?: Set<string>
): void {
  if (visible) {
    for (const key of visible) {
      let parent = tasks.get(key)?.parent;
      const visited = new Set<string>();
      while (parent) {
        const id = planningKey(parent);
        if (visited.has(id)) {
          break;
        }
        visited.add(id);
        included.add(id);
        parent = tasks.get(id)?.parent;
      }
    }
  }
}
/** Preserve parent context without turning filtered-out siblings into visible matches. */
export function planningTree(
  snapshot: PlanningSnapshot,
  visible?: Set<string>,
  collapsed = new Set<string>()
): { task: PlanningTask; depth: number; hasChildren: boolean }[] {
  const tasks = new Map(
    snapshot.tasks.map((task) => [planningKey(task.ref), task])
  );
  const included = visible ? new Set(visible) : new Set(tasks.keys());
  includeAncestors(tasks, included, visible);
  const { children, roots } = treeGroups(snapshot, included, tasks);
  const rows: { task: PlanningTask; depth: number; hasChildren: boolean }[] =
    [];
  const seen = new Set<string>();
  const stack = roots.reverse().map((task) => ({ task, depth: 0 }));
  while (stack.length) {
    const item = stack.pop();
    if (!item) {
      break;
    }
    const key = planningKey(item.task.ref);
    if (seen.has(key)) {
      continue;
    }
    seen.add(key);
    const group = children.get(key) ?? [];
    rows.push({ ...item, hasChildren: group.length > 0 });
    if (!collapsed.has(key)) {
      for (let i = group.length - 1; i >= 0; i -= 1) {
        const child = group[i];
        if (child) {
          stack.push({ task: child, depth: item.depth + 1 });
        }
      }
    }
  }
  return rows;
}

export function normalizeGanttView(
  value: unknown
): import("./types").TableGanttViewConfig {
  if (!value || typeof value !== "object") {
    return {};
  }
  const input = value as Record<string, unknown>;
  const result: import("./types").TableGanttViewConfig = {};
  if (input.zoom === "day" || input.zoom === "week" || input.zoom === "month") {
    result.zoom = input.zoom;
  }
  if (
    Number.isInteger(input.weekStartsOn) &&
    Number(input.weekStartsOn) >= 0 &&
    Number(input.weekStartsOn) <= 6
  ) {
    result.weekStartsOn = Number(input.weekStartsOn);
  }
  if (typeof input.showDependencies === "boolean") {
    result.showDependencies = input.showDependencies;
  }
  if (typeof input.anchorDate === "string") {
    try {
      dateDay(input.anchorDate);
      result.anchorDate = input.anchorDate;
    } catch {
      /* Invalid shared URL dates inherit the application default. */
    }
  }
  return result;
}

import {
  matchesContractFilter,
  normalizeFilterEnvelope,
} from "../table-contracts";
import {
  type PlanningSnapshot,
  type PlanningTask,
  planningKey,
  type TablePlanningConfig,
} from "./types";

export interface PlanningQuery {
  search?: string;
  filters?: { id: string; value: unknown }[];
  advancedFilters?: unknown;
  columns?: {
    id: string;
    accessorKey?: string;
    accessorFn?: (row: Record<string, unknown>) => unknown;
  }[];
}
/** Filters affect the projection only. The session always retains the complete scheduling graph. */
export function planningTaskMatches(
  task: PlanningTask,
  query: PlanningQuery
): boolean {
  const record = task.record ?? {
    name: task.label,
    start: task.start,
    end: task.end,
  };
  const valueFor = (id: string): unknown => {
    const column = query.columns?.find((item) => item.id === id);
    return column?.accessorFn
      ? column.accessorFn(record)
      : record[column?.accessorKey ?? id];
  };
  const search = query.search?.trim().toLocaleLowerCase();
  if (
    search &&
    ![task.label, ...Object.values(record)].some((value) =>
      String(value ?? "")
        .toLocaleLowerCase()
        .includes(search)
    )
  ) {
    return false;
  }
  if (
    query.filters?.some((filter) => {
      const actual = valueFor(filter.id);
      if (Array.isArray(filter.value)) {
        return !filter.value.some((item) =>
          (Array.isArray(actual) ? actual : [actual]).some(
            (value) => String(value) === String(item)
          )
        );
      }
      return !String(actual ?? "")
        .toLocaleLowerCase()
        .includes(String(filter.value ?? "").toLocaleLowerCase());
    })
  ) {
    return false;
  }
  const advanced = normalizeFilterEnvelope(query.advancedFilters);
  const filters = advanced.filters.filter(
    (filter) => filter.isActive !== false
  );
  if (!filters.length) {
    return true;
  }
  const matches = (filter: Record<string, unknown>): boolean =>
    matchesContractFilter(valueFor(String(filter.columnId)), filter);
  return advanced.joinOperator === "or"
    ? filters.some(matches)
    : filters.every(matches);
}

/** Reuse original records and restore missing ancestor context without adding filtered siblings. */
export function buildPlanningRows<T extends Record<string, unknown>>(
  rows: T[],
  snapshot: PlanningSnapshot | undefined,
  config: TablePlanningConfig | undefined,
  getId: (row: T) => string,
  mode: "tree" | "flat" = "tree"
): T[] {
  if (!config?.enabled || config.hierarchy === false || !snapshot) {
    return rows;
  }
  const tasks = new Map(
    snapshot.tasks
      .filter((task) => task.ref.source === config.sourceId)
      .map((task) => [task.ref.id, task])
  );
  const records = new Map<string, T>();
  const visit = (items: T[]): void => {
    for (const row of items) {
      records.set(getId(row), { ...row, subRows: [] });
      if (Array.isArray(row.subRows)) {
        visit(row.subRows as T[]);
      }
    }
  };
  visit(rows);
  for (const id of [...records.keys()]) {
    let parent = tasks.get(id)?.parent;
    const seen = new Set<string>();
    while (
      parent?.source === config.sourceId &&
      !seen.has(planningKey(parent))
    ) {
      seen.add(planningKey(parent));
      const task = tasks.get(parent.id);
      if (!task) {
        break;
      }
      if (!records.has(parent.id) && task.record) {
        records.set(parent.id, { ...task.record, subRows: [] } as unknown as T);
      }
      parent = task.parent;
    }
  }
  // Card views retain every task, even when the source records arrive as subRows.
  return mode === "flat"
    ? [...records.values()]
    : nestPlanningRows(records, tasks, config.sourceId);
}

function nestPlanningRows<T extends Record<string, unknown>>(
  records: Map<string, T>,
  tasks: Map<string, PlanningTask>,
  sourceId: string
): T[] {
  const roots: T[] = [];
  for (const [id, row] of records) {
    const task = tasks.get(id);
    const parent = task?.parent;
    const parentRow =
      parent?.source === sourceId && parent.id !== id
        ? records.get(parent.id)
        : undefined;
    if (parentRow) {
      (parentRow.subRows as T[]).push(row);
    } else {
      roots.push(row);
    }
  }
  return roots;
}

/** Sort siblings using the displayed column mappings; hierarchy order remains intact. */
export function comparePlanningTasks(
  a: PlanningTask,
  b: PlanningTask,
  query: PlanningQuery & { sorting: { id: string; desc: boolean }[] }
): number {
  for (const sort of query.sorting) {
    const column = query.columns?.find((item) => item.id === sort.id);
    const read = (task: PlanningTask): unknown =>
      column?.accessorFn
        ? column.accessorFn(task.record ?? {})
        : task.record?.[column?.accessorKey ?? sort.id];
    const left = read(a);
    const right = read(b);
    const difference =
      typeof left === "number" && typeof right === "number"
        ? left - right
        : String(left ?? "").localeCompare(String(right ?? ""), undefined, {
            numeric: true,
          });
    if (difference) {
      return sort.desc ? -difference : difference;
    }
  }
  return 0;
}

