/**
 * `TListParams` is inferred from the supplied `list`, so each edition's own list
 * contract fits without adapting it.
 */
export interface RowsPlanningAdapterOptions<
  TListParams = Record<string, unknown>,
> {
  config: TablePlanningConfig;
  /** Column mappings. `startColumn` and `endColumn` are required. */
  gantt?: TableGanttConfig;
  list: (params: TListParams) => MaybePromise<RowsPlanningListResult>;
  /** Omit to expose a read-only timeline. */
  update?: (
    id: string,
    data: Record<string, unknown>,
    context?: { row: Readonly<Record<string, unknown>> }
  ) => MaybePromise<RowsPlanningUpdateResult>;
  sourceLabel?: string;
  getId?: (row: Record<string, unknown>) => string;
  calendars?: PlanningCalendar[];
  defaultCalendarId?: string;
  /** Rows carry no relationships; supply them when the application stores them. */
  dependencies?: () => PlanningDependency[];
  pageSize?: number;
  /** Extra list parameters, for instance a scope the rows belong to. */
  listParams?: Record<string, unknown>;
  toDate?: (value: unknown) => string | null;
}

const DEFAULT_PAGE_SIZE = 200;
const MAX_PAGES = 1000;
const DEFAULT_CALENDAR_ID = "default";
const WORKING_WEEK = [1, 2, 3, 4, 5];
const REVISION_MODULUS = 2_147_483_647;
const REVISION_FACTOR = 31;
const ISO_DATE_LENGTH = 10;

/** A stable digest keeps an open preview valid while the rows are unchanged. */
function digest(value: string): string {
  let hash = 0;
  for (const character of value) {
    hash =
      (hash * REVISION_FACTOR + (character.codePointAt(0) ?? 0)) %
      REVISION_MODULUS;
  }
  return `rows-${hash}`;
}

/** Accepts civil dates, ISO timestamps and Date values, all read as UTC. */
function defaultToDate(value: unknown): string | null {
  if (value == null || value === "") {
    return null;
  }
  if (value instanceof Date) {
    return Number.isNaN(value.getTime())
      ? null
      : value.toISOString().slice(0, ISO_DATE_LENGTH);
  }
  if (typeof value === "string") {
    return value.slice(0, ISO_DATE_LENGTH);
  }
  throw new PlanningError(
    "invalid-date",
    "Map a date column or provide an explicit toDate adapter."
  );
}

function planningFields(gantt: TableGanttConfig | undefined): PlanningFields {
  if (!(gantt?.startColumn && gantt.endColumn)) {
    throw new PlanningError(
      "missing-fields",
      "Map gantt.startColumn and gantt.endColumn to build a planning from rows."
    );
  }
  return {
    title: gantt.titleColumn,
    start: gantt.startColumn,
    end: gantt.endColumn,
    parent: gantt.parentColumn,
    calendar: gantt.calendarColumn,
  };
}

/** True when the table configuration alone is enough to derive a planning graph. */
export function canDeriveRowsPlanning(gantt?: TableGanttConfig): boolean {
  return Boolean(gantt?.startColumn && gantt.endColumn);
}

function snapshotRevision(
  tasks: PlanningSnapshot["tasks"],
  dependencies: PlanningDependency[]
): string {
  return digest(
    JSON.stringify([
      tasks.map((task) => [
        task.ref.id,
        task.start,
        task.end,
        task.parent?.id ?? null,
        task.label,
        task.calendarId ?? null,
      ]),
      dependencies.map((edge) => [
        edge.id,
        edge.from.id,
        edge.to.id,
        edge.type,
        edge.lag ?? 0,
        edge.lagUnit ?? null,
      ]),
    ])
  );
}

function changedRecordPatch(
  change: PlanningChange,
  fields: PlanningFields,
  sourceId: string
): Record<string, unknown> | undefined {
  const patch: Record<string, unknown> = {};
  if (change.before.start !== change.after.start) {
    patch[fields.start] = change.after.start;
  }
  if (change.before.end !== change.after.end) {
    patch[fields.end] = change.after.end;
  }
  const beforeParent = change.before.parent?.id ?? null;
  const afterParent = change.after.parent?.id ?? null;
  if (fields.parent && beforeParent !== afterParent) {
    // Scalar columns can only represent parents from the same source.
    patch[fields.parent] =
      change.after.parent?.source === sourceId ? afterParent : null;
  }
  return Object.keys(patch).length ? patch : undefined;
}

/**
 * Builds a planning adapter from the table's own `list`/`update` actions, so a Gantt
 * needs no bespoke planning backend: mapping `gantt.startColumn` and `gantt.endColumn`
 * is enough, exactly as Kanban and Gallery need only their own column mappings.
 *
 * Unlike a database-backed adapter this cannot commit atomically: each affected row is
 * patched through `update`. A partial failure is reported and the graph is reloaded so
 * the timeline always shows what was actually stored.
 */
export function createRowsPlanningAdapter<TListParams>(
  input: RowsPlanningAdapterOptions<TListParams>
) {
  const config = planningDefaults(input.config);
  const fields = planningFields(input.gantt);
  const pageSize = input.pageSize ?? DEFAULT_PAGE_SIZE;
  const calendars = input.calendars ?? [
    { id: DEFAULT_CALENDAR_ID, workingDays: WORKING_WEEK },
  ];
  const defaultCalendarId =
    input.defaultCalendarId ?? calendars[0]?.id ?? DEFAULT_CALENDAR_ID;
  const source: PlanningSource = {
    id: config.sourceId,
    label: input.sourceLabel ?? config.sourceId,
    calendarId: defaultCalendarId,
    fields,
  };
  const getId =
    input.getId ?? ((row: Record<string, unknown>) => String(row.id));
  const emptySnapshot: PlanningSnapshot = {
    scopeId: config.scopeId,
    revision: digest("empty"),
    tasks: [],
    dependencies: [],
    sources: [source],
    calendars,
    defaultCalendarId,
    complete: true,
  };
  let current = emptySnapshot;

  const collectRows = async (
    signal?: AbortSignal
  ): Promise<Record<string, unknown>[]> => {
    const rows: Record<string, unknown>[] = [];
    const readPage = async (page: number): Promise<void> => {
      signal?.throwIfAborted();
      // compatibleListParams fills every field of the shared list contract.
      const result = await input.list(
        compatibleListParams({
          ...input.listParams,
          page,
          pageSize,
        }) as TListParams
      );
      signal?.throwIfAborted();
      const batch = (result.data ?? []) as Record<string, unknown>[];
      for (const row of batch) {
        rows.push(row);
      }
      const pageCount = Number(result.meta?.pageCount ?? 0);
      const isLastPage =
        batch.length === 0 ||
        (pageCount > 0 ? page >= pageCount : batch.length < pageSize);
      if (isLastPage) {
        return;
      }
      if (page >= MAX_PAGES) {
        throw new PlanningError(
          "incomplete-graph",
          "The planning rows exceeded the page limit."
        );
      }
      await readPage(page + 1);
    };
    await readPage(1);
    return rows;
  };

  const buildSnapshot = (rows: Record<string, unknown>[]): PlanningSnapshot => {
    const normalized = planningTasksFromRows({
      source,
      rows,
      getId,
      gantt: input.gantt,
      toDate: input.toDate ?? defaultToDate,
    });
    const dependencies = input.dependencies?.() ?? [];
    return {
      scopeId: config.scopeId,
      revision: snapshotRevision(normalized.tasks, dependencies),
      tasks: normalized.tasks,
      dependencies,
      sources: [normalized.source],
      calendars,
      defaultCalendarId,
      complete: true,
    };
  };

  const reload = async (signal?: AbortSignal): Promise<PlanningSnapshot> => {
    current = buildSnapshot(await collectRows(signal));
    return structuredClone(current);
  };

  const persist = async (changes: PlanningChange[]): Promise<void> => {
    const patches = changes.flatMap((change) => {
      if (change.ref.source !== config.sourceId) {
        return [];
      }
      const patch = changedRecordPatch(change, fields, config.sourceId);
      return patch ? [{ change, patch }] : [];
    });
    if (patches.length === 0) {
      return;
    }
    const update = input.update;
    if (!update) {
      throw new PlanningError(
        "read-only",
        "This planning has no update action, so dates cannot be saved."
      );
    }
    const save = async (
      change: PlanningChange,
      patch: Record<string, unknown>
    ): Promise<RowsPlanningUpdateResult> => {
      try {
        return await update(change.ref.id, patch, {
          row: change.before.record ?? {},
        });
      } catch (cause) {
        return {
          success: false,
          error: cause instanceof Error ? cause.message : String(cause),
        };
      }
    };
    const results = await Promise.all(
      patches.map(({ change, patch }) => save(change, patch))
    );
    const rejected = results.find((result) => !result.success);
    if (rejected) {
      throw new PlanningError(
        "apply-failed",
        rejected.error ?? "The planning changes could not be saved."
      );
    }
  };

  const actions = createPlanningTransactions({
    config: input.config,
    read: () => current,
    load: async (context) => {
      assertPlanningContext(current, config.scopeId, context);
      return await reload(context.signal);
    },
    commit: async ({ preview }) => {
      try {
        await persist(preview.changes);
      } catch (cause) {
        // Some rows may already be stored; resynchronize before surfacing the failure.
        await reload().catch(() => undefined);
        throw cause;
      }
      return await reload();
    },
  });

  return {
    actions,
    getSnapshot: (): PlanningSnapshot => structuredClone(current),
  };
}

import { dateDay } from "./calendar";
import {
  PlanningError,
  type PlanningFields,
  type PlanningRef,
  type PlanningSource,
  type PlanningTask,
  type TableGanttConfig,
} from "./types";

export interface PlanningRowAdapter<T extends Record<string, unknown>> {
  source: PlanningSource;
  rows: T[];
  getId: (row: T) => string;
  gantt?: TableGanttConfig;
  getChildren?: (row: T) => T[] | undefined;
  getParent?: (row: T) => PlanningRef | null | undefined;
  /** Convert timestamps explicitly using the application's time zone. */
  toDate?: (value: unknown) => string | null;
}
/** Normalize records or existing subRows without choosing database column names. */
export function planningTasksFromRows<T extends Record<string, unknown>>(
  input: PlanningRowAdapter<T>
): { source: PlanningSource; tasks: PlanningTask[] } {
  const start = input.gantt?.startColumn ?? input.source.fields?.start;
  const end = input.gantt?.endColumn ?? input.source.fields?.end;
  if (!(start && end)) {
    throw new PlanningError(
      "missing-fields",
      "Map both start and end columns for this planning source."
    );
  }
  const fields = {
    ...input.source.fields,
    start,
    end,
    title: input.gantt?.titleColumn ?? input.source.fields?.title,
  };
  const source = { ...input.source, fields };
  const tasks: PlanningTask[] = [];
  const getChildren =
    input.getChildren ??
    ((row: T) => (Array.isArray(row.subRows) ? (row.subRows as T[]) : []));
  const queue = input.rows.map((row) => ({
    row,
    parent: null as PlanningRef | null,
  }));
  const seen = new Set<string>();
  // Iterating the growing queue handles deeply nested data without recursion.
  for (const { row, parent } of queue) {
    const task = normalizeRow(row, parent, fields, input);
    if (!task.ref.id || seen.has(task.ref.id)) {
      throw new PlanningError(
        "duplicate-task",
        "The source contains a repeated record or cyclic subRows."
      );
    }
    seen.add(task.ref.id);
    tasks.push(task);
    for (const child of getChildren(row) ?? []) {
      queue.push({ row: child, parent: task.ref });
    }
  }
  return { source, tasks };
}
function normalizeRow<T extends Record<string, unknown>>(
  row: T,
  inheritedParent: PlanningRef | null,
  fields: PlanningFields,
  input: PlanningRowAdapter<T>
): PlanningTask {
  const ref = { source: input.source.id, id: input.getId(row) };
  const toDate = input.toDate ?? civilDate;
  const fieldParent = fields.parent ? row[fields.parent] : null;
  let parent =
    fieldParent == null || fieldParent === ""
      ? inheritedParent
      : { source: ref.source, id: String(fieldParent) };
  if (input.getParent) {
    parent = input.getParent(row) ?? null;
  }
  const calendar = fields.calendar ? row[fields.calendar] : undefined;
  // The hierarchy is normalized separately; avoid repeating nested records in every ancestor.
  const record: Record<string, unknown> = structuredClone(row);
  if (!input.getChildren) {
    record.subRows = undefined;
  }
  return {
    ref,
    label: String(fields.title ? (row[fields.title] ?? ref.id) : ref.id),
    start: toDate(row[fields.start]),
    end: toDate(row[fields.end]),
    parent,
    calendarId: calendar == null ? undefined : String(calendar),
    record,
  };
}
function civilDate(value: unknown): string | null {
  if (value == null || value === "") {
    return null;
  }
  if (typeof value !== "string") {
    throw new PlanningError(
      "invalid-date",
      "Use civil date strings or provide an explicit date adapter."
    );
  }
  dateDay(value);
  return value;
}

import { loadPlanningSnapshot } from "./adapter";
import {
  calculatePlanning,
  planningDefaults,
  resolvedPlanningSnapshot,
} from "./engine";
import {
  PlanningError,
  type PlanningMutation,
  type PlanningPreview,
  type PlanningRef,
  type PlanningResult,
  type PlanningSnapshot,
  type PlanningTask,
  planningKey,
  type TablePlanningActions,
  type TablePlanningConfig,
} from "./types";

export interface PlanningSessionState {
  snapshot?: PlanningSnapshot;
  preview?: PlanningPreview;
  selected?: PlanningRef;
  busy: boolean;
  error?: string;
}
export interface PlanningSessionOptions {
  config: TablePlanningConfig;
  actions?: TablePlanningActions;
  allowEdit?: boolean;
  canEditRow?: (row: Record<string, unknown>) => boolean;
  onChanged?: () => void | Promise<void>;
}
const CHANGE_EVENT = "yayaw-table-planning-changed";

function mutationRefs(
  mutation: PlanningMutation,
  snapshot: PlanningSnapshot
): PlanningRef[] {
  if (mutation.type === "dependency.put") {
    return [mutation.dependency.from, mutation.dependency.to];
  }
  if (mutation.type === "dependency.remove") {
    return snapshot.dependencies
      .filter((edge) => edge.id === mutation.id)
      .flatMap((edge) => [edge.from, edge.to]);
  }
  if (mutation.type === "parent" && mutation.parent) {
    return [mutation.ref, mutation.parent];
  }
  if (mutation.type === "record") {
    const field = snapshot.sources.find(
      (source) => source.id === mutation.ref.source
    )?.fields?.parent;
    const parentId = field ? mutation.patch[field] : null;
    if (parentId != null && parentId !== "") {
      return [
        mutation.ref,
        { source: mutation.ref.source, id: String(parentId) },
      ];
    }
  }
  return [mutation.ref];
}
/** One session per table instance. Only invalidations, never records or drafts, cross instances. */
export function createPlanningSession(options: PlanningSessionOptions) {
  let state: PlanningSessionState = { busy: false };
  const config = planningDefaults(options.config);
  const listeners = new Set<() => void>();
  let abort: AbortController | undefined;
  let generation = 0;
  let disposed = false;
  let settle: ((result: PlanningResult<PlanningSnapshot>) => void) | undefined;
  let applyKey: string | undefined;
  const publish = (patch: Partial<PlanningSessionState>): void => {
    if (disposed) {
      return;
    }
    state = { ...state, ...patch };
    for (const listener of listeners) {
      listener();
    }
  };
  const resultError = (cause: unknown): PlanningResult<PlanningSnapshot> => ({
    success: false,
    code: cause instanceof PlanningError ? cause.code : "planning-error",
    error: cause instanceof Error ? cause.message : String(cause),
  });
  const canEdit = (task: PlanningTask): boolean =>
    options.allowEdit !== false &&
    task.editable !== false &&
    (task.ref.source !== config.sourceId ||
      options.canEditRow?.(task.record ?? {}) !== false);
  const context = { scopeId: config.scopeId, sourceId: config.sourceId };
  const load = async (): Promise<void> => {
    if (!(config.enabled && options.actions)) {
      return;
    }
    abort?.abort();
    abort = new AbortController();
    const ticket = ++generation;
    publish({ busy: true, error: undefined });
    try {
      const snapshot = await loadPlanningSnapshot(
        options.actions,
        context,
        abort.signal,
        (page) => {
          if (ticket === generation) {
            publish({ snapshot: page });
          }
        }
      );
      if (ticket !== generation || disposed) {
        return;
      }
      // A partial/invalid graph remains inspectable, but exposes an actionable error.
      if (!snapshot.complete) {
        throw new PlanningError(
          "incomplete-graph",
          "The planning graph is incomplete. Resolve unavailable records before editing."
        );
      }
      publish({
        snapshot: resolvedPlanningSnapshot(snapshot, config),
        busy: false,
      });
    } catch (cause) {
      if (ticket !== generation || disposed) {
        return;
      }
      publish({
        busy: false,
        error: cause instanceof Error ? cause.message : String(cause),
      });
    }
  };
  const finish = (result: PlanningResult<PlanningSnapshot>): void => {
    const resolve = settle;
    settle = undefined;
    applyKey = undefined;
    publish({ preview: undefined, busy: false });
    resolve?.(result);
  };
  const cancel = (): void => {
    if (state.busy && state.preview) {
      return;
    }
    generation += 1;
    finish({
      success: false,
      code: "cancelled",
      error: "Planning changes were cancelled.",
    });
  };
  const notifyChanged = (): void => {
    if (typeof window !== "undefined") {
      window.dispatchEvent(
        new CustomEvent(CHANGE_EVENT, { detail: { scopeId: config.scopeId } })
      );
    } else {
      options.onChanged?.();
    }
  };
  const apply = async (): Promise<void> => {
    if (!state.preview || state.busy || !options.actions) {
      return;
    }
    const preview = state.preview;
    publish({ busy: true, error: undefined });
    applyKey ??= crypto.randomUUID();
    try {
      const result = await options.actions.apply({
        ...context,
        previewId: preview.id,
        revision: preview.revision,
        idempotencyKey: applyKey,
      });
      if (disposed) {
        return;
      }
      if (!(result.success && result.data)) {
        publish({
          busy: false,
          error: result.error ?? "Could not save the planning.",
        });
        if (result.code === "stale-preview") {
          finish(result);
          await load();
          publish({ error: result.error });
        }
        return;
      }
      publish({ snapshot: result.data, error: undefined });
      finish(result);
      notifyChanged();
    } catch (cause) {
      // Preserve both preview and key after an uncertain response; retry cannot duplicate a commit.
      publish({
        busy: false,
        error: cause instanceof Error ? cause.message : String(cause),
      });
    }
  };
  const checkEditable = (task: PlanningTask): void => {
    if (!canEdit(task)) {
      throw new PlanningError(
        "permission-denied",
        `Changes to ${task.label} are not permitted.`
      );
    }
  };
  const validateLocal = (
    snapshot: PlanningSnapshot,
    mutations: PlanningMutation[]
  ): void => {
    const local = calculatePlanning(snapshot, mutations, config);
    for (const change of local.preview.changes) {
      checkEditable(change.before);
      checkEditable(change.after);
    }
    for (const mutation of mutations) {
      for (const ref of mutationRefs(mutation, snapshot)) {
        const task = snapshot.tasks.find(
          (item) => planningKey(item.ref) === planningKey(ref)
        );
        if (task) {
          checkEditable(task);
        }
      }
    }
  };
  const validatePreview = (
    result: PlanningResult<PlanningPreview>
  ): PlanningPreview => {
    if (!(result.success && result.data)) {
      throw new PlanningError(
        result.code ?? "planning-error",
        result.error ?? "Could not prepare this planning change."
      );
    }
    for (const change of result.data.changes) {
      checkEditable(change.before);
      checkEditable(change.after);
    }
    return result.data;
  };
  const request = async (
    mutations: PlanningMutation[]
  ): Promise<PlanningResult<PlanningSnapshot>> => {
    if (settle || state.busy) {
      return {
        success: false,
        error: "Finish the current planning operation first.",
        code: "busy",
      };
    }
    if (!(options.actions && config.enabled) || options.allowEdit === false) {
      return {
        success: false,
        error: "Planning edits are unavailable.",
        code: "permission-denied",
      };
    }
    if (!state.snapshot) {
      await load();
    }
    const snapshot = state.snapshot;
    if (!snapshot?.complete) {
      return {
        success: false,
        error: state.error ?? "Load the complete planning first.",
        code: "incomplete-graph",
      };
    }
    const ticket = ++generation;
    publish({ busy: true, error: undefined });
    try {
      validateLocal(snapshot, mutations);
      const result = await options.actions.preview({
        ...context,
        revision: snapshot.revision,
        mutations,
      });
      if (disposed || generation !== ticket) {
        return { success: false, code: "cancelled" };
      }
      const preview = validatePreview(result);
      const completion = new Promise<PlanningResult<PlanningSnapshot>>(
        (resolve) => {
          settle = resolve;
        }
      );
      publish({ preview, busy: false });
      if (config.scheduling === "automatic") {
        await apply();
      }
      return await completion;
    } catch (cause) {
      const result = resultError(cause);
      publish({ busy: false, error: result.error });
      return result;
    }
  };
  const externalChange = (event: Event): void => {
    const detail = (event as CustomEvent<{ scopeId?: string }>).detail;
    if (detail?.scopeId !== config.scopeId) {
      return;
    }
    Promise.resolve(options.onChanged?.()).catch((cause: unknown) =>
      publish({ error: String(cause) })
    );
    // Keep an open preview for review; its revision is checked when the user applies it.
    if (!(settle || state.busy)) {
      load();
    }
  };

  const session = {
    config,
    canEdit,
    load,
    request,
    apply,
    cancel,
    connect(): void {
      disposed = false;
      if (typeof window !== "undefined") {
        window.addEventListener(CHANGE_EVENT, externalChange);
      }
      load();
    },
    getState: (): PlanningSessionState => state,
    subscribe(listener: () => void): () => void {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
    open(ref?: PlanningRef): void {
      publish({ selected: ref });
    },
    dispose(): void {
      abort?.abort();
      generation += 1;
      finish({ success: false, code: "cancelled" });
      disposed = true;
      listeners.clear();
      if (typeof window !== "undefined") {
        window.removeEventListener(CHANGE_EVENT, externalChange);
      }
    },
  };
  return session;
}
export type PlanningSession = ReturnType<typeof createPlanningSession>;

interface RecordActions {
  update?: (
    id: string,
    patch: Record<string, unknown>
  ) =>
    | Promise<{ success: boolean; data?: unknown; error?: string }>
    | { success: boolean; data?: unknown; error?: string };
  bulkUpdate?: (
    ids: string[],
    patch: Record<string, unknown>
  ) =>
    | Promise<{ success: boolean; data?: unknown; error?: string }>
    | { success: boolean; data?: unknown; error?: string };
}
/** Catalogue forms, bulk editors and inline cells all receive this same guarded action object. */
export function withPlanningActions<T extends RecordActions>(
  actions: T,
  session: PlanningSession
): T {
  if (!session.config.enabled) {
    return actions;
  }
  const updateMany = async (ids: string[], patch: Record<string, unknown>) => {
    const result = await session.request(
      ids.map((id) => ({
        type: "record",
        ref: { source: session.config.sourceId, id },
        patch,
      }))
    );
    const records = result.data?.tasks
      .filter(
        (task) =>
          task.ref.source === session.config.sourceId &&
          ids.includes(task.ref.id)
      )
      .map((task) => task.record);
    return { ...result, data: records };
  };
  return {
    ...actions,
    update: async (id: string, patch: Record<string, unknown>) => {
      const result = await updateMany([id], patch);
      return { ...result, data: result.data?.[0] };
    },
    bulkUpdate: updateMany,
  };
}

import { type PlanningSurfaceLabels, planningLabels } from "./labels";

const WEEK_ORIGIN = Date.UTC(2026, 0, 4);
const DAYS_IN_WEEK = 7;
const DAY_MS = 86_400_000;

/** Shared presentation labels keep React and Vue planning settings equivalent. */
export function ganttSettingsLabels(
  locale = "en",
  overrides?: Partial<PlanningSurfaceLabels>
) {
  const labels = planningLabels(locale, overrides);
  return {
    title: labels.settings,
    zoom: labels.zoom,
    weekStart: labels.weekStart,
    showDependencies: labels.showLinks,
    zoomOptions: [
      { value: "day", label: labels.day },
      { value: "week", label: labels.week },
      { value: "month", label: labels.month },
    ],
    weekOptions: Array.from({ length: DAYS_IN_WEEK }, (_, day) => ({
      value: String(day),
      label: new Intl.DateTimeFormat(locale, {
        weekday: "long",
        timeZone: "UTC",
      }).format(new Date(WEEK_ORIGIN + day * DAY_MS)),
    })),
  };
}

/* The planning dialog inherits the host theme; each edition styles its own timeline. */
.yayaw-planning,
.yp-dialog {
  --yp-bg: var(--background, var(--yayaw-background, #fff));
  --yp-fg: var(--foreground, var(--yayaw-foreground, #37352f));
  --yp-border: var(--border, var(--yayaw-border, #e9e9e7));
  --yp-grid: color-mix(in srgb, var(--yp-border) 48%, transparent);
  --yp-muted: color-mix(in srgb, var(--yp-fg) 4%, var(--yp-bg));
  --yp-muted-fg: color-mix(in srgb, var(--yp-fg) 65%, var(--yp-bg));
  --yp-accent: #2273bd;
  color: var(--yp-fg);
  font: inherit;
  font-size: 13px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}
:where(.yayaw-planning, .yp-dialog) button,
:where(.yayaw-planning, .yp-dialog) input,
:where(.yayaw-planning, .yp-dialog) select {
  box-sizing: border-box;
  font: inherit;
  color: inherit;
  border: 1px solid var(--yp-border);
  border-radius: 5px;
  background: var(--yp-bg);
  min-height: 30px;
  padding: 4px 8px;
}
:where(.yayaw-planning, .yp-dialog) button {
  cursor: pointer;
  transition:
    background-color 120ms,
    box-shadow 120ms;
}
:where(.yayaw-planning, .yp-dialog) button:hover {
  background: var(--yp-muted);
}
:where(.yayaw-planning, .yp-dialog) button:disabled,
:where(.yayaw-planning, .yp-dialog) input:disabled,
:where(.yayaw-planning, .yp-dialog) select:disabled {
  cursor: default;
  opacity: 0.5;
}
:where(.yayaw-planning, .yp-dialog) :focus-visible {
  outline: 2px solid var(--yp-accent);
  outline-offset: 2px;
}
.yp-icon {
  display: block;
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  pointer-events: none;
}
.dark :where(.yayaw-planning, .yp-dialog) {
  color-scheme: dark;
}
:where(.yayaw-planning, .yp-dialog) .yp-icon-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 30px;
  padding: 0;
  border-color: transparent;
  background: transparent;
  color: var(--yp-muted-fg);
}
.yp-error {
  color: var(--destructive, #b91c1c);
  padding: 8px 0;
}
.yp-warning {
  padding: 8px 12px;
  background: var(--yp-muted);
  border-radius: 5px;
}
.yp-dialog {
  margin: auto;
  background: var(--yp-bg);
  border: 1px solid var(--yp-border);
  border-radius: 10px;
  width: min(860px, calc(100vw - 32px));
  max-height: calc(100dvh - 48px);
  overflow: auto;
  padding: 24px;
  box-shadow:
    0 12px 48px #0002,
    0 2px 8px #0001;
}
.yp-dialog::backdrop {
  background: #0005;
}
.yp-dialog-heading,
.yp-dialog-actions,
.yp-dependency {
  display: flex;
  align-items: center;
  gap: 10px;
}
.yp-dialog-heading {
  justify-content: space-between;
  align-items: flex-start;
  gap: 24px;
  margin-bottom: 24px;
}
.yp-dialog h2 {
  margin: 0;
  padding-top: 2px;
  font-size: 22px;
  line-height: 1.25;
  font-weight: 600;
  letter-spacing: -0.025em;
}
.yp-dialog h3 {
  margin: 28px 0 8px;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--yp-border);
  font-size: 14px;
  font-weight: 600;
}
.yp-dialog h4 {
  margin: 20px 0 10px;
  font-size: 12px;
  font-weight: 500;
  color: var(--yp-muted-fg);
}
.yp-dialog-actions {
  justify-content: flex-end;
  padding-top: 16px;
  margin-top: 20px;
  border-top: 1px solid var(--yp-border);
}
.yp-dialog-actions button:last-child,
.yp-editor > button {
  background: var(--yp-accent);
  border-color: var(--yp-accent);
  color: #fff;
  font-weight: 500;
  box-shadow: 0 1px 2px #0001;
}
.yp-dialog-actions button:last-child:hover,
.yp-editor > button:hover {
  background: color-mix(in srgb, var(--yp-accent) 90%, #000);
}
.yp-editor {
  display: flex;
  flex-wrap: wrap;
  align-items: end;
  gap: 12px;
  margin-bottom: 16px;
}
.yp-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.yp-field select {
  max-width: 240px;
}
.yp-field input[type="number"] {
  width: 80px;
}
.yp-field span {
  font-size: 12px;
  color: var(--yp-muted-fg);
}
.yp-dependency {
  padding: 10px 0;
  border-bottom: 1px solid var(--yp-grid);
}
.yp-dependency span {
  flex: 1;
  min-width: 0;
  overflow-wrap: anywhere;
}
.yp-dependency button {
  border-color: transparent;
  color: var(--yp-muted-fg);
  padding-inline: 6px;
}
.yp-preview-table {
  overflow: auto;
}
.yp-preview-table table {
  width: 100%;
  border-collapse: collapse;
}
.yp-preview-table th,
.yp-preview-table td {
  text-align: left;
  padding: 12px 10px;
  border-bottom: 1px solid var(--yp-border);
  font-size: 12px;
  vertical-align: top;
  line-height: 1.65;
}
.yp-preview-table th {
  color: var(--yp-muted-fg);
  font-weight: 400;
  background: var(--yp-muted);
}
.yp-preview-table td:first-child {
  min-width: 160px;
  font-weight: 500;
}
@media (max-width: 767px) {
  .yp-dialog {
    position: fixed;
    inset: auto 0 0;
    margin: 0;
    width: 100%;
    max-width: none;
    max-height: 90dvh;
    box-sizing: border-box;
    border-radius: 16px 16px 0 0;
    padding: 18px 18px calc(18px + env(safe-area-inset-bottom));
    overscroll-behavior: contain;
  }
  .yp-dialog h2 {
    font-size: 18px;
  }
  .yp-dialog :is(button, input:not([type="checkbox"]), select) {
    min-height: 44px;
  }
  .yp-dialog .yp-icon-button {
    min-width: 44px;
  }

  .yp-editor .yp-field {
    flex: 1;
    min-width: 130px;
  }
  .yp-editor input,
  .yp-editor select {
    width: 100%;
    max-width: 100%;
  }
  .yp-dialog-actions {
    flex-wrap: wrap;
  }
}
@media (prefers-reduced-motion: reduce) {
  .yayaw-planning button,
  .yp-dialog button {
    transition: none;
  }
}

import { type PlanningSurfaceLabels, planningLabels } from "./labels";
import type { PlanningSession } from "./session";
import {
  type DependencyType,
  type PlanningDependency,
  type PlanningTask,
  planningKey,
  samePlanningRef,
} from "./types";

/**
 * The planning dialog: task dates, relationships and the preview/apply review.
 * Both editions share it because it is a modal form, independent of any table state.
 * Each edition renders its own timeline from the planning/timeline model.
 */
export interface PlanningSurfaceOptions {
  session: PlanningSession;
  locale?: string;
  onOpenRecord?: (task: PlanningTask) => void;
  /** Host translations for the planning vocabulary; unset keys keep their built-in value. */
  labels?: Partial<PlanningSurfaceLabels>;
}
const ICON_PATHS = {
  previous: "m14 6-6 6 6 6",
  next: "m10 6 6 6-6 6",
  down: "m6 9 6 6 6-6",
  page: "M14 3H6a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V9zm0 0v6h6M8 13h8M8 17h5",
  group: "m12 3 9 5-9 5-9-5zm-9 9 9 5 9-5M3 16l9 5 9-5",
  reload: "M20 7v5h-5M4 17v-5h5M6 6a8 8 0 0 1 13 3M5 15a8 8 0 0 0 13 3",
  close: "m6 6 12 12M6 18 18 6",
} as const;

/** The DOM renderer is shared by the two framework adapters, including keyboard and pointer behavior. */
export function mountPlanningSurface(
  container: HTMLElement,
  initial: PlanningSurfaceOptions
) {
  let options = initial;
  let dialog: HTMLDialogElement | undefined;
  let editingLink: string | undefined;
  let restoreFocus: HTMLElement | undefined;
  const drafts = new Map<string, string>();
  let draftContext = "";
  const doc = container.ownerDocument;
  container.classList.add("yayaw-planning");
  const labels = (): PlanningSurfaceLabels =>
    planningLabels(options.locale, options.labels);
  const node = <K extends keyof HTMLElementTagNameMap>(
    tag: K,
    text?: string,
    className?: string
  ): HTMLElementTagNameMap[K] => {
    const element = doc.createElement(tag);
    if (text != null) {
      element.textContent = text;
    }
    if (className) {
      element.className = className;
    }
    return element;
  };
  const icon = (name: keyof typeof ICON_PATHS): SVGSVGElement => {
    const svg = doc.createElementNS("http://www.w3.org/2000/svg", "svg");
    svg.classList.add("yp-icon");
    svg.setAttribute("viewBox", "0 0 24 24");
    svg.setAttribute("fill", "none");
    svg.setAttribute("stroke", "currentColor");
    svg.setAttribute("stroke-width", "1.5");
    svg.setAttribute("stroke-linecap", "round");
    svg.setAttribute("stroke-linejoin", "round");
    svg.setAttribute("aria-hidden", "true");
    svg.setAttribute("focusable", "false");
    const path = doc.createElementNS(svg.namespaceURI, "path");
    path.setAttribute("d", ICON_PATHS[name]);
    svg.append(path);
    return svg;
  };
  const button = (
    label: string,
    action: () => void,
    disabled = false,
    key?: string
  ): HTMLButtonElement => {
    const element = node("button", label);
    element.type = "button";
    element.disabled = disabled;
    element.addEventListener("click", action);
    if (key) {
      element.dataset.focus = key;
    }
    return element;
  };
  const field = (label: string, control: HTMLElement): HTMLLabelElement => {
    const element = node("label", undefined, "yp-field");
    element.append(node("span", label), control);
    return element;
  };
  const input = (
    type: string,
    value: string,
    key: string
  ): HTMLInputElement => {
    const element = node("input");
    element.type = type;
    element.value = drafts.get(key) ?? value;
    element.dataset.focus = key;
    return element;
  };
  const select = (
    entries: { value: string; label: string }[],
    value: string,
    key: string
  ): HTMLSelectElement => {
    const element = node("select");
    element.dataset.focus = key;
    for (const entry of entries) {
      const option = node("option", entry.label);
      option.value = entry.value;
      element.append(option);
    }
    element.value = drafts.get(key) ?? value;
    return element;
  };
  const errorNode = (): HTMLElement | undefined => {
    const error = options.session.getState().error;
    if (!error) {
      return;
    }
    const element = node("p", error, "yp-error");
    element.setAttribute("role", "alert");
    return element;
  };

  function dependencyEditor(
    task: PlanningTask,
    existing?: PlanningDependency
  ): HTMLElement {
    const t = labels();
    const state = options.session.getState();
    const snapshot = state.snapshot;
    const form = node("form", undefined, "yp-editor");
    if (!snapshot) {
      return form;
    }
    const sources = snapshot.sources.filter(
      (source) =>
        options.session.config.allowCrossTableDependencies ||
        source.id === task.ref.source
    );
    const source = select(
      sources.map((item) => ({ value: item.id, label: item.label })),
      existing?.from.source ?? task.ref.source,
      "dependency-source"
    );
    const taskOptions = (): { value: string; label: string }[] =>
      snapshot.tasks
        .filter(
          (item) =>
            item.ref.source === source.value &&
            !samePlanningRef(item.ref, task.ref)
        )
        .map((item) => ({ value: planningKey(item.ref), label: item.label }));
    const entries = taskOptions();
    const predecessor = select(
      entries,
      existing ? planningKey(existing.from) : (entries[0]?.value ?? ""),
      "dependency-task"
    );
    source.onchange = () => {
      const next = taskOptions();
      predecessor.replaceChildren(
        ...next.map((item) => {
          const option = node("option", item.label);
          option.value = item.value;
          return option;
        })
      );
      submit.disabled = !(
        next.length && options.session.config.dependencyTypes.length
      );
    };
    const type = select(
      options.session.config.dependencyTypes.map((value) => ({
        value,
        label: value,
      })),
      existing?.type ?? options.session.config.dependencyTypes[0] ?? "FS",
      "dependency-type"
    );
    const lag = input("number", String(existing?.lag ?? 0), "dependency-lag");
    lag.step = "1";
    lag.required = true;
    const unit = select(
      [
        { value: "workingDays", label: t.working },
        { value: "calendarDays", label: t.calendar },
      ],
      existing?.lagUnit ?? "workingDays",
      "dependency-unit"
    );
    form.append(
      field(t.source, source),
      field(t.predecessor, predecessor),
      field(t.type, type),
      field(t.lag, lag),
      field(t.unit, unit)
    );
    const submit = node("button", existing ? t.save : t.add);
    submit.type = "submit";
    submit.disabled = !(
      entries.length && options.session.config.dependencyTypes.length
    );
    form.append(submit);
    form.onsubmit = (event) => {
      event.preventDefault();
      const from = snapshot.tasks.find(
        (item) => planningKey(item.ref) === predecessor.value
      )?.ref;
      if (!from) {
        return;
      }
      options.session.request([
        {
          type: "dependency.put",
          dependency: {
            id: existing?.id ?? crypto.randomUUID(),
            from,
            to: task.ref,
            type: type.value as DependencyType,
            lag: Number(lag.value),
            lagUnit: unit.value as "workingDays" | "calendarDays",
          },
        },
      ]);
    };
    return form;
  }
  function taskDatesEditor(task: PlanningTask): HTMLElement {
    const t = labels();
    const session = options.session;
    const state = session.getState();
    const dates = node("form", undefined, "yp-editor");
    const start = input("date", task.start ?? "", "start-date");
    const end = input("date", task.end ?? "", "end-date");
    start.disabled = end.disabled =
      !(session.canEdit(task) && session.config.allowDateEdit) || state.busy;
    const parentOptions = [
      { value: "", label: t.root },
      ...(state.snapshot?.tasks ?? [])
        .filter((item) => !samePlanningRef(task.ref, item.ref))
        .map((item) => ({
          value: planningKey(item.ref),
          label: `${item.ref.source} · ${item.label}`,
        })),
    ];
    const parent = select(
      parentOptions,
      task.parent ? planningKey(task.parent) : "",
      "parent"
    );
    parent.disabled =
      !(session.canEdit(task) && session.config.allowHierarchyEdit) ||
      state.busy;
    dates.append(field(t.start, start), field(t.end, end));
    if (session.config.hierarchy) {
      dates.append(field(t.parent, parent));
    }
    const submit = node("button", t.save);
    submit.type = "submit";
    submit.disabled =
      !session.canEdit(task) ||
      state.busy ||
      !(session.config.allowDateEdit || session.config.allowHierarchyEdit);
    dates.append(submit);
    dates.onsubmit = (event) => {
      event.preventDefault();
      const mutations: import("./types").PlanningMutation[] = [];
      if (
        start.value !== (task.start ?? "") ||
        end.value !== (task.end ?? "")
      ) {
        mutations.push({
          type: "dates",
          ref: task.ref,
          start: start.value || null,
          end: end.value || null,
        });
      }
      const nextParent =
        state.snapshot?.tasks.find(
          (item) => planningKey(item.ref) === parent.value
        )?.ref ?? null;
      if (!samePlanningRef(nextParent, task.parent)) {
        mutations.push({ type: "parent", ref: task.ref, parent: nextParent });
      }
      if (mutations.length) {
        session.request(mutations);
      }
    };
    return dates;
  }
  function dependencyRow(
    edge: PlanningDependency,
    task: PlanningTask
  ): HTMLElement {
    const t = labels();
    const session = options.session;
    const state = session.getState();
    const row = node("div", undefined, "yp-dependency");
    const from = state.snapshot?.tasks.find((item) =>
      samePlanningRef(item.ref, edge.from)
    );
    const to = state.snapshot?.tasks.find((item) =>
      samePlanningRef(item.ref, edge.to)
    );
    row.append(
      node(
        "span",
        `${from?.label ?? edge.from.id} → ${to?.label ?? edge.to.id} · ${edge.type} · ${edge.lag ?? 0}`
      )
    );
    if (session.config.allowDependencyEdit && session.canEdit(task)) {
      if (samePlanningRef(edge.to, task.ref)) {
        row.append(
          button(
            t.edit,
            () => {
              editingLink = edge.id;
              renderOverlay();
            },
            state.busy
          )
        );
      }
      row.append(
        button(
          t.remove,
          () => {
            session.request([{ type: "dependency.remove", id: edge.id }]);
          },
          state.busy
        )
      );
    }
    return row;
  }
  function taskEditor(task: PlanningTask): HTMLElement {
    const t = labels();
    const session = options.session;
    const state = session.getState();
    const body = node("div", undefined, "yp-dialog-body");
    const dates = taskDatesEditor(task);
    body.append(dates, node("h3", t.dependencies));
    const links =
      state.snapshot?.dependencies.filter(
        (edge) =>
          samePlanningRef(edge.to, task.ref) ||
          samePlanningRef(edge.from, task.ref)
      ) ?? [];
    for (const edge of links) {
      body.append(dependencyRow(edge, task));
    }
    if (session.config.allowDependencyEdit && session.canEdit(task)) {
      body.append(
        node("h4", editingLink ? t.edit : t.newLink),
        dependencyEditor(
          task,
          links.find((edge) => edge.id === editingLink)
        )
      );
    }
    if (
      options.onOpenRecord &&
      task.ref.source === options.session.config.sourceId
    ) {
      body.append(
        button(t.record, () => {
          session.open();
          options.onOpenRecord?.(task);
        })
      );
    }
    return body;
  }
  function reasonLabel(reason: string): string {
    const t = labels();
    if (reason === "requested") {
      return t.requested;
    }
    if (reason === "summary") {
      return t.summary;
    }
    if (reason.startsWith("dependency:")) {
      return `${t.dependency} ${reason.slice(11)}`;
    }
    return t.group;
  }
  function dependencyChanges(
    preview: import("./types").PlanningPreview
  ): HTMLElement {
    const t = labels();
    const body = node("div", undefined, "yp-dialog-body");
    const before = new Map(
      (options.session.getState().snapshot?.dependencies ?? []).map((edge) => [
        edge.id,
        edge,
      ])
    );
    const after = new Map(preview.dependencies.map((edge) => [edge.id, edge]));
    const describe = (edge?: PlanningDependency): string =>
      edge
        ? `${edge.from.source}/${edge.from.id} → ${edge.to.source}/${edge.to.id} · ${edge.type} · ${edge.lag ?? 0} ${edge.lagUnit === "calendarDays" ? t.calendar : t.working}`
        : "—";
    for (const id of new Set([...before.keys(), ...after.keys()])) {
      if (JSON.stringify(before.get(id)) === JSON.stringify(after.get(id))) {
        continue;
      }
      body.append(
        node("h4", `${t.dependency} ${id}`),
        node("p", `${t.before}: ${describe(before.get(id))}`),
        node("p", `${t.after}: ${describe(after.get(id))}`)
      );
    }
    return body;
  }
  function taskChangeSummary(item: PlanningTask, other: PlanningTask): string {
    const t = labels();
    const fields = options.session
      .getState()
      .snapshot?.sources.find(
        (source) => source.id === item.ref.source
      )?.fields;
    const recordChanges = Object.keys({ ...item.record, ...other.record })
      .filter(
        (key) =>
          key !== fields?.start &&
          key !== fields?.end &&
          JSON.stringify(item.record?.[key]) !==
            JSON.stringify(other.record?.[key])
      )
      .map((key) => `${key}: ${JSON.stringify(item.record?.[key] ?? null)}`);
    const parent = item.parent
      ? `${item.parent.source}/${item.parent.id}`
      : t.root;
    return [
      `${item.start ?? t.noDates} → ${item.end ?? t.noDates}`,
      `${t.parent}: ${parent}`,
      ...recordChanges,
    ].join(" · ");
  }
  function previewBody(
    preview: import("./types").PlanningPreview
  ): HTMLElement {
    const state = options.session.getState();
    const t = labels();
    const body = node("div");
    const table = node("table");
    const head = node("thead");
    const row = node("tr");
    for (const label of [t.task, t.before, t.after, t.reason]) {
      row.append(node("th", label));
    }
    head.append(row);
    table.append(head);
    const tbody = node("tbody");
    for (const change of preview.changes) {
      const tr = node("tr");
      const reason = change.reasons.map((item) => reasonLabel(item)).join(", ");
      for (const text of [
        `${change.ref.source} · ${change.after.label}`,
        taskChangeSummary(change.before, change.after),
        taskChangeSummary(change.after, change.before),
        reason,
      ]) {
        tr.append(node("td", text));
      }
      tbody.append(tr);
    }
    table.append(tbody);
    const scroll = node("div", undefined, "yp-preview-table");
    scroll.append(table);
    body.append(scroll, dependencyChanges(preview));
    for (const warning of preview.warnings) {
      body.append(node("p", warning, "yp-warning"));
    }
    const actions = node("div", undefined, "yp-dialog-actions");
    actions.append(
      button(
        t.cancel,
        () => options.session.cancel(),
        state.busy,
        "cancel-preview"
      ),
      button(
        t.apply,
        () => {
          options.session.apply();
        },
        state.busy,
        "apply-preview"
      )
    );
    body.append(actions);
    return body;
  }
  function ensureDialog(): void {
    if (!dialog) {
      restoreFocus =
        doc.activeElement instanceof HTMLElement
          ? doc.activeElement
          : undefined;
      dialog = node("dialog", undefined, "yp-dialog");
      // Keep nested planning dialogs inside the active modal's accessibility boundary.
      const activeModal = doc.activeElement?.closest<HTMLElement>(
        '[role="dialog"],dialog'
      );
      const target =
        activeModal && !activeModal.classList.contains("yp-dialog")
          ? activeModal
          : container;
      target.append(dialog);
      dialog.oncancel = (event) => {
        event.preventDefault();
        if (options.session.getState().busy) {
          return;
        }
        if (options.session.getState().preview) {
          options.session.cancel();
        } else {
          options.session.open();
        }
      };
      if (typeof dialog.showModal === "function") {
        dialog.showModal();
      } else {
        dialog.setAttribute("open", "");
      }
    }
  }
  function closeDialog(): void {
    if (dialog) {
      dialog.close?.();
      dialog.remove();
      dialog = undefined;
      restoreFocus?.focus();
      restoreFocus = undefined;
    }
  }
  function captureDrafts(task?: PlanningTask): void {
    const revision = options.session.getState().snapshot?.revision ?? "";
    const context = `${task ? planningKey(task.ref) : ""}:${revision}:${editingLink ?? ""}`;
    if (context !== draftContext) {
      drafts.clear();
      draftContext = context;
      return;
    }
    for (const control of dialog?.querySelectorAll<
      HTMLInputElement | HTMLSelectElement
    >("input[data-focus],select[data-focus]") ?? []) {
      if (control.dataset.focus) {
        drafts.set(control.dataset.focus, control.value);
      }
    }
  }
  function renderOverlay(): void {
    const state = options.session.getState();
    const t = labels();
    const task = state.snapshot?.tasks.find((item) =>
      samePlanningRef(item.ref, state.selected)
    );
    if (!(task || state.preview)) {
      closeDialog();
      drafts.clear();
      draftContext = "";
      return;
    }
    const activeKey = (doc.activeElement as HTMLElement | null)?.dataset.focus;
    ensureDialog();
    if (!dialog) {
      return;
    }
    captureDrafts(task);
    dialog.replaceChildren();
    dialog.setAttribute(
      "aria-label",
      state.preview ? t.preview : `${t.planning}: ${task?.label ?? ""}`
    );
    const heading = node("div", undefined, "yp-dialog-heading");
    heading.append(node("h2", state.preview ? t.preview : task?.label));
    const close = button(
      t.close,
      () => {
        if (state.preview) {
          options.session.cancel();
        } else {
          options.session.open();
        }
      },
      state.busy,
      "close-dialog"
    );
    close.setAttribute("aria-label", t.close);
    close.title = t.close;
    close.className = "yp-icon-button";
    close.replaceChildren(icon("close"));
    heading.append(close);
    dialog.append(heading);
    const error = errorNode();
    if (error) {
      dialog.append(error);
    }
    if (state.preview) {
      dialog.append(previewBody(state.preview));
    } else if (task) {
      dialog.append(taskEditor(task));
    }
    if (state.busy) {
      const loading = node("p", t.loading);
      loading.setAttribute("role", "status");
      dialog.append(loading);
    }
    if (activeKey) {
      Array.from(dialog.querySelectorAll<HTMLElement>("[data-focus]"))
        .find((item) => item.dataset.focus === activeKey)
        ?.focus();
    }
  }
  const unsubscribe = options.session.subscribe(renderOverlay);
  renderOverlay();
  return {
    update(next: PlanningSurfaceOptions): void {
      options = next;
      renderOverlay();
    },
    destroy(): void {
      unsubscribe();
      dialog?.close?.();
      container.replaceChildren();
      restoreFocus?.focus();
    },
  };
}

import { dateDay, dayDate, isWorkingDay, taskCalendar } from "./calendar";
import { planningTree } from "./engine";
import type { PlanningSession } from "./session";
import {
  type PlanningDate,
  type PlanningSnapshot,
  type PlanningTask,
  planningKey,
  type TableGanttViewConfig,
} from "./types";

/**
 * Timeline geometry and projection, kept free of any framework so the React and Vue
 * timelines stay behaviourally identical while each renders with its own idioms.
 */
export const TIMELINE_ROW_HEIGHT = 42;
export const TIMELINE_HEADER_HEIGHT = 64;
export const TIMELINE_LABEL_WIDTH = 270;
export const TIMELINE_DEFAULT_HEIGHT = 480;
/** A navigable window bounds the rendered schedule; the period controls move it. */
export const TIMELINE_DAYS = 180;

const ZOOM_DAY_WIDTH = { day: 40, week: 24, month: 10 } as const;
const PERIOD_STEP = { day: 7, week: 30, month: 90 } as const;
const DAYS_IN_WEEK = 7;
const MIN_LABEL_WIDTH = 144;
const LABEL_WIDTH_RATIO = 0.42;
const FALLBACK_VIEWPORT_WIDTH = 1100;
const COLUMN_OVERSCAN_BEFORE = 2;
const COLUMN_OVERSCAN_AFTER = 8;
const ROW_OVERSCAN_BEFORE = 6;
const ROW_OVERSCAN_AFTER = 14;
const MIN_BAR_WIDTH = 8;
const LINK_ELBOW = 12;
/** Sunday is day 4 of the UTC epoch week; this realigns a day number to a weekday. */
const EPOCH_WEEKDAY_OFFSET = 4;

export interface TimelineRow {
  task: PlanningTask;
  depth: number;
  hasChildren: boolean;
}

export interface TimelineGeometry {
  /** Day number of the leftmost rendered column. */
  from: number;
  labelWidth: number;
  width: number;
  count: number;
  totalWidth: number;
  columnFrom: number;
  columnTo: number;
  firstRow: number;
  lastRow: number;
  height: number;
  canvasHeight: number;
}

export interface TimelineDayCell {
  day: number;
  date: PlanningDate;
  left: number;
  width: number;
  isToday: boolean;
  weekday: boolean;
  number: string;
}

export interface TimelineSpan {
  left: number;
  width: number;
}

export interface TimelineMonth extends TimelineSpan {
  date: PlanningDate;
}

export interface TimelineLink {
  id: string;
  d: string;
}

/** Today in the user's time zone: the UTC date is a different day near midnight. */
export const timelineToday = (now = new Date()): PlanningDate =>
  [
    now.getFullYear(),
    String(now.getMonth() + 1).padStart(2, "0"),
    String(now.getDate()).padStart(2, "0"),
  ].join("-");

/** How far the previous/next controls move the window at the current zoom. */
export const timelinePeriodStep = (
  zoom: TableGanttViewConfig["zoom"]
): number => PERIOD_STEP[zoom ?? "week"];

/** The earliest scheduled date, so an unanchored timeline opens on the work. */
export function timelineFirstDate(snapshot?: PlanningSnapshot): PlanningDate {
  const dates = snapshot?.tasks
    .flatMap((task) => (task.start ? [task.start] : []))
    .sort();
  return dates?.[0] ?? timelineToday();
}

/** Ordered, filtered and collapsed rows, preserving ancestor context. */
export function timelineRows(
  snapshot: PlanningSnapshot,
  options: {
    hierarchy?: boolean;
    visible?: (task: PlanningTask) => boolean;
    compare?: (a: PlanningTask, b: PlanningTask) => number;
    collapsed?: Set<string>;
  }
): TimelineRow[] {
  const ordered = options.compare
    ? { ...snapshot, tasks: [...snapshot.tasks].sort(options.compare) }
    : snapshot;
  const visible = options.visible
    ? new Set(
        ordered.tasks
          .filter(options.visible)
          .map((task) => planningKey(task.ref))
      )
    : undefined;
  if (options.hierarchy === false) {
    return ordered.tasks
      .filter((task) => !visible || visible.has(planningKey(task.ref)))
      .map((task) => ({ task, depth: 0, hasChildren: false }));
  }
  return planningTree(ordered, visible, options.collapsed ?? new Set());
}

export function timelineGeometry(input: {
  rowCount: number;
  view: TableGanttViewConfig;
  availableWidth?: number;
  height?: number;
  scrollTop: number;
  scrollLeft: number;
  firstDate: PlanningDate;
}): TimelineGeometry {
  const width = ZOOM_DAY_WIDTH[input.view.zoom ?? "week"];
  const anchor = dateDay(input.view.anchorDate ?? input.firstDate);
  const weekStart = input.view.weekStartsOn ?? 1;
  const weekday =
    (((anchor + EPOCH_WEEKDAY_OFFSET) % DAYS_IN_WEEK) + DAYS_IN_WEEK) %
    DAYS_IN_WEEK;
  const from = anchor - ((weekday - weekStart + DAYS_IN_WEEK) % DAYS_IN_WEEK);
  const count = TIMELINE_DAYS;
  const availableWidth = input.availableWidth || FALLBACK_VIEWPORT_WIDTH;
  const labelWidth = Math.min(
    TIMELINE_LABEL_WIDTH,
    Math.max(MIN_LABEL_WIDTH, Math.round(availableWidth * LABEL_WIDTH_RATIO))
  );
  const height = input.height ?? TIMELINE_DEFAULT_HEIGHT;
  const columnFrom = Math.max(
    0,
    Math.floor((input.scrollLeft - labelWidth) / width) - COLUMN_OVERSCAN_BEFORE
  );
  const columnTo = Math.min(
    count,
    columnFrom + Math.ceil(availableWidth / width) + COLUMN_OVERSCAN_AFTER
  );
  const firstRow = Math.max(
    0,
    Math.floor(input.scrollTop / TIMELINE_ROW_HEIGHT) - ROW_OVERSCAN_BEFORE
  );
  const lastRow = Math.min(
    input.rowCount,
    firstRow + Math.ceil(height / TIMELINE_ROW_HEIGHT) + ROW_OVERSCAN_AFTER
  );
  return {
    from,
    labelWidth,
    width,
    count,
    totalWidth: labelWidth + count * width,
    columnFrom,
    columnTo,
    firstRow,
    lastRow,
    height,
    canvasHeight: TIMELINE_HEADER_HEIGHT + input.rowCount * TIMELINE_ROW_HEIGHT,
  };
}

/** Only the day columns inside the rendered window. */
export function timelineDayCells(
  geometry: TimelineGeometry,
  view: TableGanttViewConfig
): TimelineDayCell[] {
  const today = timelineToday();
  const cells: TimelineDayCell[] = [];
  const isMonthZoom = view.zoom === "month";
  for (let day = geometry.columnFrom; day < geometry.columnTo; day += 1) {
    const date = dayDate(geometry.from + day);
    const labelled = !isMonthZoom || day % DAYS_IN_WEEK === 0;
    cells.push({
      day,
      date,
      left: geometry.labelWidth + day * geometry.width,
      width: geometry.width,
      isToday: date === today,
      weekday: labelled && !isMonthZoom,
      number: labelled ? String(Number(date.slice(8))) : "",
    });
  }
  return cells;
}

/** Month bands spanning the rendered window. */
export function timelineMonths(geometry: TimelineGeometry): TimelineMonth[] {
  const months: TimelineMonth[] = [];
  let start = geometry.columnFrom;
  while (start < geometry.columnTo) {
    const date = dayDate(geometry.from + start);
    let end = start + 1;
    while (
      end < geometry.columnTo &&
      dayDate(geometry.from + end).slice(0, 7) === date.slice(0, 7)
    ) {
      end += 1;
    }
    months.push({
      date,
      left: geometry.labelWidth + start * geometry.width,
      width: (end - start) * geometry.width,
    });
    start = end;
  }
  return months;
}

/** Undefined when the task is unscheduled or outside the rendered window. */
export function timelineBar(
  task: PlanningTask,
  geometry: TimelineGeometry
): TimelineSpan | undefined {
  if (!(task.start && task.end)) {
    return undefined;
  }
  const start = dateDay(task.start) - geometry.from;
  const end = dateDay(task.end) - geometry.from + 1;
  if (end <= 0 || start >= geometry.count) {
    return undefined;
  }
  const left = Math.max(0, start) * geometry.width;
  const width = Math.max(
    MIN_BAR_WIDTH,
    (Math.min(geometry.count, end) - Math.max(0, start)) * geometry.width
  );
  return { left, width };
}

/** Non-working day shading for this task's calendar, inside the rendered window. */
export function timelineOffDays(
  task: PlanningTask,
  snapshot: PlanningSnapshot,
  geometry: TimelineGeometry
): TimelineSpan[] {
  const spans: TimelineSpan[] = [];
  let calendar: ReturnType<typeof taskCalendar>;
  try {
    calendar = taskCalendar(task, snapshot);
  } catch {
    // The load error explains an unavailable calendar; keep the task inspectable.
    return spans;
  }
  for (let day = geometry.columnFrom; day < geometry.columnTo; day += 1) {
    if (!isWorkingDay(geometry.from + day, calendar)) {
      spans.push({ left: day * geometry.width, width: geometry.width });
    }
  }
  return spans;
}

function endpointX(
  task: PlanningTask & { start: string; end: string },
  finish: boolean,
  geometry: TimelineGeometry
): number {
  return (
    geometry.labelWidth +
    (dateDay(finish ? task.end : task.start) -
      geometry.from +
      (finish ? 1 : 0)) *
      geometry.width
  );
}

function scheduledAt(
  value: { task: PlanningTask; i: number } | undefined,
  first: number,
  last: number
): value is { task: PlanningTask & { start: string; end: string }; i: number } {
  return Boolean(
    value &&
      value.i >= first &&
      value.i < last &&
      value.task.start &&
      value.task.end
  );
}

/** Paths are drawn only when both endpoints are inside the rendered window. */
export function timelineLinks(
  rows: TimelineRow[],
  snapshot: PlanningSnapshot,
  geometry: TimelineGeometry
): TimelineLink[] {
  const positions = new Map(
    rows.map((row, i) => [planningKey(row.task.ref), { task: row.task, i }])
  );
  const links: TimelineLink[] = [];
  for (const edge of snapshot.dependencies) {
    const a = positions.get(planningKey(edge.from));
    const b = positions.get(planningKey(edge.to));
    if (
      !(
        scheduledAt(a, geometry.firstRow, geometry.lastRow) &&
        scheduledAt(b, geometry.firstRow, geometry.lastRow)
      )
    ) {
      continue;
    }
    const ax = endpointX(a.task, edge.type[0] === "F", geometry);
    const bx = endpointX(b.task, edge.type[1] === "F", geometry);
    if (
      ax < geometry.labelWidth ||
      bx < geometry.labelWidth ||
      ax > geometry.totalWidth ||
      bx > geometry.totalWidth
    ) {
      continue;
    }
    const ay = TIMELINE_HEADER_HEIGHT + (a.i + 0.5) * TIMELINE_ROW_HEIGHT;
    const by = TIMELINE_HEADER_HEIGHT + (b.i + 0.5) * TIMELINE_ROW_HEIGHT;
    const mid = Math.max(ax, bx) + LINK_ELBOW;
    links.push({
      id: edge.id,
      d: `M ${ax} ${ay} H ${mid} V ${by} H ${bx} l 5 -3 m -5 3 l 5 3`,
    });
  }
  return links;
}

/** Horizontal offset of the current date, or undefined when it is out of view. */
export function timelineTodayOffset(
  geometry: TimelineGeometry
): number | undefined {
  const today = dateDay(timelineToday()) - geometry.from;
  return today >= 0 && today < geometry.count
    ? geometry.labelWidth + (today + 0.5) * geometry.width
    : undefined;
}

/** Authorization, feature flags and in-flight state all gate a bar edit. */
export function timelineCanEdit(input: {
  task: PlanningTask;
  hasChildren: boolean;
  session: PlanningSession;
  snapshot: PlanningSnapshot;
}): boolean {
  const state = input.session.getState();
  const config = input.session.config;
  return (
    input.session.canEdit(input.task) &&
    config.allowDateEdit !== false &&
    !state.busy &&
    !state.preview &&
    input.snapshot.complete &&
    (!input.hasChildren ||
      config.parentDates === "independent" ||
      config.allowSummaryMove !== false)
  );
}

/** A leaf, or an independently dated parent, can be resized as well as moved. */
export function timelineCanResize(input: {
  hasChildren: boolean;
  session: PlanningSession;
}): boolean {
  return (
    !input.hasChildren || input.session.config.parentDates === "independent"
  );
}

/** The mutation a pointer drag or arrow key produces, shared by both editions. */
export function timelineDateMutation(
  task: PlanningTask,
  operation: "move" | "start" | "end",
  days: number
): import("./types").PlanningMutation[] {
  if (!days) {
    return [];
  }
  if (operation === "move") {
    return [{ type: "move", ref: task.ref, days }];
  }
  if (!(task.start && task.end)) {
    return [];
  }
  return [
    {
      type: "dates",
      ref: task.ref,
      start:
        operation === "start"
          ? dayDate(dateDay(task.start) + days)
          : task.start,
      end: operation === "end" ? dayDate(dateDay(task.end) + days) : task.end,
    },
  ];
}

import { calculatePlanning, planningDefaults } from "./engine";
import {
  type PlanningApplyInput,
  type PlanningContext,
  PlanningError,
  type PlanningLoadInput,
  type PlanningMutation,
  type PlanningPreview,
  type PlanningPreviewInput,
  type PlanningResult,
  type PlanningSnapshot,
  type TablePlanningActions,
  type TablePlanningConfig,
} from "./types";

/** Preview tokens are deliberately bounded; an evicted token requires a new preview. */
const MAX_RETAINED_PLANS = 100;

export interface PlanningCommitInput {
  /** The recalculated graph the adapter must make durable. */
  snapshot: PlanningSnapshot;
  preview: PlanningPreview;
  mutations: PlanningMutation[];
  context: PlanningContext;
}

export interface PlanningTransactionOptions {
  config: TablePlanningConfig;
  /** The authoritative graph as the adapter currently knows it. */
  read: () => PlanningSnapshot;
  load: (input: PlanningLoadInput) => Promise<PlanningSnapshot>;
  /** Makes the recalculated graph durable and returns the stored result. */
  commit: (
    input: PlanningCommitInput
  ) => Promise<PlanningSnapshot> | PlanningSnapshot;
  /** Runs at preview and again at commit, before the final revision check. */
  validate?: (
    snapshot: PlanningSnapshot,
    mutations: PlanningMutation[],
    preview: PlanningPreview
  ) => void | Promise<void>;
}

interface RetainedPlan {
  preview: PlanningPreview;
  mutations: PlanningMutation[];
  context: PlanningContext;
}

const failure = <T>(cause: unknown): PlanningResult<T> => ({
  success: false,
  error: cause instanceof Error ? cause.message : String(cause),
  code: cause instanceof PlanningError ? cause.code : "planning-error",
});

const staleError = (message: string): PlanningError =>
  new PlanningError("stale-preview", message);

const applySignature = (request: PlanningApplyInput): string =>
  JSON.stringify([
    request.scopeId,
    request.sourceId,
    request.previewId,
    request.revision,
  ]);

/** Every adapter entry point rejects a scope or source it does not serve. */
export function assertPlanningContext(
  current: PlanningSnapshot,
  scopeId: string,
  context: PlanningContext
): void {
  if (
    context.scopeId !== current.scopeId ||
    context.scopeId !== scopeId ||
    !current.sources.some((source) => source.id === context.sourceId)
  ) {
    throw new PlanningError(
      "scope-mismatch",
      "The planning scope or source is unavailable."
    );
  }
}

/**
 * The preview/apply state machine every planning adapter shares: revision checks,
 * bounded preview tokens, validation hooks and idempotent commits. Adapters only
 * supply how the graph is read, loaded and made durable.
 */
export function createPlanningTransactions(
  options: PlanningTransactionOptions
): TablePlanningActions {
  const config = planningDefaults(options.config);
  const plans = new Map<string, RetainedPlan>();
  const applied = new Map<
    string,
    { signature: string; snapshot: PlanningSnapshot }
  >();

  const checkContext = (context: PlanningContext): PlanningSnapshot => {
    const current = options.read();
    assertPlanningContext(current, config.scopeId, context);
    return current;
  };

  const priorCommit = (
    request: PlanningApplyInput
  ): PlanningSnapshot | undefined => {
    const prior = applied.get(request.idempotencyKey);
    if (!prior) {
      return undefined;
    }
    if (prior.signature !== applySignature(request)) {
      throw new PlanningError(
        "idempotency-conflict",
        "This request key was already used for another plan."
      );
    }
    return structuredClone(prior.snapshot);
  };

  const retain = (plan: RetainedPlan): void => {
    plans.set(plan.preview.id, plan);
    if (plans.size > MAX_RETAINED_PLANS) {
      const oldest = plans.keys().next().value;
      if (oldest) {
        plans.delete(oldest);
      }
    }
  };

  const requirePlan = (
    request: PlanningApplyInput,
    current: PlanningSnapshot
  ): RetainedPlan => {
    const plan = plans.get(request.previewId);
    if (
      !plan ||
      plan.preview.revision !== request.revision ||
      request.revision !== current.revision
    ) {
      throw staleError("The preview is stale. Reload and preview again.");
    }
    if (
      plan.context.scopeId !== request.scopeId ||
      plan.context.sourceId !== request.sourceId
    ) {
      throw new PlanningError(
        "scope-mismatch",
        "The preview belongs to another source."
      );
    }
    return plan;
  };

  const preview = async (
    request: PlanningPreviewInput
  ): Promise<PlanningResult<PlanningPreview>> => {
    try {
      const current = checkContext(request);
      if (request.revision !== current.revision) {
        throw staleError(
          "The planning changed. Reload it and create a new preview."
        );
      }
      const mutations = structuredClone(request.mutations);
      const result = calculatePlanning(current, mutations, {
        ...config,
        sourceId: request.sourceId,
      });
      const plan = { ...result.preview, id: crypto.randomUUID() };
      await options.validate?.(
        structuredClone(current),
        mutations,
        structuredClone(plan)
      );
      if (current.revision !== options.read().revision) {
        throw staleError("The planning changed while validating this preview.");
      }
      retain({
        preview: structuredClone(plan),
        mutations,
        context: { scopeId: request.scopeId, sourceId: request.sourceId },
      });
      return { success: true, data: plan };
    } catch (cause) {
      return failure(cause);
    }
  };

  const apply = async (
    request: PlanningApplyInput
  ): Promise<PlanningResult<PlanningSnapshot>> => {
    try {
      const current = checkContext(request);
      if (!request.idempotencyKey) {
        throw new PlanningError(
          "missing-idempotency-key",
          "Applying a plan requires an idempotency key."
        );
      }
      const prior = priorCommit(request);
      if (prior) {
        return { success: true, data: prior };
      }
      const plan = requirePlan(request, current);
      const recalculated = calculatePlanning(current, plan.mutations, {
        ...config,
        sourceId: request.sourceId,
      });
      await options.validate?.(
        structuredClone(current),
        plan.mutations,
        structuredClone(plan.preview)
      );
      // Another asynchronous validation may have committed or changed permissions meanwhile.
      const committed = priorCommit(request);
      if (committed) {
        return { success: true, data: committed };
      }
      if (request.revision !== options.read().revision) {
        throw staleError(
          "The planning changed during validation. No changes were saved."
        );
      }
      const stored = await options.commit({
        snapshot: recalculated.snapshot,
        preview: plan.preview,
        mutations: plan.mutations,
        context: plan.context,
      });
      applied.set(request.idempotencyKey, {
        signature: applySignature(request),
        snapshot: structuredClone(stored),
      });
      plans.delete(request.previewId);
      return { success: true, data: structuredClone(stored) };
    } catch (cause) {
      return failure(cause);
    }
  };

  return { load: options.load, preview, apply };
}

/** Civil dates are YYYY-MM-DD strings, never browser-local timestamps. End dates are inclusive. */
export type PlanningDate = string;
export type DependencyType = "FS" | "SS" | "FF" | "SF";
export interface PlanningRef {
  source: string;
  id: string;
}
export interface PlanningCalendar {
  id: string;
  /** Sunday is 0; this is unrelated to the first displayed weekday. */
  workingDays: number[];
  /** true opens a date, false closes it. */
  exceptions?: Record<PlanningDate, boolean>;
}
export interface PlanningFields {
  title?: string;
  start: string;
  end: string;
  parent?: string;
  calendar?: string;
}
export interface PlanningSource {
  id: string;
  label: string;
  calendarId?: string;
  fields?: PlanningFields;
}
export interface PlanningTask {
  ref: PlanningRef;
  label: string;
  start: PlanningDate | null;
  end: PlanningDate | null;
  parent?: PlanningRef | null;
  calendarId?: string;
  /** Host authorization applies to every affected task, including hidden successors. */
  editable?: boolean;
  record?: Record<string, unknown>;
}
export interface PlanningDependency {
  id: string;
  from: PlanningRef;
  to: PlanningRef;
  type: DependencyType;
  lag?: number;
  lagUnit?: "workingDays" | "calendarDays";
}
export interface PlanningSnapshot {
  scopeId: string;
  revision: string;
  tasks: PlanningTask[];
  dependencies: PlanningDependency[];
  sources: PlanningSource[];
  calendars: PlanningCalendar[];
  defaultCalendarId: string;
  /** A partial graph is displayable but must never be scheduled. */
  complete: boolean;
  nextCursor?: string;
}
export interface TablePlanningConfig {
  enabled: boolean;
  scopeId: string;
  sourceId: string;
  allowDateEdit?: boolean;
  allowDependencyEdit?: boolean;
  allowHierarchyEdit?: boolean;
  allowCrossTableDependencies?: boolean;
  allowSummaryMove?: boolean;
  hierarchy?: boolean;
  parentDates?: "rollup" | "independent";
  dependencyTypes?: DependencyType[];
  scheduling?: "manual" | "preview" | "automatic";
  /** Bound malformed calendars and unsatisfiable schedules without hanging the UI. */
  maxCalendarSearchDays?: number;
}
export interface TableGanttViewConfig {
  zoom?: "day" | "week" | "month";
  weekStartsOn?: number;
  showDependencies?: boolean;
  anchorDate?: PlanningDate;
}
export interface TableGanttConfig extends TableGanttViewConfig {
  titleColumn?: string;
  startColumn?: string;
  endColumn?: string;
  /** Scalar column holding the parent record id, for a hierarchy derived from the rows. */
  parentColumn?: string;
  /** Scalar column selecting the row's calendar. */
  calendarColumn?: string;
  height?: number;
}
export type PlanningMutation =
  | {
      type: "dates";
      ref: PlanningRef;
      start: PlanningDate | null;
      end: PlanningDate | null;
    }
  | { type: "move"; ref: PlanningRef; days: number }
  | { type: "parent"; ref: PlanningRef; parent: PlanningRef | null }
  | { type: "record"; ref: PlanningRef; patch: Record<string, unknown> }
  | { type: "dependency.put"; dependency: PlanningDependency }
  | { type: "dependency.remove"; id: string };
export interface PlanningChange {
  ref: PlanningRef;
  before: PlanningTask;
  after: PlanningTask;
  reasons: string[];
}
export interface PlanningPreview {
  id: string;
  revision: string;
  changes: PlanningChange[];
  dependencies: PlanningDependency[];
  warnings: string[];
}
export interface PlanningResult<T> {
  success: boolean;
  data?: T;
  error?: string;
  code?: string;
}
export interface PlanningContext {
  scopeId: string;
  sourceId: string;
}
export interface PlanningLoadInput extends PlanningContext {
  cursor?: string;
  signal?: AbortSignal;
}
export interface PlanningPreviewInput extends PlanningContext {
  revision: string;
  mutations: PlanningMutation[];
}
export interface PlanningApplyInput extends PlanningContext {
  previewId: string;
  revision: string;
  /** Reuse this key after an uncertain response. */
  idempotencyKey: string;
}
export interface TablePlanningActions {
  load: (input: PlanningLoadInput) => Promise<PlanningSnapshot>;
  preview: (
    input: PlanningPreviewInput
  ) => Promise<PlanningResult<PlanningPreview>>;
  apply: (
    input: PlanningApplyInput
  ) => Promise<PlanningResult<PlanningSnapshot>>;
}
export class PlanningError extends Error {
  readonly code: string;
  constructor(code: string, message: string) {
    super(message);
    this.code = code;
    this.name = "PlanningError";
  }
}
export const planningKey = (ref: PlanningRef): string =>
  JSON.stringify([ref.source, ref.id]);
export const samePlanningRef = (
  a?: PlanningRef | null,
  b?: PlanningRef | null
): boolean =>
  a == null ? b == null : b != null && a.source === b.source && a.id === b.id;

