/** Structural row contract shared by the independently installable editions. */
interface RangeSelectableRow {
  id: string;
  getCanMultiSelect: () => boolean;
  getCanSelect: () => boolean;
  getIsGrouped: () => boolean;
}

interface RowSelectionRangeTable<TRow> {
  getRowModel: () => { flatRows: readonly TRow[] };
}

export interface RowSelectionRangeOptions {
  anchorRowId: string;
  isSelected: boolean;
  rowSelection: Readonly<Record<string, boolean>>;
  rows: readonly { id: string }[];
  targetRowId: string;
}

/**
 * Returns rows that can participate in a multi-row selection range, excluding
 * generated grouping rows. The order matches the table's current flat model.
 */
export const getRangeSelectableRows = <TRow extends RangeSelectableRow>(
  table: RowSelectionRangeTable<TRow>
): TRow[] => {
  const rows: TRow[] = [];
  const seenRowIds = new Set<string>();

  for (const row of table.getRowModel().flatRows) {
    const isGroupedRow = row.getIsGrouped();
    const isDuplicate = seenRowIds.has(row.id);

    if (
      isGroupedRow ||
      isDuplicate ||
      !row.getCanSelect() ||
      !row.getCanMultiSelect()
    ) {
      continue;
    }

    seenRowIds.add(row.id);
    rows.push(row);
  }

  return rows;
};

/**
 * Applies an inclusive range toggle without changing selections outside it.
 * Returns undefined when either endpoint is absent from the supplied row order.
 */
export const getNextRowSelectionForRange = ({
  anchorRowId,
  isSelected,
  rowSelection,
  rows,
  targetRowId,
}: RowSelectionRangeOptions): Record<string, true> | undefined => {
  const anchorIndex = rows.findIndex((row) => row.id === anchorRowId);
  const targetIndex = rows.findIndex((row) => row.id === targetRowId);

  if (anchorIndex === -1 || targetIndex === -1) {
    return undefined;
  }

  const rangeStart = Math.min(anchorIndex, targetIndex);
  const rangeEnd = Math.max(anchorIndex, targetIndex);
  const nextRowSelection: Record<string, true> = {};
  for (const [id, selected] of Object.entries(rowSelection)) {
    if (selected) {
      nextRowSelection[id] = true;
    }
  }

  for (let index = rangeStart; index <= rangeEnd; index += 1) {
    const row = rows[index];
    if (!row) {
      continue;
    }

    if (isSelected) {
      nextRowSelection[row.id] = true;
    } else {
      delete nextRowSelection[row.id];
    }
  }

  return nextRowSelection;
};

const SELECTION_SCOPE_SELECTOR = "[data-yayaw-table-selection-scope]";
const SELECTION_ROW_SELECTOR = "[data-yayaw-table-selection-row-id]";

/** Resolve only rendered, selectable rows in their visible order. */
export const getRenderedRangeRows = <TRow extends RangeSelectableRow>(
  checkboxElement: HTMLElement | null,
  table: RowSelectionRangeTable<TRow>
): TRow[] => {
  const rangeRows = getRangeSelectableRows(table);
  const selectionScope = checkboxElement?.closest(SELECTION_SCOPE_SELECTOR);

  if (!selectionScope) {
    return rangeRows;
  }

  const rowById = new Map(rangeRows.map((rangeRow) => [rangeRow.id, rangeRow]));
  const renderedRows: TRow[] = [];
  const seenRowIds = new Set<string>();

  for (const selectionControl of selectionScope.querySelectorAll(
    SELECTION_ROW_SELECTOR
  )) {
    if (selectionControl.hasAttribute("data-yayaw-table-selection-disabled")) {
      continue;
    }

    const rowId = selectionControl.getAttribute(
      "data-yayaw-table-selection-row-id"
    );
    const renderedRow = rowId ? rowById.get(rowId) : undefined;

    if (!(renderedRow && !seenRowIds.has(renderedRow.id))) {
      continue;
    }

    seenRowIds.add(renderedRow.id);
    renderedRows.push(renderedRow);
  }

  return renderedRows.length > 0 ? renderedRows : rangeRows;
};

import { type ContractRecord, compatibleListParams } from "./table-contracts";

/**
 * A window a view needs rows for, such as the dates a calendar shows.
 * Days are local calendar days (`YYYY-MM-DD`), both ends inclusive.
 */
export interface DateRangeScope {
  kind: "dateRange";
  /** Column holding the start date, or the only date. */
  field: string;
  /** Column holding the end date; a row then overlaps the window when its span does. */
  endField?: string;
  from: string;
  to: string;
}

export type ListScope = DateRangeScope;

type ListAction = (params: ContractRecord) => Promise<{
  data: unknown[];
  meta?: { pageCount?: number; scope?: string; totalCount?: number };
}>;

export interface ScopedRowsRequest {
  /** Server list action. Receives `scope` beside the usual list parameters. */
  list?: ListAction;
  /** Local rows, used when there is no list action. */
  rows?: readonly unknown[];
  params?: ContractRecord;
  scope?: ListScope;
  pageSize?: number;
  /** Rows kept at most; views show that the result was truncated. */
  maxRows?: number;
  /** `throw` for views that are wrong when incomplete, such as a planning graph. */
  overflow?: "throw" | "truncate";
  signal?: AbortSignal;
}

export interface ScopedRowsResult {
  rows: Record<string, unknown>[];
  truncated: boolean;
  /** `server` when the list action confirmed it applied the scope with `meta.scope: "applied"`. */
  scopeApplied: "client" | "none" | "server";
}

export class ScopedRowsOverflowError extends Error {
  constructor(maxRows: number) {
    super(`More than ${maxRows} rows match. Narrow the filters and try again.`);
    this.name = "ScopedRowsOverflowError";
  }
}

export const DEFAULT_SCOPED_PAGE_SIZE = 100;
export const DEFAULT_SCOPED_MAX_ROWS = 2000;
const MAX_SCOPED_PAGES = 1000;
const DATE_ONLY_PATTERN = /^\d{4}-\d{2}-\d{2}$/;
const pad = (value: number) => String(value).padStart(2, "0");

/** The local calendar day of a date value, matching the date filters' day semantics. */
export function localDayKey(value: unknown): string | undefined {
  if (value === null || value === undefined || value === "") {
    return;
  }
  if (typeof value === "string" && DATE_ONLY_PATTERN.test(value)) {
    return value;
  }
  const date =
    value instanceof Date || typeof value === "number"
      ? new Date(value)
      : new Date(String(value));
  if (!Number.isFinite(date.getTime())) {
    return;
  }
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
}

export function rowInScope(
  row: Record<string, unknown>,
  scope: ListScope
): boolean {
  const start = localDayKey(row[scope.field]);
  if (!start) {
    return false;
  }
  const end =
    (scope.endField ? localDayKey(row[scope.endField]) : undefined) ?? start;
  return start <= scope.to && end >= scope.from;
}

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null;

function capRows(
  rows: Record<string, unknown>[],
  maxRows: number,
  overflow: "throw" | "truncate"
): { rows: Record<string, unknown>[]; truncated: boolean } {
  if (rows.length <= maxRows) {
    return { rows, truncated: false };
  }
  if (overflow === "throw") {
    throw new ScopedRowsOverflowError(maxRows);
  }
  return { rows: rows.slice(0, maxRows), truncated: true };
}

function isLastPage(
  batch: number,
  meta: { pageCount?: number; totalCount?: number } | undefined,
  page: number,
  loaded: number,
  pageSize: number
): boolean {
  const pageCount = Number(meta?.pageCount);
  const totalCount = Number(meta?.totalCount);
  if (Number.isFinite(pageCount) && pageCount > 0) {
    return page >= pageCount;
  }
  if (Number.isFinite(totalCount) && totalCount >= 0) {
    return loaded >= totalCount;
  }
  return batch < pageSize;
}

function appliedBy(
  scope: ListScope | undefined,
  serverScoped: boolean
): ScopedRowsResult["scopeApplied"] {
  if (!scope) {
    return "none";
  }
  return serverScoped ? "server" : "client";
}

/**
 * Load every row a view needs, not only the current page.
 *
 * The scope is sent to the list action; a server that filters by it answers
 * `meta.scope: "applied"`. Otherwise rows are filtered here, so hosts that have
 * not implemented scopes keep working, only with more data transferred.
 */
export async function loadScopedRows({
  list,
  rows,
  params = {},
  scope,
  pageSize = DEFAULT_SCOPED_PAGE_SIZE,
  maxRows = DEFAULT_SCOPED_MAX_ROWS,
  overflow = "truncate",
  signal,
}: ScopedRowsRequest): Promise<ScopedRowsResult> {
  const keep = (row: unknown): row is Record<string, unknown> =>
    isRecord(row) && (!scope || rowInScope(row, scope));
  if (!list) {
    return {
      ...capRows((rows ?? []).filter(keep), maxRows, overflow),
      scopeApplied: appliedBy(scope, false),
    };
  }

  const request = compatibleListParams({ ...params, pageSize });
  const collected: Record<string, unknown>[] = [];
  let loaded = 0;
  let serverScoped = false;
  for (let page = 1; page <= MAX_SCOPED_PAGES; page += 1) {
    signal?.throwIfAborted();
    const result = await list({
      ...request,
      ...(scope ? { scope } : {}),
      page,
    });
    signal?.throwIfAborted();
    if (page === 1) {
      serverScoped = Boolean(scope) && result.meta?.scope === "applied";
    }
    const batch = result.data ?? [];
    loaded += batch.length;
    collected.push(...batch.filter(serverScoped ? isRecord : keep));
    const done =
      batch.length === 0 ||
      isLastPage(batch.length, result.meta, page, loaded, pageSize);
    // Stop early once the cap is exceeded; the caller only needs to know it was.
    if (done || collected.length > maxRows) {
      return {
        ...capRows(collected, maxRows, overflow),
        scopeApplied: appliedBy(scope, serverScoped),
      };
    }
  }
  throw new Error(
    "Too many pages to load all matching rows. Narrow the filters and try again."
  );
}

import { getNextRowSelectionForRange } from "./row-selection-range";

const anchors = new WeakMap<object, { id: string; order: string }>();

/** A stable table scope owns one anchor shared by every selection surface. */
export function selectionAfterClick({
  scope,
  rows,
  selection,
  id,
  selected,
  shift,
  multiple = true,
}: {
  scope: object;
  rows: readonly { id: string }[];
  selection: Readonly<Record<string, boolean>>;
  id: string;
  selected: boolean;
  shift: boolean;
  multiple?: boolean;
}): Record<string, boolean> {
  const order = JSON.stringify(rows.map((row) => row.id));
  const anchor = anchors.get(scope);
  if (multiple && shift && anchor?.order === order) {
    const result = getNextRowSelectionForRange({
      anchorRowId: anchor.id,
      targetRowId: id,
      rows,
      rowSelection: selection,
      isSelected: selected,
    });
    if (result) {
      return result;
    }
  }
  anchors.set(scope, { id, order });
  const result = multiple ? { ...selection } : {};
  if (selected) {
    result[id] = true;
  } else {
    delete result[id];
  }
  return result;
}

const EDITOR_OR_OVERLAY =
  'input, textarea, select, [contenteditable]:not([contenteditable="false"]), [role="textbox"], dialog, [role="dialog"], [role="alertdialog"], [role="menu"], [role="listbox"]';

interface SelectionScope {
  root: HTMLElement;
  enabled: () => boolean;
  selectAll?: () => void;
  undo?: () => void;
  duplicate?: () => void;
}

interface SelectionManager {
  scopes: Set<SelectionScope>;
  active?: SelectionScope;
  dispose: () => void;
}

const managers = new WeakMap<Document, SelectionManager>();

function isVisible(scope: SelectionScope): boolean {
  return (
    scope.root.isConnected &&
    !scope.root.closest('[hidden], [inert], [aria-hidden="true"]') &&
    scope.root.getClientRects().length > 0 &&
    scope.root.ownerDocument.defaultView?.getComputedStyle(scope.root)
      .visibility !== "hidden"
  );
}

function scopeForTarget(
  manager: SelectionManager,
  target: Element
): SelectionScope | undefined {
  // Pick the innermost table when a record embeds another table.
  let match: SelectionScope | undefined;
  for (const scope of manager.scopes) {
    if (
      scope.root.contains(target) &&
      (!match || match.root.contains(scope.root))
    ) {
      match = scope;
    }
  }
  return match;
}

function resolveScope(
  manager: SelectionManager,
  document: Document,
  target: Element
): SelectionScope | undefined {
  const direct = scopeForTarget(manager, target);
  if (
    direct ||
    (target !== document.body && target !== document.documentElement)
  ) {
    return direct;
  }
  const candidates = [...manager.scopes].filter(
    (item) => item.enabled() && isVisible(item)
  );
  if (manager.active && candidates.includes(manager.active)) {
    return manager.active;
  }
  return candidates.length === 1 ? candidates[0] : undefined;
}

function createManager(document: Document): SelectionManager {
  const manager: SelectionManager = {
    scopes: new Set(),
    dispose: () => undefined,
  };
  const activate = (event: Event): void => {
    if (event.target instanceof Element) {
      manager.active = scopeForTarget(manager, event.target);
    }
  };
  const onKeyDown = (event: KeyboardEvent): void => {
    if (
      event.defaultPrevented ||
      !(event.ctrlKey || event.metaKey) ||
      event.altKey ||
      event.shiftKey ||
      !["a", "z", "d"].includes(event.key.toLowerCase())
    ) {
      return;
    }
    const target = event.target;
    if (!(target instanceof Element) || target.closest(EDITOR_OR_OVERLAY)) {
      return;
    }
    // An open portal must keep its shortcuts even when its focus briefly returns to body.
    if (
      [
        ...document.querySelectorAll(
          'dialog[open], [role="dialog"], [role="alertdialog"], [role="menu"], [role="listbox"]'
        ),
      ].some(
        (element) =>
          element.getClientRects().length > 0 &&
          !element.closest('[hidden], [aria-hidden="true"]')
      )
    ) {
      return;
    }
    const scope = resolveScope(manager, document, target);
    if (!(scope?.enabled() && isVisible(scope))) {
      return;
    }
    const commands: Record<string, (() => void) | undefined> = {
      a: scope.selectAll,
      z: scope.undo,
      d: scope.duplicate,
    };
    const command = commands[event.key.toLowerCase()];
    if (!command) {
      return;
    }
    event.preventDefault();
    event.stopPropagation();
    if (!event.repeat) {
      command();
    }
  };
  document.addEventListener("pointerdown", activate, true);
  document.addEventListener("focusin", activate, true);
  document.addEventListener("keydown", onKeyDown, true);
  manager.dispose = () => {
    document.removeEventListener("pointerdown", activate, true);
    document.removeEventListener("focusin", activate, true);
    document.removeEventListener("keydown", onKeyDown, true);
  };
  return manager;
}

/** Catch Select All before the browser, including an unfocused single-table page. */
export function registerSelectionShortcuts(scope: SelectionScope): () => void {
  const document = scope.root.ownerDocument;
  let manager = managers.get(document);
  if (!manager) {
    manager = createManager(document);
    managers.set(document, manager);
  }
  manager.scopes.add(scope);
  return () => {
    manager.scopes.delete(scope);
    if (manager.active === scope) {
      manager.active = undefined;
    }
    if (manager.scopes.size === 0) {
      manager.dispose();
      managers.delete(document);
    }
  };
}

/** Read-oriented remote boards load each lane independently of grid pagination. */
export interface ServerKanbanGroup {
  value: string;
  label: string;
  totalCount: number;
}
export interface ServerKanbanPage {
  rows: Record<string, unknown>[];
  nextCursor: string | null;
}
export interface ServerKanbanSource {
  /** Change whenever search, filters, sorting, permissions, or refresh identity changes. */
  queryKey: string;
  groups: (signal: AbortSignal) => Promise<ServerKanbanGroup[]>;
  rows: (
    group: string,
    cursor: string | null,
    signal: AbortSignal
  ) => Promise<ServerKanbanPage>;
  getRowId?: (row: Record<string, unknown>) => string;
  onActivate?: (row: Record<string, unknown>) => void;
  labels?: {
    loading?: string;
    retry?: string;
    loadMore?: string;
    empty?: string;
  };
}
export interface ServerKanbanLane extends ServerKanbanGroup {
  rows: Record<string, unknown>[];
  nextCursor: string | null;
  loading: boolean;
  error?: string;
}
export interface ServerKanbanState {
  lanes: ServerKanbanLane[];
  loading: boolean;
  error?: string;
}

/** Every publication is immutable; aborted or superseded reads cannot restore another scope. */
export function createServerKanban(
  source: ServerKanbanSource,
  publish: (state: ServerKanbanState) => void
) {
  let state: ServerKanbanState = { lanes: [], loading: true };
  const controller = new AbortController();
  const id =
    source.getRowId ?? ((row: Record<string, unknown>) => String(row.id));
  const emit = () => {
    if (!controller.signal.aborted) {
      publish(state);
    }
  };
  const patch = (value: string, change: Partial<ServerKanbanLane>) => {
    state = {
      ...state,
      lanes: state.lanes.map((lane) =>
        lane.value === value ? { ...lane, ...change } : lane
      ),
    };
    emit();
  };
  const loadLane = async (value: string) => {
    const lane = state.lanes.find((item) => item.value === value);
    if (
      !lane ||
      lane.loading ||
      (lane.rows.length && lane.nextCursor === null)
    ) {
      return;
    }
    patch(value, { loading: true, error: undefined });
    try {
      const page = await source.rows(value, lane.nextCursor, controller.signal);
      if (controller.signal.aborted) {
        return;
      }
      if (page.nextCursor !== null && page.nextCursor === lane.nextCursor) {
        throw new Error("The server returned a repeated cursor.");
      }
      const rows = new Map(lane.rows.map((row) => [id(row), row]));
      for (const row of page.rows) {
        rows.set(id(row), row);
      }
      patch(value, {
        rows: [...rows.values()],
        nextCursor: page.nextCursor,
        loading: false,
      });
    } catch (cause) {
      patch(value, {
        loading: false,
        error: cause instanceof Error ? cause.message : String(cause),
      });
    }
  };
  const load = async () => {
    if (controller.signal.aborted) {
      return;
    }
    state = { lanes: [], loading: true };
    emit();
    try {
      const groups = await source.groups(controller.signal);
      if (controller.signal.aborted) {
        return;
      }
      if (
        new Set(groups.map((group) => group.value)).size !== groups.length ||
        groups.some(
          (group) => !Number.isInteger(group.totalCount) || group.totalCount < 0
        )
      ) {
        throw new Error("Invalid server board groups.");
      }
      state = {
        loading: false,
        lanes: groups.map((group) => ({
          ...group,
          rows: [],
          nextCursor: null,
          loading: false,
        })),
      };
      emit();
      await Promise.all(
        groups
          .filter((group) => group.totalCount > 0)
          .map((group) => loadLane(group.value))
      );
    } catch (cause) {
      state = {
        ...state,
        loading: false,
        error: cause instanceof Error ? cause.message : String(cause),
      };
      emit();
    }
  };
  return { load, loadLane, dispose: () => controller.abort() };
}

:root {
  /* The host's shadcn theme wins; fallbacks are shadcn's neutral theme, as in React. */
  --yayaw-background: var(--background, oklch(1 0 0));
  --yayaw-foreground: var(--foreground, oklch(0.145 0 0));
  --yayaw-muted: var(--muted, oklch(0.97 0 0));
  --yayaw-muted-foreground: var(--muted-foreground, oklch(0.556 0 0));
  --yayaw-border: var(--border, oklch(0.922 0 0));
  --yayaw-input: var(--input, oklch(0.922 0 0));
  --yayaw-primary: var(--primary, oklch(0.205 0 0));
  --yayaw-primary-foreground: var(--primary-foreground, oklch(0.985 0 0));
  --yayaw-danger: var(--destructive, oklch(0.577 0.245 27.325));
  --yayaw-ring: var(--ring, oklch(0.708 0 0));
  /* Controls use shadcn's rounded-md: the theme radius minus 2px. */
  --yayaw-radius: calc(var(--radius, 0.625rem) - 2px);
  --yayaw-shadow: 0 12px 40px rgba(0, 0, 0, 0.12);
  --yayaw-shadow-xs: 0 1px 2px 0 rgb(0 0 0 / 0.05);
}
.dark {
  --yayaw-background: var(--background, oklch(0.145 0 0));
  --yayaw-foreground: var(--foreground, oklch(0.985 0 0));
  --yayaw-muted: var(--muted, oklch(0.269 0 0));
  --yayaw-muted-foreground: var(--muted-foreground, oklch(0.708 0 0));
  --yayaw-border: var(--border, oklch(1 0 0 / 10%));
  --yayaw-input: var(--input, oklch(1 0 0 / 15%));
  --yayaw-primary: var(--primary, oklch(0.922 0 0));
  --yayaw-primary-foreground: var(--primary-foreground, oklch(0.205 0 0));
  --yayaw-danger: var(--destructive, oklch(0.704 0.191 22.216));
  --yayaw-ring: var(--ring, oklch(0.556 0 0));
}
