}
.yayaw-options-item-copy small {
  margin-top: 2px;
  color: var(--yayaw-muted-foreground);
  font-size: 12px;
}
.yayaw-options-item-end {
  display: flex;
  width: 32px;
  flex: none;
  align-items: center;
  justify-content: flex-end;
  color: var(--yayaw-muted-foreground);
}
.yayaw-options-item-count {
  display: flex;
  width: 20px;
  height: 20px;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  background: var(--yayaw-primary);
  color: var(--yayaw-primary-foreground);
  font-size: 12px;
}
.yayaw-options-content {
  display: grid;
  gap: 9px;
  max-height: 350px;
  overflow: auto;
  padding: 10px;
}
.yayaw-options-check {
  border-radius: 6px;
  padding: 6px;
}
.yayaw-options-check:hover {
  background: var(--yayaw-muted);
}
.yayaw-options-rule {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  gap: 6px;
  align-items: center;
}
.yayaw-column-toggles {
  display: grid;
  gap: 6px;
}
.yayaw-column-filters {
  display: flex;
  align-items: end;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 10px;
  border: 1px solid var(--yayaw-border);
  border-radius: var(--yayaw-radius);
  background: color-mix(in srgb, var(--yayaw-muted) 50%, transparent);
  padding: 10px;
}
.yayaw-field-inline {
  display: grid;
  gap: 4px;
  color: var(--yayaw-muted-foreground);
  font-size: 12px;
}
.yayaw-advanced-filters {
  display: grid;
  gap: 12px;
  min-width: 0;
}
.yayaw-filter-join {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: var(--yayaw-muted-foreground);
}
.yayaw-filter-rule {
  min-width: 0;
  padding: 8px 0;
  border: 0;
  border-bottom: 1px solid var(--yayaw-border);
}
.yayaw-filter-row {
  align-items: flex-end;
  flex-wrap: wrap;
  gap: 10px;
}
.yayaw-filter-row > .yayaw-field-inline {
  flex: 1 1 130px;
  min-width: 0;
}
.yayaw-filter-options {
  flex: 2 1 180px;
  min-width: 0;
  margin: 0;
  padding: 0;
  border: 0;
}
.yayaw-filter-options legend,
.yayaw-filter-hint {
  color: var(--yayaw-muted-foreground);
  font-size: 12px;
}
.yayaw-filter-option-list {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 12px;
  padding: 4px 0;
}
.yayaw-filter-buttons {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  width: 100%;
  gap: 6px;
}
.yayaw-content {
  position: relative;
  min-height: 90px;
}
.yayaw-grid-shell {
  overflow: hidden;
  border: 1px solid var(--yayaw-border);
  border-radius: var(--yayaw-radius);
  background: var(--yayaw-background);
}
.yayaw-table-scroll {
  width: 100%;
  overflow: auto;
}
.yayaw-data-grid {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  table-layout: auto;
}
.yayaw-data-grid.resizable {
  table-layout: fixed;
}
.yayaw-data-grid th,
.yayaw-data-grid td {
  height: var(--yayaw-density-height);
  border-bottom: 1px solid var(--yayaw-border);
  padding: var(--yayaw-density-py) var(--yayaw-density-px);
  text-align: left;
  vertical-align: middle;
}
.yayaw-data-grid th {
  position: sticky;
  z-index: 3;
  top: 0;
  background: color-mix(
    in oklab,
    var(--yayaw-muted) 20%,
    var(--yayaw-background)
  );
  color: var(--yayaw-foreground);
  font-size: 14px;
  font-weight: 500;
}
.yayaw-data-grid thead th + th {
  border-left: 1px solid var(--yayaw-border);
}
/* Column menus appear on hover or keyboard focus, as in React. */
.yayaw-data-grid th .yayaw-column-menu-trigger {
  opacity: 0;
}
.yayaw-data-grid th:hover .yayaw-column-menu-trigger,
.yayaw-data-grid th:focus-within .yayaw-column-menu-trigger,
.yayaw-data-grid th .yayaw-column-menu-trigger[aria-expanded="true"] {
  opacity: 1;
}
.yayaw-data-grid th.sortable {
  cursor: pointer;
  user-select: none;
}
.yayaw-data-grid tbody tr:hover td,
.yayaw-data-grid tbody tr.selected td {
  background: color-mix(in srgb, var(--yayaw-muted) 70%, transparent);
}
.yayaw-data-grid tbody tr {
  cursor: default;
}
.yayaw-data-grid tbody tr.grouped {
  background: color-mix(in srgb, var(--yayaw-muted) 20%, transparent);
}
.yayaw-data-grid td.yayaw-group-heading {
  padding: 0;
}
.yayaw-group-toggle {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  min-height: var(--yayaw-density-height, 40px);
  padding: 4px 8px;
  text-align: start;
  cursor: pointer;
}
.yayaw-group-toggle:focus-visible {
  outline: 2px solid var(--yayaw-primary);
  outline-offset: -2px;
}
.yayaw-data-grid tfoot td {
  background: var(--yayaw-muted);
}
.yayaw-header-cell {
  position: relative;
  display: flex;
  align-items: center;
  gap: 6px;
}
.yayaw-column-resize-handle {
  position: absolute;
  z-index: 4;
  top: -8px;
  right: -12px;
  bottom: -8px;
  width: 8px;
  cursor: col-resize;
  touch-action: none;
  outline: none;
}
.yayaw-column-resize-handle::after {
  position: absolute;
  top: 4px;
  right: 0;
  bottom: 4px;
  width: 2px;
  background: var(--yayaw-border);
  content: "";
}
.yayaw-column-resize-handle:hover::after,
.yayaw-column-resize-handle:focus-visible::after {
  background: var(--yayaw-primary);
}
.yayaw-column-menu-trigger,
.yayaw-column-drag-handle {
  margin-left: auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  flex: 0 0 24px;
  border-radius: var(--yayaw-radius);
  border: 0;
  background: transparent;
  color: var(--yayaw-muted-foreground);
  cursor: pointer;
}
.yayaw-column-sort {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 0;
  border: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  cursor: pointer;
}
.yayaw-column-sort svg,
.yayaw-column-menu-trigger svg,
.yayaw-column-drag-handle svg,
.yayaw-column-menu-item svg,
.yayaw-view-menu-item svg {
  width: 16px;
  height: 16px;
  flex: 0 0 16px;
}
.yayaw-column-menu,
.yayaw-view-menu {
  box-sizing: border-box;
  font:
    13px / 1.4 ui-sans-serif,
    system-ui,
    sans-serif;
  z-index: 100;
  min-width: 180px;
  padding: 4px;
  border: 1px solid var(--yayaw-border);
  border-radius: var(--yayaw-radius);
  background: var(--yayaw-background);
  color: var(--yayaw-foreground);
  box-shadow: 0 4px 12px rgb(0 0 0 / 0.12);
}
.yayaw-column-menu-item,
.yayaw-view-menu-item {
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 32px;
  padding: 4px 8px;
  border-radius: var(--yayaw-radius);
  font-size: 13px;
  cursor: pointer;
}
.yayaw-view-menu-item[data-highlighted],
.yayaw-column-menu-item[data-highlighted],
.yayaw-column-menu-trigger:hover {
  background: var(--yayaw-muted);
  outline: none;
}
.yayaw-column-drag-handle:hover,
.yayaw-column-drag-handle[aria-pressed="true"] {
  background: var(--yayaw-muted);
  outline: none;
}
.yayaw-view-menu-item[data-disabled],
.yayaw-column-menu-item[data-disabled] {
  opacity: 0.5;
  pointer-events: none;
}
.yayaw-column-menu-divider,
.yayaw-view-menu-divider {
  height: 1px;
  margin: 4px 0;
  background: var(--yayaw-border);
}
.yayaw-column-menu-trigger:focus-visible,
.yayaw-column-drag-handle:focus-visible,
.yayaw-column-sort:focus-visible {
  outline: 2px solid var(--yayaw-primary);
  outline-offset: 2px;
}
.yayaw-cell {
  position: relative;
  max-width: 480px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.yayaw-cell.is-editable {
  cursor: text;
}
.yayaw-inline-editor {
  width: 100%;
  min-width: 110px;
}
.yayaw-inline-selection {
  display: flex;
  height: var(--yayaw-density-control, 32px);
  min-height: var(--yayaw-density-control, 32px);
  align-items: center;
  gap: 6px;
  overflow: hidden;
  border: 1px solid var(--yayaw-border);
  border-radius: 6px;
  padding: 0 6px;
  white-space: nowrap;
}
.yayaw-inline-selection:focus-within {
  border-color: var(--yayaw-primary);
  box-shadow: 0 0 0 3px
    color-mix(in srgb, var(--yayaw-primary) 20%, transparent);
}
.yayaw-inline-chips {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 6px;
  overflow-x: auto;
  scrollbar-width: none;
}
.yayaw-inline-chips::-webkit-scrollbar {
  display: none;
}
.yayaw-inline-chip {
  display: inline-flex;
  flex-shrink: 0;
  height: 22px;
  align-items: center;
  gap: 4px;
  border-radius: 4px;
  padding: 0 0 0 6px;
  background: var(--yayaw-muted);
  color: var(--yayaw-foreground);
  font-size: 12px;
  font-weight: 500;
}
.yayaw-inline-chip button {
  display: inline-flex;
  width: 24px;
  height: 24px;
  align-items: center;
  justify-content: center;
  border: 0;
  background: transparent;
  color: inherit;
  opacity: 0.5;
  cursor: pointer;
}
.yayaw-inline-chip button:hover,
.yayaw-inline-chip button:focus-visible {
  opacity: 1;
}
.yayaw-inline-chip button:disabled {
  cursor: not-allowed;
  opacity: 0.3;
}
.yayaw-inline-search {
  flex: 1;
  width: 0;
  min-width: 64px;
  height: 24px;
  border: 0;
  outline: none;
  background: transparent;
  color: inherit;
  padding: 0;
  font: inherit;
}
.yayaw-inline-options {
  z-index: 60;
  box-sizing: border-box;
  width: var(--reka-combobox-trigger-width);
  max-width: calc(100vw - 16px);
  max-height: min(252px, var(--reka-combobox-content-available-height));
  overflow-y: auto;
  overscroll-behavior: contain;
  border: 1px solid var(--yayaw-border);
  border-radius: 6px;
  padding: 4px;
  color: var(--yayaw-foreground);
  background: var(--yayaw-background);
  box-shadow: var(--yayaw-shadow);
  font:
    14px / 1.4 ui-sans-serif,
    system-ui,
    sans-serif;
}
.yayaw-inline-option {
  position: relative;
  display: flex;
  align-items: center;
  border-radius: 4px;
  padding: 6px 32px 6px 8px;
  outline: none;
  cursor: default;
  user-select: none;
}
.yayaw-inline-option[data-highlighted] {
  background: var(--yayaw-muted);
}
.yayaw-inline-option[data-disabled] {
  pointer-events: none;
  opacity: 0.5;
}
.yayaw-inline-check {
  position: absolute;
  right: 8px;
  display: flex;
}
.yayaw-inline-empty {
  padding: 8px;
  text-align: center;
  color: var(--yayaw-muted-foreground);
}
.yayaw-inline-progress {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  height: 2px;
  overflow: hidden;
  border-radius: 999px;
  background: var(--yayaw-muted);
}
.yayaw-inline-progress-bar {
  height: 100%;
  background: var(--yayaw-primary);
  transition: width 75ms;
}
.yayaw-inline-progress.is-saving .yayaw-inline-progress-bar {
  animation: yayaw-inline-pulse 1.5s ease-in-out infinite;
}
@keyframes yayaw-inline-pulse {
  50% {
    opacity: 0.5;
  }
}
@media (prefers-reduced-motion: reduce) {
  .yayaw-inline-progress-bar {
    transition: none;
    animation: none;
  }
}
.yayaw-inline-error,
.yayaw-field-error {
  display: block;
  margin-top: 4px;
  color: var(--yayaw-danger);
  font-size: 12px;
}
.yayaw-code,
.yayaw-json {
  margin: 0;
  border-radius: 4px;
  background: var(--yayaw-muted);
  padding: 2px 5px;
  font-family: ui-monospace, monospace;
  font-size: 12px;
}
.yayaw-json {
  max-width: 360px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.yayaw-number {
  display: block;
  text-align: right;
}
.yayaw-cell-image {
  width: 38px;
  height: 38px;
  border-radius: 6px;
  object-fit: cover;
}
.yayaw-link {
  color: #2563eb;
  text-decoration: none;
}
.yayaw-tags {
  display: inline-flex;
  flex-wrap: wrap;
  gap: 4px;
}
.yayaw-tag {
  display: inline-flex;
  border: 1px solid transparent;
  border-radius: 0.35rem;
  background: var(--yayaw-muted);
  padding: 2px 8px;
  font-size: 12px;
}
.yayaw-boolean {
  display: inline-flex;
  width: 22px;
  height: 22px;
  align-items: center;
  justify-content: center;
  border-radius: 5px;
  background: var(--yayaw-muted);
}
.yayaw-boolean[data-value="true"] {
  background: #dcfce7;
  color: #166534;
}
.yayaw-empty {
  text-align: center;
}
/* Shadcn Empty layout, shared by the table and card displays. */
.yayaw-empty-root {
  box-sizing: border-box;
  display: flex;
  width: 100%;
  min-width: 0;
  min-height: 160px;
  flex: 1;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 16px;
  border-radius: var(--yayaw-radius);
  padding: 40px 16px;
  color: var(--yayaw-foreground);
  text-align: center;
  text-wrap: balance;
  white-space: normal;
}
.yayaw-card-empty {
  border: 1px solid var(--yayaw-border);
}
.yayaw-empty-header {
  display: flex;
  max-width: 384px;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}
.yayaw-empty-media {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  margin-bottom: 8px;
}
.yayaw-empty-media[data-variant="icon"] {
  width: 40px;
  height: 40px;
  border-radius: var(--yayaw-radius);
  background: var(--yayaw-muted);
  color: var(--yayaw-foreground);
}
.yayaw-empty-media svg {
  width: 24px;
  height: 24px;
  flex-shrink: 0;
  pointer-events: none;
}
.yayaw-empty-title {
  font-size: 18px;
  font-weight: 500;
  letter-spacing: -0.025em;
}
.yayaw-empty-description {
  margin: 0;
  color: var(--yayaw-muted-foreground);
  font-size: 14px;
  line-height: 1.625;
}
.yayaw-empty-description > a {
  text-decoration: underline;
  text-underline-offset: 4px;
}
.yayaw-empty-description > a:hover {
  color: var(--yayaw-primary);
}
.yayaw-empty-content {
  display: flex;
  width: 100%;
  max-width: 384px;
  min-width: 0;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  font-size: 14px;
}
.yayaw-empty-reset:focus-visible {
  outline: 2px solid var(--yayaw-primary);
  outline-offset: 2px;
}
.yayaw-calculation small,
.yayaw-calculation strong {
  display: block;
}
.yayaw-calculation small {
  color: var(--yayaw-muted-foreground);
  font-size: 10px;
  text-transform: uppercase;
}
.yayaw-calculation-trigger {
  display: block;
  width: 100%;
  max-width: 100%;
  padding: 2px 4px;
  border: 0;
  border-radius: 4px;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: inherit;
  cursor: pointer;
}
.yayaw-calculation-trigger:hover,
.yayaw-calculation-trigger[data-state="open"] {
  background: var(--yayaw-muted);
}
.yayaw-calculation-trigger:focus-visible {
  outline: 2px solid var(--yayaw-primary);
  outline-offset: 2px;
}
.yayaw-calculation-empty {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--yayaw-muted-foreground);
  font-size: 12px;
}
.yayaw-calculation-menu {
  max-height: var(--reka-dropdown-menu-content-available-height);
  overflow-y: auto;
}
.yayaw-calculation-option {
  justify-content: space-between;
}
.yayaw-pagination {
  justify-content: flex-end;
  min-height: 54px;
  padding: 8px 12px;
}
.yayaw-pagination > span:first-child {
  margin-right: auto;
  color: var(--yayaw-muted-foreground);
}
.yayaw-loading-overlay {
  position: absolute;
  z-index: 20;
  inset: 0;
  display: grid;
  place-items: center;
  border-radius: var(--yayaw-radius);
  background: color-mix(in srgb, var(--yayaw-background) 72%, transparent);
  backdrop-filter: blur(1px);
}
.yayaw-row-actions {
  justify-content: center;
}
.yayaw-row-actions > .yayaw-icon-button {
  width: 32px;
  min-width: 32px;
  height: var(--yayaw-density-control, 32px);
  min-height: var(--yayaw-density-control, 32px);
  padding: 0;
}
.yayaw-row-actions-menu {
  z-index: 90;
  display: grid;
  min-width: 128px;
  gap: 0;
  border: 0;
  border-radius: 6px;
  background: var(--yayaw-background);
  box-shadow:
    0 0 0 1px var(--yayaw-border),
    var(--yayaw-shadow);
  padding: 4px;
  color: var(--yayaw-foreground);
  font:
    14px / 1.4 ui-sans-serif,
    system-ui,
    sans-serif;
}
.yayaw-row-actions-menu,
.yayaw-row-actions-menu * {
  box-sizing: border-box;
}
.yayaw-row-action-item {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  border: 0;
  min-height: 32px;
  border-radius: 4px;
  background: transparent;
  color: inherit;
  padding: 6px 8px;
  text-align: left;
  cursor: pointer;
}
.yayaw-row-action-item:hover,
.yayaw-row-action-item:focus-visible,
.yayaw-row-action-item[data-highlighted] {
  background: var(--yayaw-muted);
  outline: none;
}
.yayaw-row-action-item:disabled,
.yayaw-row-action-item[data-disabled] {
