  opacity: 0.5;
}
.yayaw-row-action-danger {
  color: var(--yayaw-danger);
}
.yayaw-row-actions-divider {
  height: 1px;
  margin: 4px -4px;
  background: var(--yayaw-border);
}
.yayaw-bulk-menu-wrapper {
  z-index: 50;
  display: flex;
  width: 100%;
  justify-content: center;
  pointer-events: none;
  animation: yayaw-bulk-enter 0.3s ease-out;
}
.yayaw-bulk-menu-wrapper[data-position="fixed"] {
  position: fixed;
  right: 0;
  bottom: 24px;
  left: 0;
  padding-inline: 16px;
}
.yayaw-bulk-menu-wrapper[data-position="anchored"] {
  position: relative;
  padding-inline: 0;
}
.yayaw-bulk-anchor {
  width: 100%;
  height: 0;
}
@keyframes yayaw-bulk-enter {
  from {
    transform: translateY(8px);
    opacity: 0;
  }
  to {
    transform: translateY(0);
    opacity: 1;
  }
}
.yayaw-bulk-bar {
  display: flex;
  width: fit-content;
  max-width: 100%;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  border: 1px solid var(--yayaw-border);
  border-radius: 16px;
  background: color-mix(in srgb, var(--yayaw-muted) 95%, transparent);
  box-shadow:
    0 20px 25px -5px rgba(0, 0, 0, 0.1),
    0 8px 10px -6px rgba(0, 0, 0, 0.1);
  padding: 4px;
  backdrop-filter: blur(10px);
  pointer-events: auto;
}
.yayaw-bulk-count {
  display: flex;
  flex: none;
  align-items: center;
  gap: 8px;
  padding-inline: 12px;
  color: var(--yayaw-foreground);
  font-size: 14px;
  white-space: nowrap;
}
.yayaw-bulk-count strong {
  font-weight: 500;
}
.yayaw-bulk-count-dot {
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: var(--yayaw-primary);
  animation: yayaw-pulse 2s ease-in-out infinite;
}
@keyframes yayaw-pulse {
  50% {
    opacity: 0.5;
  }
}
.yayaw-bulk-action-tab {
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  gap: 0;
  border: 0;
  border-radius: 12px;
  background: transparent;
  color: var(--yayaw-muted-foreground);
  padding: 8px;
  font: inherit;
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  transition:
    gap 0.6s cubic-bezier(0.22, 1, 0.36, 1) 0.1s,
    padding 0.6s cubic-bezier(0.22, 1, 0.36, 1) 0.1s,
    background 0.3s ease,
    color 0.3s ease;
}
.yayaw-bulk-action-tab:hover,
.yayaw-bulk-action-tab:focus-visible {
  gap: 8px;
  background: color-mix(in srgb, var(--yayaw-background) 80%, transparent);
  color: var(--yayaw-foreground);
  padding-inline: 16px;
  outline: none;
}
.yayaw-bulk-action-tab:disabled {
  cursor: not-allowed;
  opacity: 0.45;
}
.yayaw-bulk-action-label {
  max-width: 0;
  overflow: hidden;
  opacity: 0;
  white-space: nowrap;
  transition:
    max-width 0.6s cubic-bezier(0.22, 1, 0.36, 1) 0.1s,
    opacity 0.6s cubic-bezier(0.22, 1, 0.36, 1) 0.1s;
}
.yayaw-bulk-action-tab:hover .yayaw-bulk-action-label,
.yayaw-bulk-action-tab:focus-visible .yayaw-bulk-action-label {
  max-width: 160px;
  opacity: 1;
}
.yayaw-bulk-action-danger {
  color: var(--yayaw-danger);
}
.yayaw-bulk-action-fallback {
  font-size: 11px;
  font-weight: 700;
}
.yayaw-bulk-divider {
  width: 1.2px;
  height: 24px;
  flex: none;
  margin-inline: 4px;
  background: var(--yayaw-border);
}
.yayaw-bulk-divider + .yayaw-bulk-action-tab {
  width: 32px;
  height: 32px;
  padding: 0;
}
.yayaw-bulk-divider + .yayaw-bulk-action-tab:hover,
.yayaw-bulk-divider + .yayaw-bulk-action-tab:focus-visible {
  padding: 0;
}
.yayaw-status,
.yayaw-error {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 10px;
  border: 1px solid #fecaca;
  border-radius: var(--yayaw-radius);
  background: #fef2f2;
  color: #991b1b;
  padding: 9px 12px;
}
.yayaw-status[data-type="success"] {
  border-color: #bbf7d0;
  background: #f0fdf4;
  color: #166534;
}
.yayaw-status button {
  border: 0;
  background: transparent;
  color: inherit;
  cursor: pointer;
}
.yayaw-card-view-shell {
  display: grid;
  gap: 12px;
}
.yayaw-card-controls {
  flex-wrap: wrap;
  border: 1px solid var(--yayaw-border);
  border-radius: var(--yayaw-radius);
  background: var(--yayaw-background);
  padding: 8px;
}
/* Shadcn Vue controls share Reka focus, selection, and portal behavior. */
.yayaw-control-field {
  display: inline-flex;
  min-width: 0;
  max-width: 100%;
  align-items: center;
  gap: 8px;
}
.yayaw-control-field > label {
  color: var(--yayaw-muted-foreground);
  font-size: 12px;
  white-space: nowrap;
}
.yayaw-select-trigger,
.yayaw-card-control-button {
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  height: 32px;
  min-height: 32px;
  padding: 6px 10px;
  border: 1px solid var(--yayaw-border);
  border-radius: 6px;
  background: var(--yayaw-background);
  color: var(--yayaw-foreground);
  font: inherit;
  font-size: 13px;
  font-weight: 400;
  box-shadow: 0 1px 2px rgb(0 0 0 / 0.04);
  cursor: pointer;
}
.yayaw-select-trigger {
  min-width: 96px;
  max-width: 220px;
}
.yayaw-select-trigger > span:first-child {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.yayaw-select-trigger > svg {
  flex-shrink: 0;
  color: var(--yayaw-muted-foreground);
}
.yayaw-select-trigger:hover,
.yayaw-card-control-button:hover,
.yayaw-card-control-button[data-state="open"] {
  background: var(--yayaw-muted);
}
.yayaw-select-trigger:focus-visible,
.yayaw-card-control-button:focus-visible,
.yayaw-checkbox:focus-visible,
.yayaw-kanban-move-actions button:focus-visible {
  outline: 2px solid var(--yayaw-primary);
  outline-offset: 2px;
}
.yayaw-select-trigger[data-disabled],
.yayaw-checkbox[data-disabled] {
  opacity: 0.5;
  cursor: not-allowed;
}
.yayaw-select-content {
  /* Above modal dialogs, e.g. the layout choice when saving a view. */
  z-index: 120;
  min-width: var(--reka-select-trigger-width);
  max-width: min(320px, calc(100vw - 16px));
  max-height: min(320px, var(--reka-select-content-available-height));
  overflow: hidden;
}
.yayaw-select-viewport {
  max-height: inherit;
}
.yayaw-select-item,
.yayaw-control-check-item {
  position: relative;
  padding-right: 32px;
  border-radius: 4px;
  user-select: none;
}
.yayaw-control-indicator {
  position: absolute;
  right: 8px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.yayaw-select-scroll {
  display: flex;
  justify-content: center;
  padding: 4px;
}
.yayaw-card-properties-menu {
  width: 224px;
  max-width: calc(100vw - 16px);
  max-height: var(--reka-dropdown-menu-content-available-height);
  overflow-y: auto;
}
.yayaw-control-menu-label {
  padding: 6px 8px;
  font-size: 12px;
  font-weight: 500;
  color: var(--yayaw-muted-foreground);
}
.yayaw-checkbox {
  box-sizing: border-box;
  display: inline-flex;
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: 1px solid var(--yayaw-input);
  border-radius: 4px;
  background: transparent;
  color: var(--yayaw-primary-foreground);
  box-shadow: var(--yayaw-shadow-xs);
  cursor: pointer;
}
.yayaw-checkbox[data-state="checked"] {
  border-color: var(--yayaw-primary);
  background: var(--yayaw-primary);
}
.yayaw-checkbox-indicator {
  display: flex;
  align-items: center;
  justify-content: center;
}
.yayaw-kanban {
  display: grid;
  grid-auto-columns: 18rem;
  grid-auto-flow: column;
  gap: 12px;
  overflow-x: auto;
  border: 1px solid var(--yayaw-border);
  border-radius: var(--yayaw-radius);
  background: var(--yayaw-background);
  padding: 12px;
}
.yayaw-kanban-lane {
  min-height: 28rem;
  overflow: hidden;
  border: 1px solid var(--yayaw-border);
  border-radius: var(--yayaw-radius);
  background: color-mix(
    in oklab,
    var(--yayaw-muted) 20%,
    var(--yayaw-background)
  );
  box-shadow: 0 1px 2px rgb(0 0 0 / 0.05);
}
.yayaw-kanban-lane > header {
  display: flex;
  height: 44px;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--yayaw-border);
  padding: 0 12px;
  font-weight: 500;
}
.yayaw-kanban-lane > header .yayaw-count {
  border-radius: 999px;
  background: var(--yayaw-background);
  padding: 2px 8px;
}
.yayaw-kanban-cards {
  display: grid;
  gap: 8px;
  padding: 8px;
}
.yayaw-card {
  overflow: hidden;
  border: 1px solid var(--yayaw-border);
  border-radius: var(--yayaw-radius);
  background: var(--yayaw-background);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.04);
  transition:
    box-shadow 0.15s,
    transform 0.15s;
}
.yayaw-card:hover,
.yayaw-card:focus {
  border-color: color-mix(
    in oklab,
    var(--yayaw-primary) 40%,
    var(--yayaw-border)
  );
  background: color-mix(
    in oklab,
    var(--yayaw-muted) 20%,
    var(--yayaw-background)
  );
  outline: none;
}
.yayaw-kanban-card {
  padding: 8px;
}
.yayaw-card.pending {
  opacity: 0.55;
}
.yayaw-card-header {
  display: flex;
  align-items: flex-start;
  gap: 8px;
}
.yayaw-card-header strong {
  min-width: 0;
  flex: 1;
  font-size: 14px;
  font-weight: 500;
}
.yayaw-kanban-move-actions {
  display: inline-flex;
  gap: 2px;
}
.yayaw-card-select {
  display: inline-flex;
  align-items: center;
  padding-top: 2px;
  cursor: pointer;
}
.yayaw-card-properties {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  margin: 8px 0 0;
  color: var(--yayaw-muted-foreground);
  font-size: 12px;
}
.yayaw-card-properties:not(.labeled) dd[data-type="number"],
.yayaw-card-properties:not(.labeled) dd[data-type="date"] {
  border-radius: 999px;
  background: color-mix(in oklab, var(--yayaw-muted) 70%, transparent);
  padding: 2px 8px;
  font-size: 11px;
}
.yayaw-card-properties:not(.labeled) dd[data-type="date"] {
  color: var(--yayaw-muted-foreground);
}
.yayaw-card-properties.labeled {
  display: grid;
  grid-template-columns: 5.5rem minmax(0, 1fr);
  gap: 8px;
}
.yayaw-card-properties dt {
  color: var(--yayaw-muted-foreground);
}
.yayaw-card-properties dd {
  min-width: 0;
  overflow: hidden;
  margin: 0;
  color: var(--yayaw-foreground);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.yayaw-gallery-section {
  display: grid;
  gap: 8px;
}
.yayaw-gallery-section > h3 {
  margin: 12px 0 0;
  font-size: 14px;
}
.yayaw-gallery {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 16rem), 1fr));
  gap: 12px;
}
.yayaw-gallery[data-size="small"] {
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 12rem), 1fr));
}
.yayaw-gallery[data-size="large"] {
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 22rem), 1fr));
}
.yayaw-gallery-media {
  position: relative;
  display: grid;
  aspect-ratio: 1;
  place-items: center;
  overflow: hidden;
  background: var(--yayaw-muted);
  color: var(--yayaw-muted-foreground);
  font-size: 18px;
  font-weight: 700;
}
.yayaw-gallery-media[data-ratio="portrait"] {
  aspect-ratio: 3 / 4;
}
.yayaw-gallery-media[data-ratio="video"] {
  aspect-ratio: 16 / 9;
}
.yayaw-gallery-media[data-ratio="wide"] {
  aspect-ratio: 2 / 1;
}
.yayaw-gallery-media img {
  width: 100%;
  height: 100%;
}
.yayaw-gallery-media .yayaw-card-select {
  position: absolute;
  top: 9px;
  left: 9px;
  display: grid;
  width: 28px;
  height: 28px;
  place-items: center;
  border-radius: 6px;
  background: color-mix(in srgb, var(--yayaw-background) 85%, transparent);
}
.yayaw-gallery-body {
  padding: 12px;
}
.yayaw-dialog-backdrop {
  position: fixed;
  z-index: 100;
  inset: 0;
  display: flex;
  align-items: stretch;
  justify-content: flex-end;
  /* Match React's bg-black/10 and backdrop-blur-xs, including host blur tokens. */
  background: rgba(0, 0, 0, 0.1);
  -webkit-backdrop-filter: blur(var(--blur-xs, 4px));
  backdrop-filter: blur(var(--blur-xs, 4px));
}
.yayaw-form-surface {
  width: min(620px, 94vw);
  height: 100%;
  overflow: auto;
  background: var(--yayaw-background);
  color: var(--yayaw-foreground);
  max-width: 100vw;
  box-shadow: var(--yayaw-shadow);
}
.yayaw-form-surface[data-presentation="modal"] {
  height: fit-content;
  max-height: 90vh;
  margin: auto;
  border-radius: 12px;
}
.yayaw-confirm-surface {
  width: min(460px, 92vw);
}
.yayaw-confirm-body {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  padding: 18px 20px;
}
.yayaw-bulk-editor {
  display: grid;
  justify-content: stretch;
}
.yayaw-json-editor {
  font-family: ui-monospace, monospace;
}
.yayaw-form-header {
  position: sticky;
  z-index: 2;
  top: 0;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  border-bottom: 1px solid var(--yayaw-border);
  background: var(--yayaw-background);
  padding: 18px 20px;
}
.yayaw-form-header h3,
.yayaw-form-section h4 {
  margin: 0;
}
.yayaw-form-header p,
.yayaw-form-section header p {
  margin: 4px 0 0;
  color: var(--yayaw-muted-foreground);
}
.yayaw-form {
  display: grid;
  gap: 20px;
  padding: 20px;
}
.yayaw-form-fields {
  container: yayaw-form / inline-size;
  display: grid;
  gap: 20px;
  min-width: 0;
  padding: 0;
  margin: 0;
  border: 0;
}
.yayaw-collection-table-wrap {
  max-width: 100%;
  overflow-x: auto;
}
.yayaw-collection-table {
  width: 100%;
  border-collapse: collapse;
}
.yayaw-collection-table th,
.yayaw-collection-table td {
  padding: 8px;
  border-bottom: 1px solid var(--yayaw-border);
  text-align: start;
}
.yayaw-form-section {
  display: grid;
  gap: 12px;
}
.yayaw-form-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 14px;
}
.yayaw-form-block-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 16px;
}
.yayaw-form-block {
  min-width: 0;
}
.yayaw-form-block > .yayaw-form-section,
.yayaw-form-content {
  border: 1px solid var(--yayaw-border);
  border-radius: 6px;
  padding: 16px;
}
.yayaw-form-content {
  background: var(--yayaw-muted);
}
.yayaw-form-content[data-tone="warning"] {
  border-color: #f59e0b66;
  background: #f59e0b1a;
}
.yayaw-form-content p {
  white-space: pre-wrap;
}
.yayaw-form-block h3,
.yayaw-form-block p {
  margin: 0;
}
.yayaw-form-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: start;
  gap: 8px;
}
@container yayaw-form (min-width: 28rem) {
  .yayaw-form-grid {
    grid-template-columns: repeat(var(--columns), minmax(0, 1fr));
  }
  .yayaw-form-block-grid {
    grid-template-columns: repeat(var(--form-columns), minmax(0, 1fr));
  }
  .yayaw-form-block {
    grid-column: span var(--form-span);
  }
  .yayaw-form-block[data-full-span="true"] {
    grid-column: 1 / -1;
  }
}
.yayaw-form-field {
  min-width: 0;
}
.yayaw-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
.yayaw-label {
  display: block;
  margin-bottom: 5px;
  font-weight: 550;
}
.yayaw-form-field > .yayaw-input,
.yayaw-form-field > .yayaw-select {
  width: 100%;
}
.yayaw-add-select,
.yayaw-inline-group {
  width: 100%;
}
.yayaw-inline-group > .yayaw-input,
.yayaw-inline-group > .yayaw-select {
  min-width: 0;
  flex: 1;
}
.yayaw-options-grid {
  display: grid;
  gap: 7px;
}
.yayaw-table-picker {
  min-width: 0;
}
.yayaw-table-picker .yayaw-table-scroll {
  max-height: var(--yayaw-table-picker-max-height, 480px);
}
.yayaw-checkbox-label,
.yayaw-switch {
  display: flex;
  align-items: center;
  gap: 7px;
  cursor: pointer;
}
.yayaw-collection {
  display: grid;
  gap: 10px;
}
.yayaw-collection-item {
  position: relative;
  display: grid;
  gap: 10px;
  border: 1px solid var(--yayaw-border);
  border-radius: var(--yayaw-radius);
  padding: 12px;
}
.yayaw-collection-actions {
  display: flex;
  justify-content: flex-end;
}
.yayaw-form-footer {
  position: sticky;
  bottom: 0;
  justify-content: flex-end;
  border-top: 1px solid var(--yayaw-border);
  background: var(--yayaw-background);
  padding-top: 14px;
}
@media (max-width: 760px) {
  .yayaw-toolbar-row {
    align-items: stretch;
  }
  .yayaw-toolbar-left,
  .yayaw-toolbar-right,
  .yayaw-search {
    width: 100%;
  }
  .yayaw-toolbar-right > * {
    flex: 1;
  }
  .yayaw-form-grid {
    grid-template-columns: 1fr;
  }
  .yayaw-bulk-bar {
    border-radius: 16px;
  }
  .yayaw-pagination {
    flex-wrap: wrap;
    justify-content: center;
  }
}

/* Match the shared Tailwind spacing scale without inflating compact rows. */
.yayaw-data-grid .yayaw-row-actions > .yayaw-icon-button {
  width: var(--yayaw-density-control);
  min-width: var(--yayaw-density-control);
  height: var(--yayaw-density-control);
  min-height: var(--yayaw-density-control);
}
.yayaw-data-grid .yayaw-cell-image {
  display: block;
  width: var(--yayaw-density-control);
  height: var(--yayaw-density-control);
}
.yayaw-data-grid .yayaw-inline-editor {
  min-height: var(--yayaw-density-control);
  padding-block: 0;
}
.yayaw-data-grid .yayaw-column-resize-handle {
  top: calc(-1 * var(--yayaw-density-py));
  right: calc(-1 * var(--yayaw-density-px));
  bottom: calc(-1 * var(--yayaw-density-py));
}
.yayaw-density-menu {
  min-width: 128px;
}
.yayaw-density-label {
  padding: 6px 8px;
  color: var(--yayaw-muted-foreground);
  font-size: 12px;
}
.yayaw-density-option {
  justify-content: space-between;
}

.yayaw-tooltip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  z-index: 100;
  width: fit-content;
  max-width: 320px;
  transform-origin: var(--reka-tooltip-content-transform-origin);
  border-radius: 0.375rem;
  padding: 0.375rem 0.75rem;
  background: var(--yayaw-foreground);
  color: var(--yayaw-background);
  font:
    12px / 16px ui-sans-serif,
    system-ui,
    sans-serif;
  box-shadow: var(--yayaw-shadow);
  overflow-wrap: break-word;
}
.yayaw-tooltip-arrow {
  z-index: 100;
  width: 10px;
  height: 10px;
  background: var(--yayaw-foreground);
  fill: var(--yayaw-foreground);
  transform: translateY(calc(-50% - 2px)) rotate(45deg);
  border-radius: 2px;
}

.yayaw-image-placeholder {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: var(--muted);
  color: var(--muted-foreground);
  border: 1px solid var(--border);
}

.yayaw-filter-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 16px;
}
.yayaw-filter-trigger {
  max-width: 100%;
  gap: 0.5rem;
  font-weight: 400;
}
.yayaw-filter-trigger > span:first-of-type {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.yayaw-filter-trigger > svg {
  flex-shrink: 0;
}
.yayaw-filter-count {
  border-radius: 0.25rem;
  background: var(--yayaw-muted);
  padding: 0 0.375rem;
  font-size: 0.75rem;
}
.yayaw-filter-picker {
  z-index: 3000;
  display: grid;
  gap: 0.5rem;
  width: min(18rem, calc(100vw - 1rem));
  max-height: var(--reka-popover-content-available-height);
  overflow: auto;
  padding: 0.75rem;
  border: 1px solid var(--yayaw-border);
  border-radius: var(--yayaw-radius);
  background: var(--yayaw-background);
  color: var(--yayaw-foreground);
  box-shadow: var(--yayaw-shadow);
  box-sizing: border-box;
  font-size: 0.875rem;
}
.yayaw-filter-heading {
  margin: 0;
  font-weight: 500;
}
.yayaw-filter-choices {
  max-height: 15rem;
  overflow: auto;
}
.yayaw-filter-choice {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.375rem 0.5rem;
  border-radius: 0.25rem;
  cursor: pointer;
}
.yayaw-filter-choice:hover {
  background: var(--yayaw-muted);
}
.yayaw-filter-choice:has(input:disabled) {
  opacity: 0.5;
