  now?: Date;
}

const DATE_ONLY = /^\d{4}-\d{2}-\d{2}$/;

/** Date-only strings are calendar days in local time; other values are instants. */
export function parseDateValue(value: unknown): Date | undefined {
  if (value === null || value === undefined || value === "") {
    return;
  }
  let date: Date;
  if (value instanceof Date) {
    date = value;
  } else if (typeof value === "string") {
    date = DATE_ONLY.test(value)
      ? new Date(`${value}T00:00:00`)
      : parseISO(value);
    if (!isValid(date)) {
      // Formats the browser accepted before, such as "2026/09/05".
      date = new Date(value);
    }
  } else {
    date = new Date(value as number);
  }
  return isValid(date) ? date : undefined;
}

const RELATIVE_UNITS: [Intl.RelativeTimeFormatUnit, number][] = [
  ["year", 31_536_000],
  ["month", 2_592_000],
  ["week", 604_800],
  ["day", 86_400],
  ["hour", 3600],
  ["minute", 60],
  ["second", 1],
];

function relative(date: Date, locale: string | undefined, now: Date): string {
  const seconds = (date.getTime() - now.getTime()) / 1000;
  const [unit, size] = RELATIVE_UNITS.find(
    ([, length]) => Math.abs(seconds) >= length
  ) ??
    RELATIVE_UNITS.at(-1) ?? ["second", 1];
  return new Intl.RelativeTimeFormat(locale, { numeric: "auto" }).format(
    Math.round(seconds / size),
    unit
  );
}

const INTL_PRESETS: Partial<
  Record<DateDisplayPreset, Intl.DateTimeFormatOptions>
> = {
  "localized-short": { dateStyle: "short" },
  short: { dateStyle: "short" },
  "localized-medium": { dateStyle: "medium" },
  date: { dateStyle: "medium" },
  "localized-long": { dateStyle: "long" },
  long: { dateStyle: "full" },
  "month-name-long": { day: "2-digit", month: "long", year: "numeric" },
  "month-year": { month: "long", year: "numeric" },
  dateTime: { dateStyle: "medium", timeStyle: "short" },
  time: { timeStyle: "short" },
};

function numericParts(date: Date, timeZone?: string) {
  const parts = new Intl.DateTimeFormat("en-US", {
    day: "2-digit",
    month: "2-digit",
    year: "numeric",
    timeZone,
  }).formatToParts(date);
  const get = (type: string) =>
    parts.find((part) => part.type === type)?.value ?? "";
  return { day: get("day"), month: get("month"), year: get("year") };
}

function numericPreset(
  preset: DateDisplayPreset,
  date: Date,
  timeZone?: string
): string | undefined {
  const { day, month, year } = numericParts(date, timeZone);
  const short = year.slice(-2);
  switch (preset) {
    case "dmy-numeric":
      return `${day}/${month}/${year}`;
    case "dmy-short":
      return `${day}/${month}/${short}`;
    case "mdy-numeric":
      return `${month}/${day}/${year}`;
    case "mdy-short":
      return `${month}/${day}/${short}`;
    case "iso-date":
      return `${year}-${month}-${day}`;
    default:
      return;
  }
}

export function formatDateValue(
  value: unknown,
  options: ColumnDateFormat = {}
): string {
  if (value === null || value === undefined || value === "") {
    return "—";
  }
  const date = parseDateValue(value);
  if (!date) {
    return String(value);
  }
  if (options.pattern) {
    return formatPattern(date, options.pattern);
  }
  const preset = options.preset ?? "localized-short";
  if (preset === "iso") {
    return date.toISOString();
  }
  if (preset === "relative") {
    return relative(date, options.locale, options.now ?? new Date());
  }
  const numeric = numericPreset(preset, date, options.timeZone);
  if (numeric) {
    return numeric;
  }
  return new Intl.DateTimeFormat(options.locale, {
    ...(INTL_PRESETS[preset] ?? INTL_PRESETS["localized-short"]),
    hour12: options.hour12,
    timeZone: options.timeZone,
  }).format(date);
}

import {
  DISPLAY_MODE_CONFIG_KEYS,
  DISPLAY_MODES,
  resolveDisplayModes,
  type TableDisplayMode,
} from "./display-modes";
import {
  normalizeFilterEnvelope,
  normalizeViewAliases,
} from "./table-contracts";

/** These capabilities describe presentation, before catalogue permissions apply. */
export function getViewModeCapabilities(mode: TableDisplayMode) {
  const definition = DISPLAY_MODES[mode] ?? DISPLAY_MODES.table;
  return {
    ...definition.capabilities,
    kanban: mode === "kanban",
    gallery: mode === "gallery",
    gantt: mode === "gantt",
    maxGroups: definition.maxGroups,
  } as const;
}

/**
 * Gantt needs a planning graph the way Kanban needs a grouping column: offering the
 * mode without one only leads to an empty view, so it is withheld until it can render.
 */
export function availableDisplayModes(
  displayModes: readonly unknown[] | undefined,
  context: { planning: boolean; renderers?: readonly string[] }
): TableDisplayMode[] {
  return resolveDisplayModes(displayModes, context);
}

const VIEW_SETTING_KEYS = [
  ...DISPLAY_MODE_CONFIG_KEYS,
  "advancedFilters",
  "columnFilters",
  "columnOrder",
  "columnPinning",
  "columnSizing",
  "columnVisibility",
  "density",
  "displayMode",
  "footerCalculationsVisible",
  "globalSearch",
  "grouping",
  "pageSize",
  "sorting",
];

function canonicalValue(value: unknown, field?: string): unknown {
  if (value instanceof Date) {
    return value.toJSON() ?? undefined;
  }
  if (Array.isArray(value)) {
    return value.length || field === "cardColumnIds"
      ? value.map((item) => canonicalValue(item))
      : undefined;
  }
  if (value !== null && typeof value === "object") {
    const result: Record<string, unknown> = {};
    for (const key of Object.keys(value).sort()) {
      const normalized = canonicalValue(
        (value as Record<string, unknown>)[key],
        key
      );
      if (normalized !== undefined) {
        result[key] = normalized;
      }
    }
    return Object.keys(result).length ? result : undefined;
  }
  return value === null || (value === "" && field !== "imageColumn")
    ? undefined
    : value;
}

/** Compare saved settings, excluding transient selection, pages and UI state. */
export function areViewSettingsEqual(left: object, right: object): boolean {
  const normalize = (input: object) => {
    const aliases = normalizeViewAliases(input);
    const settings: Record<string, unknown> = {};
    for (const key of VIEW_SETTING_KEYS) {
      settings[key] = aliases[key];
    }
    // Selection and action columns are positioned by the table, including in legacy views.
    if (Array.isArray(settings.columnOrder)) {
      settings.columnOrder = settings.columnOrder.filter(
        (id) => id !== "select" && id !== "actions"
      );
    }
    // Filter identities and edit timestamps do not change the saved query's meaning.
    settings.advancedFilters = normalizeFilterEnvelope(
      aliases.advancedFilters
    ).filters.map(
      ({
        id: _id,
        label: _label,
        createdAt: _createdAt,
        updatedAt: _updatedAt,
        ...filter
      }) => ({
        ...filter,
        joinOperator: filter.joinOperator === "or" ? "or" : undefined,
      })
    );
    // An explicit visible column has the same meaning as an absent override.
    if (
      settings.columnVisibility &&
      typeof settings.columnVisibility === "object"
    ) {
      settings.columnVisibility = Object.fromEntries(
        Object.entries(settings.columnVisibility).filter(
          ([, visible]) => visible === false
        )
      );
    }
    return canonicalValue(settings);
  };
  return JSON.stringify(normalize(left)) === JSON.stringify(normalize(right));
}

export interface PageSharingEnvironment {
  share?: (data: { url: string }) => Promise<void>;
  clipboard?: { writeText: (text: string) => Promise<void> };
}

export type PageShareResult = "shared" | "copied" | "cancelled";

/** Sharing a URL never grants access or changes a saved view's organization scope. */
export async function sharePageUrl(
  url: string,
  native: boolean,
  environment: PageSharingEnvironment = navigator
): Promise<PageShareResult> {
  if (native && typeof environment.share === "function") {
    try {
      await environment.share({ url });
      return "shared";
    } catch (error) {
      if (error instanceof Error && error.name === "AbortError") {
        return "cancelled";
      }
      if (!environment.clipboard?.writeText) {
        throw error;
      }
    }
  }
  if (!environment.clipboard?.writeText) {
    throw new Error("Link sharing is unavailable in this browser.");
  }
  await environment.clipboard.writeText(url);
  return "copied";
}

/**
 * View tabs shared by the React and Vue editions: which saved views show as
 * tabs and which move to the "More" menu.
 */

export interface ViewTabsSettings {
  /** Tabs shown before the rest move to the "More" menu (default 4). */
  maxVisible?: number;
}

/** `table.viewTabs`: `false` keeps the view menu only. */
export type ViewTabsConfig = boolean | ViewTabsSettings;

export const DEFAULT_VIEW_TABS_MAX_VISIBLE = 4;

/** Resolved tab settings, or `undefined` when tabs are turned off. */
export function resolveViewTabs(
  config: ViewTabsConfig | undefined
): Required<ViewTabsSettings> | undefined {
  if (config === false) {
    return;
  }
  const requested = typeof config === "object" ? config.maxVisible : undefined;
  const maxVisible =
    typeof requested === "number" &&
    Number.isInteger(requested) &&
    requested > 0
      ? requested
      : DEFAULT_VIEW_TABS_MAX_VISIBLE;
  return { maxVisible };
}

/**
 * Split views into visible tabs and the overflow menu, keeping their order.
 * The active view always stays visible, in place of the last visible tab.
 */
export function splitViewTabs<TView extends { id: string }>(
  views: readonly TView[],
  activeId: string | null | undefined,
  maxVisible: number
): { visible: TView[]; overflow: TView[] } {
  if (views.length <= maxVisible) {
    return { visible: [...views], overflow: [] };
  }
  const visible = views.slice(0, maxVisible);
  const active = views.find((view) => view.id === activeId);
  if (active && !visible.includes(active)) {
    visible[visible.length - 1] = active;
  }
  return {
    visible,
    overflow: views.filter((view) => !visible.includes(view)),
  };
}
